SELECT 'moj-all-verified-judgments-review-002-chunk-183' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c3692dd3-0e5a-54f9-9c18-4272341d58aa","document_type":"judgment","category":"judicial","subcategory":"general","title":"سمسرة -مطالبة بإعادة عربون -السمسار يستحق السعي بالتوفيق بن الطرفن -ال يسترد السعي بفسخ البيع -صرف النظر عن دعوى املدعي.","document_number":"33313847","case_number":"32191693","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة احلقوقية اخلامسة مبحكمة الاستئناف بالرياض.","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/24","year":"1434","subject":"سمسرة -مطالبة بإعادة عربون -السمسار يستحق السعي بالتوفيق بن الطرفن -ال يسترد السعي بفسخ البيع -صرف النظر عن دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33313847:‬تاريخه‪1433/6/24:‬هـ‬\n                  ‫رقم الدعوى‪32191693:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3429191‬تاريخه‪1434/2/4 :‬هـ‬\n\n\n‫سمســرة ‪ -‬مطالبــة بإعــادة عربــون ‪ -‬السمســار يســتحق الســعي‬\n‫بالتوفيــق بــن الطرفــن ‪ -‬ال يســترد الســعي بفســخ البيــع ‪ -‬صــرف‬\n                                         ‫النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n‫‪ .1‬جــاء يف شــرح منتهــى اإلرادات ‪( 153/5‬ومــن قبــض شــيئ ًا بســبب عقــد‬\n‫كــدالل يف بيــع فــإن فســخ البيــع باإلقالــة ونحوهــا ممــا يقــف علــى‬\n                                              ‫تــراض الطرفــن لــم يــرده)‪.‬‬\n‫‪ .2‬جــاء يف جامــع الفصولــن ‪(211/2‬لــو اســتحق املبيــع أو رد بعيــب ال‬\n                                                           ‫تســترد الداللــة)‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه وكالــة بــأن موكلــه رغــب‬\n‫بشــراء فلــة عــن طريــق مكتــب عقــاري عائــد ملــوكل املدعــى عليــه‬\n‫وذلــك مببلــغ أربعــة ماليــن ومائتــي ألــف ريــال وبعــد أن وافــق البائــع علــى‬\n‫البيــع رجــع موكلــه وطلــب اإلقالــة مــن البائــع ووافــق البائــع وقــد ســلم‬\n‫موكلــه مبلــغ مائــة ألــف ريــال عربــون شــراء الفلــة مبوجــب شــيك وقــد‬\n‫صــدر علــى موكلــه احلكــم بدفــع املبلــغ مــن مكتــب الفصــل يف األوراق‬\n‫التجاريــة ومبــا أن البيــع ُفســخ يطلــب إلــزام املدعــى عليــه بعــدم اســتالم‬\n\n                                                                                       ‫‪104‬‬\n\f      ‫املبلــغ وإعــادة الشــيك املرفــق باملعاملــة هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n      ‫عليــه باملصادقــة علــى الدعــوى وعلــى صــدور حكــم ملوكلــه بالشــيك‬\n      ‫محــل الدعــوى مــن مكتــب الفصــل يف األوراق التجاريــة وموكلــه يطلب‬\n      ‫تســليمه الشــيك ورد الدعــوى ‪ -‬جــرى ســؤال املدعــي هــل اإلقالــة حصلت‬\n      ‫بعــد إمتــام البيــع فأجــاب باملصادقــة وأنهــا حصلــت بعــد اإليجــاب والقبــول‬\n      ‫وأن مالــك العقــار قــد تنــازل عــن العربــون وكتــب إقــرار بذلــك ‪ -‬قــرر‬\n      ‫املدعــي أصالــة بــأن ســعي الفيــا فيمــا لــو مت البيــع مبلــغ وقــدره مائــة‬\n      ‫وخمســة وعشــرون ألــف ريــال وصادقــه املدعــى عليــه علــى ذلــك ‪ -‬ومبــا‬\n      ‫أن املدعــي قــد أقــر بــأن اإلقالــة حصلــت بعــد إمتــام البيــع وأن الســعي‬\n      ‫حســب العــرف مبلــغ وقــدره مائــة وخمســة وعشــرون ألــف ريــال ‪ -‬ومبــا أن‬\n      ‫السمســار يســتحق الســعي بالتوفيــق بــن الطرفــن ‪ -‬ملــا قــرره أهــل العلــم‬\n      ‫انظــر شــرح منتهــى اإلرادات ‪ 153/5‬وجامــع الفصولــن ‪ - 211/2‬ملــا‬\n      ‫تقــدم صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه‬\n      ‫مــا يدعيــه ‪ -‬وتســليم الشــيك الــذي يف املعاملــة للمدعــى عليــه ‪ -‬قنــع‬\n      ‫املدعــى عليــه باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن‬\n                   ‫الدائــرة احلقوقيــة اخلامســة مبحكمــة االســتئناف بالريــاض‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬لقاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32191693‬وتاريــخ ‪1432/05/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32599387‬وتاريــخ ‪1432/05/23‬ه ـ واملنقوضــة‬\n      ‫ســابقا مــن محكمــة االســتئناف بقــرار رقــم ‪/347‬ق‪ /5‬ب يف‬\n\n‫‪105‬‬\n\f‫‪1432/4/11‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1433/06/24‬ه ـ حضــر‬\n‫‪ ........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ) ........‬بصفتــه وكيــا عــن‬\n‫‪ ........‬نــوب عنــه يف املطالبــة واملرافعــة واملدافعــة وطلــب اليمــن واإلقــرار‬\n‫واإلنــكار وقبــول احلكــم ونفيــه واالعتــراض عليــه ومتييــزه واالســتالم‬\n‫والتســليم مبوجــب صــك وكالــة صــادر مــن كتابــة عــدل الدرعيــة‬\n‫برقــم ‪ 410602062171‬يف ‪1431/6/26‬ه ـ وادعــى علــى احلاضــر معــه‬\n‫‪ ........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ) ........‬بصفتــه وكيــا‬\n‫عــن ‪ ........‬ينــوب عنــه يف املطالبــة واملرافعــة واملدافعــة وطلــب اليمــن‬\n‫واإلقــرار واإلنــكار والصلــح وقبــول احلكــم ونفيــه واالعتــراض عليــه‬\n‫وطلــب متييــزه واالســتالم والتســليم مبوجــب صــك وكالــة صــادر مــن‬\n‫كتابــة عــدل الريــاض الثانيــة رقــم ‪ 43946‬يف ‪1431/6/11‬ه ـ قائــا‬\n‫يف حتريــر دعــواه عليــه‪ :‬إن موكلــي رغــب يف شــراء فيــا تقــع يف حــي‬\n‫الواحــة مبدينــة الريــاض والعائــدة للمدعــو ‪ ........‬عــن طريــق مكتــب‬\n‫‪ ........‬العائــد ملــوكل هــذا وأشــار إلــى املدعــى عليــه وذلــك مببلــغ‬\n‫أربعــة ماليــن ومائتــي ألــف ريــال وبعــد أن وافــق البائــع علــى البيــع رجــع‬\n‫موكلــي وطلــب اإلقالــة مــن البائــع ووافــق وقــد دفــع موكلــي مبلــغ مائــة‬\n‫ألــف ريــال عربــون شــراء الفيــا مبوجــب شــيك وصــدر علــى موكلــي‬\n‫احلكــم مــن مكتــب الفصــل يف األوراق التجاريــة ونفــذ احلكــم حيــث‬\n‫ســلم هــذا املبلــغ جلهــة قاضــي التنفيــذ مبوجــب شــيك مرفــق باملعاملــة‬\n‫وحيــث أن هــذا املبلــغ سيســلم للمدعــى عليــه بــدون حــق نظــرا ألن البيــع‬\n‫فســخ أطلــب إلــزام املدعــى عليــه بعــدم اســتالم املبلــغ وإعــادة الشــيك‬\n‫املرفــق باملعاملــة الــذي سيســلم لــه وقــدره (‪ )100000‬حيــث حــرر علــى‬\n‫أنــه عربــون وليــس مــن حقــه االحتفــاظ بــه ألنــه ليــس البائــع وإمنــا دالل‬\n\n\n                                                                                       ‫‪106‬‬\n\f      ‫للبيــع هــذه دعــواي وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي مــن أن موكلــه ســلم ملوكلــي الشــيك‬\n      ‫املذكــور يف دعــواه مببلــغ مائــة ألــف ريــال عربــون شــراء فيــا مــن‬\n      ‫الشــخص املذكــور هــذا صحيــح والشــيك محــل الدعــوى قــد صــدر‬\n      ‫بــه حكــم مــن مكتــب الفصــل يف األوراق التجاريــة بالريــاض برقــم‬\n      ‫‪ 1496‬يف ‪1430/6/15‬ه ـ وهــو حكــم مكتســب القطعيــة وهــو اآلن يف‬\n      ‫التنفيــذ وموكلــي يطلــب تســليمه الشــيك لــذا أطلــب رد دعــوى املدعــي‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة رد قائــا صحيــح‬\n      ‫أنــه ســبق أن صــدر احلكــم املذكــور ولكنــه لــم يتطــرق إلــى موضــوع‬\n      ‫الشــيك وإمنــا بنــاء علــى الشــيك أداة وفــاء جتــري مجــرى النقــود يف الوفــاء‬\n      ‫وموكلــي يطالــب بــرد الشــيك ألنــه حــرر علــى أنــه عربــون وليــس مــن‬\n      ‫حقــه االحتفــاظ بــه والســعي الــذي يطالــب بــه صاحــب املكتــب يكــون‬\n      ‫حســب العــرف والصحيــح أن موكلــي اســتلم هــذا املبلــغ علــى أن يكــون‬\n      ‫ســعي يف حــال انعقــاد البيــع ثــم إن موكلــي قــد اشــترط شــرطا علــى‬\n      ‫أن املبلــغ يفقــد يف حــال تراجــع املشــتري أو املســتأجر واملؤمنــون علــى‬\n      ‫شــروطهم فطلــب مــن الطرفــن القــرار الصــادر مــن مكتــب الفصــل‬\n      ‫فأحضــر يف هــذه اجللســة القــرار املذكــور برقــم ‪ 30/1496‬وتاريــخ‬\n      ‫‪1430/6/15‬ه ـ واملكــون مــن ثالثــة أوراق وقــد جــرى االطــاع عليــه‬\n      ‫فجــرى ســؤال املدعــي أصالــة هــل اإلقالــة حصلــت بعــد إمتــام البيــع قــال‬\n      ‫هــذا صحيــح فبعــد اإليجــاب والقبــول تراجعــت عــن الشــراء وعرضــت‬\n      ‫ذلــك علــى املالــك ووافــق وعلــى هــذا ال يســتحق الوســيط املبلــغ الــذي‬\n      ‫حــرر يف الشــيك وأبــرز ورقــة نصهــا إقــرار بالتنــازل ( أقــر أنــا ‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم (‪ ) ........‬وأنــا بكامــل قواي‬\n\n\n‫‪107‬‬\n\f‫العقليــة ويف متــام أهليتــي املعتبــرة شــرعا ونظامــا بأننــي تنازلــت لــأخ‬\n‫‪ ........‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم (‪ ) ........‬عــن العربــون‬\n‫الــذي ســبق وأن صــدر بــه شــيك رقــم ‪ 301162‬بتاريــخ ‪2008/9/23‬م‬\n‫مببلــغ قــدره مائــة ألــف ريــال علــى بنــك ‪ ........‬إلــى ‪ ........‬صاحــب‬\n‫مكتــب ‪ ........‬بشــأن مفاوضــات شــراء الفيــا العائــدة لنــا ومســاحتها‬\n‫(‪800‬م‪ )2‬ثمامنائــة متــر مربــع يف حــي ‪ ........‬علمــا أن مفاوضــات الشــراء‬\n‫املذكــورة لــم يتــم عليهــا أي شــيء وهــذا تنــازل منــي بذلــك املقــر مبــا‬\n‫فيــه املتنــازل ‪ ........‬توقيعــه بتاريــخ ‪1431/4/27‬ه ـ الشــاهد األول ‪........‬‬\n‫‪ ........‬توقعيــه الشــاهد الثانــي ‪ ........‬توقيعه)‪.‬أه ـ فجــرى ســؤال املدعــي‬\n‫أصالــة عــن ثمــن الفيــا املشــتراة فقــال مبلــغ أربعــة ماليــن ومائتــي ألــف‬\n‫ريــال فجــرى ســؤاله عــن الســعي لهــذا املبلــغ لــو مت البيــع قــال الســعي‬\n‫حســب العــرف مبلــغ مائــة وخمســة وعشــرين ألــف ريــال وصــادق املدعــى‬\n‫عليــه علــى ذلــك فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وبنــاء علــى ما‬\n‫أقــر بــه املدعــي مــن أن اإلقالــة حصلــت بعــد إمتــام البيــع وأن ثمــن العقــار‬\n‫مبلــغ أربعــة ماليــن ومائتــي ألــف ريــال والســعي مبلــغ مائــة وخمســة‬\n‫وعشــرين ألــف ريــال حســب العــرف ومبــا أن السمســار يســتحق الســعي‬\n‫بالتوفيــق بــن الطرفــن ومبــا أنــه قــد مت البيــع بإقــرار املدعــي وملــا قــرره‬\n‫أهــل العلــم قــال يف منتهــى اإلرادات (‪ ()153/5‬ومــن قبــض شــيئا بســبب‬\n‫عقــد كــدالل يف بيــع فــإن فســخ البيــع باإلقالــة ونحوهــا ممــا يقــف‬\n‫علــى تــراض الطرفــن لــم يــرده) ويف جامــع الفصولــن (‪ ( )211/2‬لــو‬\n‫اســتحق املبيــع أو رد بعيــب ال تســترد الداللــه) جلميــع ذلــك فقــد صرفــت‬\n‫النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه مــا يدعيــه وامــرت بتســليم‬\n‫الشــيك املرفــق باملعاملــة للمدعــى عليــه وبذلــك حكمــت وبعرضــه علــى‬\n\n\n                                                                                        ‫‪108‬‬\n\f      ‫الطرفــن قنــع املدعــى عليــه ولــم يقنــع املدعــي وطالــب بتمييــزه واســتعد‬\n      ‫بتقــدمي الئحــة اعتراضيــة وأفهــم بــأن عليــه تقــدمي اعتراضــه خــال ثالثني‬\n      ‫يومــا مــن اآلن وإذا انتهــت املــدة احملــددة لالعتــراض ولــم يقــدم شــيئا‬\n      ‫ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1433/06/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n      ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n      ‫‪ 32599387‬وتاريــخ ‪1434/1/7‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ......../‬برقــم ‪ 33313847‬وتاريــخ‬\n      ‫‪1433/6/24‬ه ـ اخلــاص بدعــوى‪ ......../‬ضــد‪ ......../‬يف مبلــغ مــن املــال‬\n      ‫علــى الصفــة املوضحــة يف الصــك واملتضمــن حكــم فضيلتــه كمــا هــو‬\n      ‫موضــح بالصــك وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضية‬\n      ‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم‪ .‬واهلل‬\n                    ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪109‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":104,"source_page_end":109,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1f1d5f42f754d4df34a710b1a7e9dc2aed13cddc6cde31575e36c81bf6bee5ac","normalized_text_hash":"fca0868a424073876dfd321abbed53901db614262ebf1b916a64229c21cd6261","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p104-33313847"},{"id":"ca6ed427-e0ae-56e0-9764-9fc6db3453d4","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب -أتعاب محاماة -مرافعة وإنهاء اإلجراءات ومتابعة لدى اجلهات -عقد جعالة -األتعاب نسبة من احلق -وفاة احملامي وانتقال حقه لورثته -عدم حتديد األتعاب كتابة قبل البدء يف العمل- إبرام عقد اتفاق بن احملامي وورثة املوكل ملزم للطرفن -إنهاء احملامي العمل وإعادة احلق ينفي حدوث ضرر ملوكله -استطالع رأي أهل اخلبرة يف تقدير األتعاب -إقرار الوكيل ملزم للموكل .","document_number":"34220573","case_number":"32223955","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/22","year":"1434","subject":"أتعاب -أتعاب محاماة -مرافعة وإنهاء اإلجراءات ومتابعة لدى اجلهات -عقد جعالة -األتعاب نسبة من احلق -وفاة احملامي وانتقال حقه لورثته -عدم حتديد األتعاب كتابة قبل البدء يف العمل- إبرام عقد اتفاق بن احملامي وورثة املوكل ملزم للطرفن -إنهاء احملامي العمل وإعادة احلق ينفي حدوث ضرر ملوكله -استطالع رأي أهل اخلبرة يف تقدير األتعاب -إقرار الوكيل ملزم للموكل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34220573 :‬تاريخه‪1434/5/22 :‬هـ‬\n                   ‫رقم الدعوى‪32223955 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34316063‬تاريخه‪1434/9/9 :‬هـ‬\n\n\n‫أتعــاب ‪ -‬أتعــاب محامــاة‪ -‬مرافعــة وإنهــاء اإلجــراءات ومتابعــة لــدى‬\n‫اجلهات‪ -‬عقد جعالة‪ -‬األتعاب نسبة من احلق‪ -‬وفاة احملامي وانتقال‬\n‫حقــه لورثتــه‪ -‬عــدم حتديــد األتعــاب كتابــة قبــل البــدء يف العمــل‪-‬‬\n‫إبــرام عقــد اتفــاق بــن احملامــي وورثــة املــوكل ملــزم للطرفــن‪ -‬إنهــاء‬\n‫احملامــي العمــل وإعــادة احلــق ينفــي حــدوث ضــرر ملوكلــه‪ -‬اســتطالع‬\n‫رأي أهــل اخلبــرة يف تقديــر األتعــاب ‪ -‬إقــرار الوكيــل ملــزم للمــوكل ‪.‬‬\n\n\n\n\n‫‪ -1‬قــول املــرداوي يف اإلنصــاف‪ »:‬وأنــه لــو قــال (أي اجلاعــل للعامــل)‬\n‫فلــك ثلــث الضالــة أو ربعهــا صــح علــى مــا نــص عليــه يف الثــوب ينســج‬\n          ‫بثلثــه والــزرع يحصــد والنخــل يصــرم بسدســه ال بــأس بــه ا‪.‬ه ـ‬\n‫‪ -2‬وقــال يف كشــاف القنــاع ‪ 484/9‬وأن جعــل ملــن عمــل لــه عمــا عوضــا‬\n‫مجهــوال فلــه أجــره املثــل ا‪.‬ه ـ وينظــر الشــرح الكبيــر ‪ 168/16‬واإلنصــاف‬\n                                                                      ‫‪.168/16‬‬\n‫‪ -3‬قولــه يف كشــاف القنــاع ‪« 286/8‬ويصــح الصلــح عــن املجهــول‬\n‫مبعلــوم‪ ،‬إذا كان املجهــول ممــا ال ميكــن معرفتــه ســواء كان املجهــول‬\n‫عينــا أودينــا ‪ ،‬أو كان اجلهــل مــن اجلانبــن ‪ ،‬كصلــح الزوجــة عــن‬\n‫صداقهــا الــذي ال بينــة لهــا بــه ‪،‬وال علــم لهــا وال للورثــة مببلغــه ‪،‬‬\n‫وكذلــك الرجــان بينهمــا معاملــة وحســاب قــد مضــى عليــه زمــن‬\n‫طويــل ‪ ،‬وال علــم لــكل منهمــا مبــا عليــه لصاحبــه ‪ ،‬أو كان اجلهــل‬\n                                                                                 ‫‪110‬‬\n\f      ‫ممــن الديــن عليــه بــأن كان عليــه حــق ال علــم لــه بقــدره ولــو علمــه‬\n                                  ‫صاحــب احلــق وال بينــة لــه مبــا يدعيــه» ا‪.‬هــ‪.‬‬\n\n\n\n\n      ‫ا‬\n      ‫أقــام املدعــون دعواهــم ضــد املدعــى عليهــم بــأن مورثهــم كان وكيـ ً‬\n      ‫ملــورث املدعــى عليهــم بخصــوص أرض مبكــة ولــم يتفقــوا كتابــة علــى‬\n      ‫أتعابــه وبعــد اســترجاع األرض مت االتفــاق بــن مورثهــم واملدعــى عليهــم‬\n      ‫كتابــة علــى أتعــاب قدرهــا ‪ %20‬مــن ثمــن األرض إال أن املدعــى عليهــم‬\n      ‫امتنعــوا عــن ســداد هــذه القيمــة وقامــوا ببيــع األرض مببلــغ ســتني مليــون‬\n      ‫ريــال لذلــك فإنهــم يطلبــون إلــزام املدعــى عليهــم بســداد مبلــغ اثنــي عشــر‬\n      ‫مليــون ريــال نصيــب مورثهــم كأتعــاب يف ثمــن األرض املشــار إليهــا ‪-‬‬\n      ‫دفــع وكيــل املدعــى عليهــم أن هــذا االتفــاق كان مشــروط أن يتــم البيــع‬\n      ‫لشــخص معــن ولكــن ذلــك لــم يحــدث وطلــب تعويض ـ ًا مــن املدعــن‬\n      ‫لقــاء األضــرار التــي نتجــت عــن تصرفــات مورثهــم مببلــغ وقــدره ثالثــة‬\n      ‫وثالثــون مليــون ريــال وبعــد أن اســتعرضت احملكمــة كافــة األوراق‬\n      ‫وســماع الشــهود قــررت إعتبــار موضــوع الدعــوى عقــد جعالــة وأن العمــل‬\n      ‫املتفــق عليــه بــن مورثــي الطرفــن فقــد مت علــى النحــو املطلــوب وبذلــك‬\n      ‫ينتفــي الضــرر يف حــق املدعــى عليهــم‪ -‬وألن املدعــى عليهــم ومــورث‬\n      ‫املدعــن اتفقــوا علــى ‪ %20‬مــن قيمــة األرض مقابــل أتعــاب ‪ -‬حكمــت‬\n      ‫احملكمــة بإلــزام املدعــى عليهــم بســداد مبلــغ اثنــي عشــر مليــون ريــال‬\n      ‫للمدعــن ‪ -‬أعتــرض املدعــى عليهــم علــى احلكــم ‪ -‬جــرى تصديقــه‬\n      ‫مــن محكمــة اإلســتئناف قــدم املدعــى عليهــم التمــاس إلــى محكمــة‬\n                                                                 ‫اإلســتئناف ورفــض ‪.‬‬\n\n‫‪111‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....................‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة املقيــدة باحملكمــة برقــم‬\n‫‪ 32575209‬وتاريــخ ‪1432/05/20‬ه ـ حضــر ‪..........................‬بالســجل‬\n‫املدنــي رقــم ‪ 1039132012‬بوكالتــه عــن ‪ ......................‬بالوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانية بجنوب جدة برقم ‪ 3537/34729‬يف‬\n‫‪1432/10/7‬ه ـ وبوكالتــه أيضــا عــن ‪ ............‬بوكالته عن ‪...............‬و‪.‬‬\n‫‪..................‬بالوكالــة‬                 ‫‪...........‬و‪...............‬و‪.............‬و‪..........‬أوالد‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم ‪3526/33694‬‬\n‫يف ‪1432/9/16‬ه ـ وكلتــا الوكالتــن تخولــه إقامــة وســماع الدعــاوى‬\n‫واملرافعــة واملدافعــة وحضــور اجللســات ‪..‬الــخ وادعــى علــى احلاضــر معــه‬\n‫‪.........................‬بالســجل املدنــي رقــم …………… بوكالتــه عــن‬\n‫‪ ..............................‬بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بشــمال محافظــة جــدة برقــم ‪ 10277/8577‬يف ‪1432/1/26‬ه ـ وعــن‬\n‫‪ ..............................‬أصالــة عــن نفســه وبوكالتــه عــن ‪.........................‬‬\n‫بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف برقــم‬\n‫‪ 4584/26273‬يف ‪1431/6/5‬ه ـ وعــن ‪ ............................‬بالوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف برقــم ‪4587/26522‬‬\n‫يف ‪1431/6/8‬ه ـ وعــن ‪ ..........................‬أصالــة عــن نفســه وبوكالتــه‬\n‫عــن ‪ .......................‬و‪.............‬و‪.............‬و‪..................‬و‪ ...................‬أوالد‬\n‫‪ ....................‬بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف‬\n\n\n                                                                                                         ‫‪112‬‬\n\f      ‫برقــم ‪ 4526/20454‬يف ‪1431/4/29‬ه ـ وعــن ‪ .....................‬أصالــة عن‬\n      ‫نفســه وبوكالتــه عــن أختــه ‪ .............‬بالوكالــة الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة مبكــة برقم ‪ 3878/55115‬يف ‪1429/11/10‬هـ وجميع‬\n      ‫الــوكاالت تخولــه ســماع الدعــاوى واملرافعــة املدافعــة ‪...‬الــخ قائــا يف‬\n      ‫دعــوه عليــه أدعــى أنــا ‪ ................‬ســعودي اجلنســية بالســجل املدنــي‬\n      ‫ا‬ ‫رقــم ‪ ...............‬الوكيــل الشــرعي عــن ‪ ......................‬وبصفتــه وكي ـ ً‬\n      ‫عــن (‪...............................‬ابنــاء ‪ ........................‬و‪ .......................‬أبنــاء‬\n      ‫‪........................‬وادعــى علــى املدعــى عليهــم ورثــة ‪.............................‬‬\n      ‫وهــم ورثــة (‪ ، ...........‬وورثــة ‪ ...................‬وهــم (أبنائــه ‪ ...........‬و‪).............‬‬\n      ‫ا يف‬   ‫وورثــة ‪ .............‬وهــم ‪ .........‬و‪ ).............‬و‪ ............‬و‪ ...............‬قائ ـ ً‬\n      ‫حتريــر دعــواي إن مــورث موكلــي قبــل وفاتــه كان قــد ترافــع بصفتــه‬\n      ‫الوكيــل الشــرعي عــن مــورث املدعــى عليهــم يف األرض الكائنــة‬\n      ‫‪...‬مبكــة املكرمــة ولــم يكــن هنــاك اتفــاق مبــرم مــع مــورث املدعــى‬\n      ‫عليهــم يحــدد أتعــاب مــورث موكلـ ّـي حتــى عــام ‪1426‬ه ـ حيــث اتفــق‬\n      ‫معــي جميــع الورثــة بــأن أتعابــي ‪ %20‬مــن قيمــة األرض وذلــك حســب‬\n      ‫العقــد املــؤرخ ‪1426/2/3‬ه ـ وحيــث أن مــورث موكلي يف العام ‪1415‬هـ‬\n      ‫أقــام دعــوى يف مكــة املكرمــة ضــد املدعــى عليــه ‪.....................‬مطالبـ ًا‬\n      ‫بإرجــاع األرض املذكــورة وقــد نظــرت لــدى مكتــب فضيلــة الشــيخ‬\n      ‫‪ .....................‬وقــد صــدر يف هــذه الدعــوى الصــك رقــم ‪5/19/53‬‬\n      ‫وتاريــخ ‪1416/4/1‬ه ـ وحكــم بعــدم االختصــاص وقــد اكتســب‬\n      ‫احلكــم القطعيــة ويف العــام ‪1417‬ه ـ قــام مــورث موكلــي برفــع دعــوى‬\n      ‫أخــرى بالريــاض ضــد ‪ ..........................‬مطالــب بقيمة األرض املذكورة‬\n      ‫نظــرت لــدى مكتــب الشــيخ ‪ ....‬القاضــي باحملكمــة الكبــرى‬\n\n\n‫‪113‬‬\n\f‫بالريــاض وصــدر بذلــك الصــك رقــم ‪ 16/176‬بتاريــخ ‪1419/5/24‬ه ـ‬\n‫والقاضــي باحلكــم علــى ‪ ...................‬بدفــع مبلــغ ‪( 54.000.000‬أربعــة‬\n‫وخمســون مليــون ريــال) لصالــح مــورث املدعــى عليهــم وقــد اكتســب‬\n‫هــذا الصــك القطعيــة وبنــاء ًا علــى أوامــر ملكيــة أحيلــت القضيــة‬\n‫لدراســتها مــن قبــل مجلــس القضــاء األعلــى بهيئتــه الدائمــة وتوصــل‬\n‫إلــى احلكــم رقــم ‪ 4/140‬وتاريــخ ‪1423/2/24‬ه ـ يقضــي بإلغــاء كال‬\n‫الصكــن الصادريــن مــن احملكمــة الكبــرى مبكــة املكرمــة واملنــوه‬\n‫عنــه بعاليــة والصــك الصــادر مــن احملكمــة الكبــرى بالريــاض وإرجــاع‬\n‫األرض إلــى مــورث املدعــى عليهــم واملدعــى عليهــم يعلمــون أن مــورث‬\n‫موكلــي قــد بــذل مجهــود ًَا جبــار ًا بحثــا وراء حقــوق مــورث املدعــى‬\n‫عليهــم طيلــة أكثــر مــن (‪)14‬عامـ ًا وقــد كللــت مســاعيه بالنجــاح وهلل‬\n‫احلمــد وقــد أعيــدت األرض إلــى أصحابهــا واملدعــى عليهــم أقــروا مبــا‬\n‫قــام بــه موكلــي ومــا بذلــه مــن جهــد يف هــذه الدعــوى وقــد كتبــوا لــه‬\n‫اإلقــرار املشــار إليــه بعاليــة طالــب مــورث موكلــي املدعــى عليهــم مــرار ًا‬\n‫وتكــرار ًا بتســليمه أتعابــه إال أنهــم أثــروا املماطلــة والتهــرب حتــى توفــى‬\n‫مــورث موكلــي وال زال املدعــى عليهــم مياطلــون بدفــع حقــوق موكلــي‬\n‫يف هــذه األتعــاب وملــا كان ملوكلــي بذمــة املدعــى عليهــم نســبة وقدرهــا‬\n‫‪ %20‬مــن قيمــة األرض إال أنهــم أثــروا املماطلــة والتهــرب الســيما بيعهــم‬\n‫األرض واســتحقاق نســبة موكلــي املشــار إليهــا ‪ ،‬وملــا كان ذلــك ميثــل‬\n‫ضرب ـ ًا مــن ضــروب أكل أمــوال النــاس بالباطــل وال شــك أن ذلــك ميثــل‬\n‫إضــرار ًا متعمــد ًا مبوكلــي وحيــث قــال تعالــي( يأيهــا الذيــن آمنــوا ال‬\n‫تأكلــوا أموالكــم بينكــم بالباطــل) وحيــث قــال صلــى اهلل عليــه‬\n‫وســلم (أعــط األجيــر أجــره قبــل أن يجــف عرقــه ) وقــال صلــى اهلل عليــه‬\n\n\n                                                                                      ‫‪114‬‬\n\f                                                           ‫وســلم (مطــل الغنــي ظلــم)‬\n      ‫موكلي‬\n       ‫ّ‬          ‫وأطلــب مــا يلــي ‪ :‬احلكــم علــى املدعــى عليهــم وإلزامهــم بتســليم‬\n      ‫مــا نســبته ‪ %20‬مــن قيمــة األرض املباعــة وحيــث أن املدعــى عليهــم‬\n      ‫أصالــة باعــوا األرض بســتني مليــون ريــال فأطلــب إلزامهــم بدفــع مــا‬\n      ‫يقابــل هــذه النســبة مــن هــذا املبلــغ وقــدره اثنــا عشــر مليــون ريــال هــذه‬\n      ‫دعــواي وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي أصالــة ثــم يف‬\n      ‫جلســة أخــرى حضــر الطرفــان وكالــة وبســؤال املدعــى عليــه وكالــة‬\n      ‫عــن اجابتــه علــى الدعــوى أبــرز ورقــة هــذا نصهــا يعلــم فضيلتكــم أن‬\n      ‫املــواد (‪ )28-27-26‬مــن نظــام احملامــاة والئحتــه التنفيذيــة قواعــد آمــره‬\n      ‫حــددت أن احملكمــة املختصــة بتحديــد أتعــاب احملامــي هــي احملكمــة‬\n      ‫التــي الــم بدقائــق الوقائــع والظــروف واملالبســات وعــدد اجللســات‬\n      ‫والعنايــة مــن واقــع املســتندات واملذكــرات املقدمــة مــن احملامــي ‪ .‬وهــذا‬\n      ‫مــا أي ــده صــك احلكــم الصــادر مــن احملكمــة العامــة بالطائــف رقــم‬\n      ‫‪ 4/5/91‬وتاريــخ ‪1431/7/16‬ه ـ واملؤيــد بقــرار محكمــة االســتئناف‬\n      ‫رقــم ‪ 1/2/357‬وتاريــخ ‪1432/4/8‬ه ـ بنــاء علــى الدفــع بعــدم اختصاص‬\n      ‫احملكمــة العامــة بالطائــف وأن محكمــة الريــاض هــي املختصــة بنظــر‬\n      ‫القضيــة إال أن املدعــي وكالــة آثــر جتاهــل حكــم فضيلتــه وحيــث أن‬\n      ‫احملكمــة العامــة مبكــة املكرمــة ســبق أن صرفــت النظــر عــن دعوانــا‬\n      ‫وكالــة ضــد ‪ .................‬نظــرا ملطالبــة الوكيــل بالقيمــة والقيمــة بذمــة‬\n      ‫‪...................‬ومت نظــر الدعــوى ضــد ‪ .........‬بالريــاض وقــد أبطلــت جميــع‬\n      ‫الصكــن بقــرار مــن مجلــس القضــاء األعلــى وأمــر ملكــي ســامي‪.‬‬\n      ‫وبنــاء عليــه أطلــب مــن فضيلتكــم صــرف النظــر عــن الدعــوى لعــدم‬\n      ‫اختصــاص احملكمــة وأن ينظــر يف طلبــي هــذا كدفــع شــكلي يبــت‬\n\n\n‫‪115‬‬\n\f‫فيــه قبــل نظــر القضيــة حرصــا علــى كســب الوقــت لنــا كمتداعــن ‪.‬‬\n‫إجابــة علــى دعــوى املدعــي أجيــب مبــا يلــي أوال «‪-:‬ال يفتــر املدعــي عــن‬\n‫تزييــف احلقائــق وتضليــل القضــاء وااللتــواء عن احلــق ‪ ،‬فها هو يدعي بأن‬\n‫الورثــة مقريــن بـ ـ ‪ %20‬وثبــوت أتعابــه!! ونتســاءل ملــاذا أقــام هــذه الدعــوى‬\n‫؟ أليــس إلثبــات أتعابــه ‪ ،‬وهــل تناســى أنــه كان شــريك يف الشــراء‬\n‫مــن الورثــة يف البيــع احليلــة الباطــل لتثبيــت األتعــاب والوصايــا الباطلــة‬\n‫بعــد أن أبطــل العقــد ومــا يدعيــه احملكمــة العامــة بالطائــف فضيلــة‬\n‫الشــيخ ‪ ...................‬بالصــك رقــم ‪ 5/8/194‬وتاريــخ ‪1429/3/10‬هــ‪ .‬ثم‬\n‫إن الورثــة لــم يقــروا ويلحــظ فضيلتكــم أن العقــد الــذي ذكــرت فيــه‬\n‫أتعابــه مبوجــب صلــح باطــل وذلــك ال يعت ــبر إقــرار ذكــر يف كشــاف‬\n‫القنــاع ‪ )425/10‬مــن ُأدعــي عليــه بحــق فأنكــره ‪ ،‬ثــم قــال صاحلنــي‬\n‫عــن املــال الــذي تدعيــه لــم يكــن مقــرا بــه وذكــر أيضـ ًا يف ‪( 424/10‬‬\n‫فمتــى كان أحدهمــا عاملـ ًا بكــذب نفســه فالصلــح باطــل يف حقــه ومــا‬\n‫أخــذه العالــم بكــذب نفســه حــرام عليــه ألنــه مــن أكل املــال بالباطــل‬\n‫وال يشــهد لــه الشــاهد بــه إن علــم ظلمــه ألنــه إعانــة علــى باطــل ) وهــذا‬\n‫مــا شــهد بــه الشــهود نظــر ًا ملــا علمــوه‪ .‬ثانيــا»‪ -:‬ليــس صحيحــا مــا ذكــره‬\n‫وكيــل املدعــي بــأن الوكيــل رحمــه اهلل طالــب بعــودة األرض ويظهــر‬\n‫لفضيلتكــم أن الوكيــل رحمــة اهلل لــم يطالــب بعــودة األرض بــل طالــب‬\n‫بالثمــن ممــا كان لــه بالــغ الضــرر علــى تكييــف القضيــة بشــكلها‬\n‫الصحيــح وأخــذ يخبــط يف رفــع الدعــاوى ويضلــل القضــاء حتــى مت‬\n‫تكييفهــا بالشــكل الصحيــح مــن مجلــس القضــاء األعلــى وعــودة‬\n‫األرض عــن طريــق أعلــى ســلطات الدولــة ولــذا فــإن ورثــة املدعــن أصالــة‬\n‫ال يســتحق أي شــيء مقابــل عملــه ونطلــب صــرف النظــر عــن دعــواه هــذه‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫إجابتــي وبعــرض هــذه اإلجابــة علــى املدعــي وكالــة ثــم يف جلســة أخــرى‬\n      ‫حضــر الطرفــان وكالــة وجــرى ســؤال املدعــي وكالــة هــل أحضــر ردا‬\n      ‫علــى إجابــة املدعــى عليــه وكالــة فأبــرز ورقــة هــذا نصهــا ‪ -:‬إن ردي‬\n                                      ‫علــى مــا قدمــه املدعــى عليــه هــو مــا يلــي ‪-:‬‬\n      ‫‪ .1‬إن املــادة ( ‪ ) 5/28‬مــن الالئحــة التنفيذيــة لنظــام احملامــاة قــد ورد‬\n      ‫فيهــا مــا نصــه (وتنظــر مــن القاضــي الــذي نظــر القضيــة األصليــة‬\n      ‫‪...‬الــخ ) وال شــك أن عبــارة ( القضيــة األصليــة ) تعنــى القضيــة التــي مت‬\n      ‫ـداء حســب النظــام ومت الترافــع فيهــا وصــدر فيهــا حكــم‪،‬‬         ‫رفعهــا ابتـ ً‬\n      ‫وهــذا مــا ينطبــق بالتمــام علــى القضيــة التــي رفعــت مــن قبــل مــورث‬\n      ‫موكلــي مطالب ـ ًا بــأرض مــورث املدعــى عليهــم والتــي نظــرت مــن قبــل‬\n      ‫فضيلــة الشــيخ ‪ ...................‬القاضــي بهــذه احملكمــة يف العــام ‪1415‬ه ـ‬\n      ‫وانتهــت بالصــك رقــم ‪ 5/19/53‬وتاريــخ ‪1416/4/1‬ه ـ ‪ ،‬وال شــك أن‬\n      ‫الدعــوى التــي رفعــت ضــد ‪ ...........................‬بالريــاض دعــوى متفرعــة‬\n      ‫عــن دعوانــا أمــام فضيلــة الشــيخ ‪ .....................‬وهــذا مــا جــاء يف عجــز‬\n      ‫املــادة ( ‪ ) 26‬مــن نظــام احملامــاة والتــي تنــص ( ويطبــق هــذا احلكــم‬\n      ‫كذلــك إذا نشــأ عــن الدعــوى األصليــة أي دعــوى فرعيــة ) ‪ .‬أمــا فيمــا‬\n      ‫يخــص الصــك الصــادر مــن محكمــة الطائــف بالرقــم ‪ 4/5/91‬وتاريــخ‬\n      ‫‪1431/7/16‬ه ـ واملصــادق عليــه مــن محكمــة االســتئناف وإن كان‬\n      ‫قــد صــدر بعــدم االختصــاص إال أنــه لــم يبــن احملكمــة املختصــة وذلــك‬\n      ‫لوجــود النصــوص النظاميــة التــي حتكــم ذلــك ‪ ،‬لــذا التمــس مــن‬\n      ‫فضيلتكــم صــرف النظــر عــن الدفــع الشــكلي وذلــك لتعــارض الطلــب‬\n                   ‫مــع النصــوص النظاميــة التــي حتكــم مســألة االختصــاص‪.‬‬\n      ‫‪ .2‬أمــا فيمــا يخــص مــا جــاء يف ( ثانيـ ًا ) مــن مذكرتــه ‪ :‬نــرد بــأن فضيلــة‬\n\n\n‫‪117‬‬\n\f‫الشــيخ ‪ .....................‬القاضــي باحملكمــة العامــة بالطائــف لــم يبطــل‬\n‫اســتحقاق مــورث موكلــي فيمــا يخــص األتعــاب بــل ذكــر أن ملــورث‬\n‫موكلــي املطالبــة مبــا نســبته ‪ %20‬مــن ثمــن األرض وبدعــوى مســتقلة‪،‬‬\n‫وال شــك أن املدعــى عليهــم أقــروا بنســبة ال ـ ‪ %20‬مــن قيمــة األرض‬\n‫كأتعــاب ملــورث موكلــي فهنــاك أقــرار موثــق مــن الورثــة يؤكــدون‬\n‫فيــه علــى أحقيــة مــورث موكلــي بهــذه النســبة ‪ ،‬أمــا مــن حيــث دعواهــم‬\n‫فقــد حصروهــا يف إبطــال البيــع فقــط ولــم يطالبــوا بأكثــر مــن ذلــك ‪.‬‬\n‫‪ .3‬وال شــك أن مــورث موكلــي يســتحق هــذه النســبة بالنظــر إلــى مــا‬\n‫بذلــه مــن جهــد ومــا عــاد مــن نفــع طــوال ‪ 14‬عــام ‪ - ،‬أمــا مــا جــاء يف (‬\n‫ـداء‬\n‫ثالثـ ًا ) مــن مذكرتــه‪ :‬فنــرد بــأن مــورث موكلنــا كان قــد طالــب ابتـ ً‬\n‫بعــن املزرعــة وهــذا مــا يظهــر يف حتريــر دعــواه األصليــة واملضمنــة يف‬\n‫الصــك رقــم ‪ 5/19/53‬وتاريــخ ‪1416/4/1‬ه ـ والتــي جــاء فيهــا ( اطلــب‬\n‫حجــز املزرعــة وإعادتهــا ملوكلــي وعــدم التصــرف فيهــا والســير يف‬\n‫القضيــة مبــا يضمــن تســليم ثمنهــا أو إعادتهــا إلــى موكلــي ) وال شــك‬\n‫ـداء علــى بيــع هــذه األرض ألن‬   ‫أن مــورث املدعــى عليهــم لــم يعتــرض ابتـ ً‬\n‫ذلــك بالضبــط مــا كان يطلبــه انــذاك عنــد إفراغهــا ل‪، .....................‬‬\n‫وبالتالــي فليــس ملــورث موكلــي اخليــرة مــن أمــره يف أن ميضــي قدمـ ًا يف‬\n‫املطالبــة بثمــن األرض لــدى ‪ ..........‬ال ســيما وقــد مت إفهامــه من قبل ناظر‬\n‫الدعــوى األصليــة بــأن الدعــوى بالثمــن تتوجــه علــى ‪،.................‬وصرفــه‬\n                                      ‫النظــر عــن الدعــوى ضــد مــن بيــده العــن‪.‬‬\n‫‪ .4‬أمــا فيمــا يخــص تقديــر األتعــاب يف حــدود الــ‪ %20‬املذكــورة يف‬\n‫أقــرار املدعــى عليهــم فقــد مت نظــر دعــوى األتعــاب أمــام فضيلــة الشــيخ‬\n‫‪ ...................‬القاضــي باحملكمــة العامــة بالطائــف وقــد أجــرى عليهــا‬\n\n\n                                                                                       ‫‪118‬‬\n\f      ‫املســتلزمات الشــرعية الكفيلــة بتقديرهــا التقديــر الشــرعي وقــد‬\n      ‫خاطــب هيئــة النظــر باحملكمــة للتدخــل وتقديــر األتعــاب وقــد مت‬\n      ‫تقديرهــا بحضــور مــورث موكلــي واملدعــى عليهــم بعــد االســتعانة بأهــل‬\n      ‫اخلبــرة يف هــذا اخلصــوص وقــد صــدر منهــم قــرار يقضــي باســتحقاق‬\n      ‫مــورث موكلــي مــا نســبته ‪ %20‬مــن قيمــة األرض ونلتمــس مــن احملكمة‬\n                                                  ‫املوقــرة طلــب هــذا التقريــر رســمي ًا ‪.‬‬\n      ‫لــذا ولــكل مــا ذكــرت التمــس مــن فضيلتكــم إلــزام املدعــى عليهــم‬\n      ‫بتســليم موكلــي مــا نســبته ‪ %20‬مــن قيمــة األرض احلقيقيــة ا‪.‬ه ـ ثــم‬\n      ‫جــرى اطالعــي علــى الصــك الصــادر مــن احملكمــة العامــة بالطائــف‬\n      ‫برقــم ‪ 5/8/194‬يف ‪1429/3/10‬ه ـ فوجدتــه يتضمــن دعــوى بعــض‬\n      ‫ورثــة ‪ .......................‬ضــد ‪ ..................‬ويطالــب فيهــا تركــة مورثهــم‬\n      ‫‪ ................‬ثــم تدخــل يف القضيــة ‪ .................‬وذكــر أن مــن أعيــان‬\n      ‫التركــة املزرعــة املســماة ‪ ...‬وســبق أن باعهــا مــورث الطرفــن ‪...............‬‬\n      ‫مــع ‪ ....................‬مببلــغ ســتة وثمانــن مليونــا وأربعمائــة ألــف ريــال ولــم‬\n      ‫يســلم لــه هــذا املبلــغ واشــترط عــدم صرفــه حتــى تنــزع املزرعــة لصالــح‬\n      ‫الدولــة ومت إفــراغ العقــار لألميــر واحتفــظ البائــع بالصــك إال أن ‪...........‬‬\n      ‫لــم يلتــزم بهــذا الشــرط واســتخرج صــك بــدل فاقــد منــه وبــاع العقــار‬\n      ‫علــى ‪ ..................‬فأقــام ‪ .............‬بصفتــه وكيــل عــن ‪ ..................‬مــورث‬\n      ‫الطرفــن دعــوى ضــد ‪ .................‬يطالبــه بالثمــن فصــرف النظــر عــن‬\n      ‫دعــواه وافهــم بــأن تقــام الدعــوى بالثمــن علــى ‪ ...............‬يف مقــر إقامتــه‬\n      ‫بالريــاض فأقــام ‪..............‬دعــواه ضــد ‪ ............‬وصــدر احلكــم بإلــزام‬\n      ‫‪ .........‬بدفــع الثمــن ثــم صــدر قــرار الهيئــة الدائمــة ملجلــس القضــاء‬\n      ‫األعلــى بإعــادة املزرعــة ملالكهــا األصلــي ‪ .................‬ومــن ثــم ورثتــه‬\n\n\n‫‪119‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":110,"source_page_end":119,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"815d2b2f132c050327ca109da6f0acf04b586e891f5bbed6a863317c90ae6172","normalized_text_hash":"3f05988c07e9ddd033f349af93f231388b981af7181665b5c6c8933f7748d65d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p110-34220573"},{"id":"e955a9aa-42e8-549b-b922-15fb3f9cbcb0","document_type":"judgment","category":"judicial","subcategory":"general","title":"سمسرة -مطالبة بإعادة مبلغ معن -عدم حضور املدعى عليه دون عذر رغم تبلغه يعد نكو ال عن اجلواب -املمتنع عن احلضور تسمع عليه البينة ويقضى بها من غير مين االستظهار -احلكم يف حق املدعى عليه حضوري لتبلغه -إلزام املدعى عليه بتسليم املبلغ","document_number":"33459984","case_number":"32252771","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/20","year":"1434","subject":"سمسرة -مطالبة بإعادة مبلغ معن -عدم حضور املدعى عليه دون عذر رغم تبلغه يعد نكو ال عن اجلواب -املمتنع عن احلضور تسمع عليه البينة ويقضى بها من غير مين االستظهار -احلكم يف حق املدعى عليه حضوري لتبلغه -إلزام املدعى عليه بتسليم املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33459984:‬تاريخه‪1433/11/20:‬هـ‬\n                         ‫رقم الدعوى‪32252771:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34220971‬تاريخه‪1434/5/25 :‬هـ‬\n\n\n      ‫سمســرة ‪ -‬مطالبــة بإعــادة مبلــغ معــن ‪ -‬عــدم حضــور املدعــى عليــه دون‬\n      ‫عــذر رغــم تبلغــه يعــد نكــو ًال عــن اجلــواب ‪-‬املمتنــع عــن احلضــور تســمع‬\n      ‫عليــه البينــة ويقضــى بهــا مــن غيــر ميــن االســتظهار ‪ -‬احلكــم يف حــق‬\n      ‫املدعــى عليــه حضــوري لتبلغــه ‪ -‬إلــزام املدعــى عليــه بتســليم املبلــغ‬\n                                                                         ‫املدعــى بــه ‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار) رواه أحمد‪.‬‬\n      ‫‪ .2‬جــاء يف شــرح املنتهــى (وإن ســكت مدعــى عليــه بــأن لــم يقــر بالدعــوى‬\n      ‫ولــم ينكرهــا أو قــال املدعــى عليــه ال أقــر وال أنكــر أو قــال ال أعلــم قــدر‬\n      ‫حقــه وال بينــة ملــدع بدعــواه قــال احلاكــم ملدعــى عليــه إن أجبــت وإال‬\n                                    ‫ال وقضيــت عليــك بالنكــول ‪.)..‬‬ ‫جعلتــك نــاك ً‬\n      ‫‪ .3‬جــاء يف اإلنصــاف (وإن ســكت املدعــى عليــه فــم يقــر ولــم ينكــر قــال‬\n      ‫ال وقضيــت عليــك وهــو‬         ‫لــه القاضــي إن أجبــت وإال جعلتــك نــاك ً‬\n                                                                             ‫املذهــب)‪.‬‬\n      ‫‪ .4‬جــاء يف حتفــة احملتــاج (وإال لتواريــه أو تعــززه أي تغلبــه وقــد ثبــت‬\n      ‫ذلــك عنــد القاضــي فتســمع البينــة ويحكــم بغيــر حضــوره مــن غيــر‬\n                   ‫ميــن االســتظهار علــى املنقــول املعتمــد تغليظ ـ ًا عليــه ‪.)..‬‬\n                                            ‫‪ .5‬املادة ‪ 55‬من نظام املرافعات الشرعية‪.‬‬\n\n\n‫‪201‬‬\n\f‫ادعــى املدعــي ضــد املدعــى عليــه بــأن مــورث موكلــه اشــترى فلــة بحــي‬\n‫‪ ...‬بواســطة املدعــى عليــه ثــم اســتلم املدعــى عليــه مبلــغ وقــدره خمســون‬\n‫ألــف ريــال بشــيك وخمســة وعشــرون ألــف ريــال داللــه وأخــذ مياطــل يف‬\n‫إمتــام البيــع حتــى تاريخــه ويطلــب إلــزام املدعــى عليــه بــرد املبلــغ وقــدره‬\n‫خمســة وســبعون ألــف ريــال هكــذا ادعــى ‪ -‬طلــب املدعــى عليــه اإلمهــال‬\n‫للجــواب يف اجللســة القادمــة ‪ -‬لــم يحضــر املدعــى عليــه مــع تبلغــه جــرى‬\n‫ســؤال املدعــي عــن بينتــه ‪ -‬قــدم املدعــى الشــيك رقــم ‪ ...‬مببلــغ خمســن‬\n‫ألــف ريــال وإقــرار املدعــى عليــه باســتالم املبلــغ املدعــى بــه يف صــك‬\n‫احلكــم املنقــوض وشــهادة الشــاهد املثبتــة يف الصــك ‪ -‬ومبــا أن املدعــى‬\n‫عليــه تخلــف عــن احلضــور رغــم تبلــغ وكيلــه الشــرعي وإفهامــه بإيــداع‬\n‫جوابــه قبــل موعــد اجللســة بثالثــة أيــام ومبــا أن عــدم حضــوره وإيــداع‬\n‫دفاعــه دون عــذر يعــد نكــو ًال عــن اجلــواب والنــاكل يقضــى عليــه ملــا‬\n‫قــرره الفقهــاء ‪ -‬ومبــا أن امتنــاع املدعــى عليــه عــن احلضــور يعــد إضــرار ًا‬\n‫باملدعــي والضــرر يــزال ‪ -‬ومبــا أن املمتنــع عــن احلضور تســمع عليه البينة‬\n‫ويقضــى بهــا مــن غيــر ميــن االســتظهار ‪ -‬وبنــاء علــى إقــرار املدعــى عليــه‬\n‫باملبلــغ املدعــى بــه يف صــك احلكــم املنقــوض ‪ -‬ملــا تقــدم صــدر احلكــم‬\n‫بإلــزام املدعــى عليــه بتســليم املبلــغ املدعــى بــه وقــدره خمســة وســبعون‬\n‫ألــف ريــال ملــوكل املدعــي ‪ -‬يعــد هــذا احلكــم يف حــق املدعــى عليــه‬\n‫حضوري ـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات وســيبلغ باحلكــم ‪-‬‬\n‫قنــع املدعــي وكالــة باحلكــم ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                  ‫األولــى مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n                                                                                        ‫‪202‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪32252771‬‬\n      ‫وتاريــخ ‪ 1432/06/27‬ه ـ املقيــدة باحملكمــة برقــم ‪32759673‬‬\n      ‫وتاريــخ ‪ 1432/06/22‬ه ـ واملنقــوض بالقــرار رقــم ‪/1/21‬ن وتاريــخ‬\n      ‫‪1432/6/11‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/03/08‬ه ـ أفتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 53‬وفيهــا حضــر ‪ ........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ........‬بصفتــه وكيــا عــن ‪ ........‬ولــي اصالــة‬\n      ‫عــن نفســه وبواليتــه علــى اخويــه ‪ ........‬و‪ ........‬مبوجــب صــك الواليــة‬\n      ‫الصــادر مــن احملكمــة العامــة بجــدة برقــم ‪ 13/120‬يف ‪1427/7/26‬ه ـ‬\n      ‫وبوكالتــه عــن ‪ ........‬ولــي و‪ ........‬و‪ ....‬و‪ ........‬و‪ ........‬بصفتهــم مــن‬\n      ‫ورثــة املتــويف ‪ ........‬مبوجــب صــك حصــر الورثــة الصــادر مــن احملكمــة‬\n      ‫العامــة بجــدة برقــم ‪ 15/104‬وتاريــخ ‪1427/7/25‬ه ـ مبوجــب الوكالــة‬\n      ‫رقــم ‪ 51636‬وتاريــخ ‪1428/6/12‬ه ـ وادعــى علــى احلاضــر معــه ‪........‬‬\n      ‫ســعودي اجلنســية مبوجب الســجل املدني رقم ‪ ........‬بصفته وكيال عن‬\n      ‫‪ ........‬مبوجــب الوكالــة رقــم ‪ 15928‬وتاريــخ ‪1433/2/17‬ه ـ قائــا يف‬\n      ‫دعــواه أن مــورث موكلــي اشــترى فلــه بحــي ‪ ...‬بواســطة املدعــى عليــه ثــم‬\n      ‫اســتلم مبلــغ وقــدره خمســون ألــف ريــال شــيك وخمســة وعشــرون ألــف‬\n      ‫ريــال داللــه وإخــذ مياطــل حتــى تاريخــه يف إكمــال البيــع نطلــب إلزامــه‬\n      ‫بإرجــاع املبلــغ الــذي يف ذمتــه وهــو خمســة وســبعون ألــف ريــال هــذه‬\n      ‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال أطلــب مهلــة للــرد هكــذا‬\n\n‫‪203‬‬\n\f‫قــال ويف يــوم الثالثــاء املوافــق‪ 1433/06/24‬ه ـ افتتحت اجللســة الســاعة‬\n‫‪ 10 : 01‬وفيهــا حضــر ‪ ........‬واملدونــه هويتــه ووكالتــه ســابق ًا ولــم‬\n‫يحضــر املدعــى عليــه رغــم تبلغــه باملوعــد يف اجللســه املاضيــه وبســؤال‬\n‫املدعــي وكالــه قــال أطلــب تبليغــه عــن طريــق البحــث والتحــري لــذا‬\n‫جــرى تأجيــل اجللســه لتبليــغ املدعــى عليــه عــن طريــق البحــث والتحــري‪.‬‬\n‫ويف يــوم الســبت املوافــق‪ 1433/11/20‬ه ـ لــدي أنــا ‪ ........‬القاضــي‬\n‫يف احملكمــة العامــة مبحافظــة جــدة وخلــف فضيلــة الشــيخ ‪، ........‬‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ‪ ........‬ولــم يحضــر املدعى‬\n‫عليــه وال مــن ميثلــه وقــد وردنــا أصــل ورقــة البــاغ موقعــة مــن املســتلم‪........‬‬\n‫وصفتــه وكيــل شــرعي ومتبلــغ عــن طريــق املشــرف اإلداري مبكتبنــا‬\n‫وتوقيعــه‪ .‬ا‪.‬ه ـ وقــد وردنــا كتــاب مديــر شــعبة التحريــات والبحــث‬\n‫اجلنائــي رقــم‪/4/20/1733 :‬ع‪ 22‬يف‪1433/1/25 :‬ه ـ ونــص احلاجــة‬\n‫منــه‪( :‬عليــه نفيــد فضيلتكــم بأنــه حضــر لدينــا املذكــور وأقــر بإقــراره‬\n‫املرفــق بأنــه مســتعد مبراجعتكــم وإنهــاء الدعــوى املقامــة ضــده)‪ .‬ا‪.‬‬\n‫ه ـ وباالطــاع علــى احملضــر املرفــق وجدنــا مــا نصــه‪( :‬أتعهــد أنــا ‪........‬‬\n‫بــأن أراجــع احملكمــة العامــة مبحافظــة جــدة لــدى الشــيخ ‪ ........‬إلنهــاء‬\n‫الدعــوى املقامــة ضــدي مــن ‪ ........‬وعليــه جــرى التوقيــع‪ .‬توقيــع)‪ .‬ا‪ .‬ه ـ‬\n‫وبســؤال املدعــي وكالــة عــن بينتــه أجــاب قائــا‪ :‬بينتــي الشــيك رقــم‬\n‫‪ ...‬يف ‪1427/6/18‬ه ـ الصــادر مــن ‪ ........‬ولــي لصالــح الســيد ‪........‬‬\n‫مببلــغ قــدره خمســون الــف ريــال وذلــك عربــون فيــا ورثــة ‪ ...‬املســحوب‬\n‫علــى بنــك ‪ ........‬ا‪.‬ه ـ وباالطــاع علــى صورتــه وجدنــاه طبقــا ملــا ذكــر‬\n‫وبســؤاله هــل لديــه زيــادة بينــه اجــاب قائــا نعــم وابــرز الشــيك رقــم ‪14‬‬\n‫يف ‪1427/6/18‬ه ـ الصــادر مــن ‪ ........‬ولــي لصالــح الســيد ‪ ........‬مببلــغ‬\n\n\n                                                                                            ‫‪204‬‬\n\f      ‫قــدره خمســة وعشــرون ألــف ريــال ســعودي وذلــك داللــة فيــا ورثــة ‪........‬‬\n      ‫املســحوب علــى بنــك ‪ ........‬ا‪.‬ه ـ وباالطــاع علــى صورتــه وجدنــاه طبقــا‬\n      ‫ملــا ذكــر وبســؤاله هــل لديــه زيــادة بينــه اجــاب قائــا نعــم وهــي اقــراره‬\n      ‫باســتالم املبلــغ املشــار إليــه املثبــت علــى الصــك املنقــوض مــن املكتــب‬\n      ‫القضائي الثالث رقم‪ 3/200/109 :‬يف ‪1430/5/11‬هـ وباالطالع عليه‬\n      ‫وجدنــا أن املدعــي ‪ ....‬ولــي باالصالــة عن نفســه وبوكالته عن ورثة ‪........‬‬\n      ‫واملدعــى عليــه ‪ ........‬واملتضمــن مــا نصــه ( واســتلمت مــن مورثهــم هــذا‬\n      ‫املبلــغ وقــدره خمســة وســبعون ألــف ريــال ولــي منهــا مبلــغ داللــه خمســة‬\n      ‫وعشــرون ألــف ريــال حســب العقــد مناصفــة يف مبلــغ الداللــة بينــي وبــن‬\n      ‫شــخص اســمه ‪ ........‬مينــي اجلنســية أمــا مبلــغ خمســون ألــف ريــال فقــد‬\n      ‫ســلمتها للبائــع ‪ ........‬وكيــل ورثــة ‪ ........‬وقــد حصــل اتفــاق حيــث طلــب‬\n      ‫مــورث املدعــي مهلــة أســبوع ثــم تغيــب ومضــت املهلــة وعلمنــا بعــد ذلــك‬\n      ‫انــه تــويف بعدهــا بشــهر ) ا‪.‬ه ـ ثــم أضــاف‪ :‬علــى فــرض أنــه ســلمها لـ ــ‪........‬‬\n      ‫فإنــه ليــس وكيــا عــن الورثــة هكــذا أضــاف‪ .‬وبســؤاله هــل لديــه زيــادة‬\n      ‫بينــه أجــاب قائــا نعــم وهــي شــهادة الشــاهد املثبتــة يف صــك احلكــم‬\n      ‫املشــار إليــه أعــاه وباالطــاع عليــه وجدنــا مــا نصــه‪( :‬فأحضــر الشــاهد‬\n      ‫‪ ........‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ........ :‬وبســؤاله‬\n      ‫عمــا لديــه مــن شــهادة قــال أشــهد هلل بأننــي كنــت حاضــرا يف وقــت‬\n      ‫كتابــة املبايعــة التــي كانــت بــن ‪ ........‬و‪ ........‬وأشــهد أن التأخيــر‬\n      ‫كان مــن املدعــى عليــه ‪...‬ويقــول إن صاحــب العقــار ‪ ........‬مســافر إلــى‬\n      ‫خــارج اململكــة وأنــه ســيعود بعــد أســبوعني ثــم اتصلنــا باملدعــى عليــه‬\n      ‫‪...‬فقــال لــم يعــد مــن الســفر فأشــهد أن التأخيــر لــم يكــن مــن ‪........‬‬\n      ‫بــل كان مــن املدعــى عليــه ‪ ...‬هكــذا شــهد)‪ .‬ا‪ .‬ه ـ وبســؤاله هــل لديــه‬\n\n\n‫‪205‬‬\n\f‫زيــادة بينــة أجــاب قائــا ليــس لــدي ســوى مــا ذكــرت هكــذا اجــاب‪.‬‬\n‫وباالطــاع علــى أصــل الصــك رقــم‪ 3/200/109 :‬يف‪1430/5/11 :‬ه ـ‬\n‫وجدنــا مــا نصــه‪( :‬وعليــه ورد خطــاب رئيــس قســم اخلبــراء باحملكمــة‬\n‫رقــم‪ 30/51691 :‬يف‪1431/2/11 :‬ه ـ املعطــوف علــى رئيــس طائفــة‬\n‫العقــار مبحافظــة جــدة املتضمــن أنــه بحســب املتعــارف عليــه فيجــب أوال‬\n‫أن تكــون الدفعــة األولــى باســم البائــع وليــس باســم صاحــب املكتــب‬\n‫ثانيــا تصــرف الداللــة للمكتــب بعــد امتــام عملــة اإلفــراغ ثالثــا مــا لــم‬\n‫يتــم توقيــع عقــد املبايعــة مــن الطــرف االول البائــع او مــن ينــوب عنــه‬\n‫بوكالــه شــرعية وهــذا يبطــل البيــع وتكــون املبايعــة غيــر صحيحــه)‬\n‫ا‪.‬ه ـ ثــم قــرر املدعــي وكالــة قائــا ان البيــع لــم يتــم بــن ورثــة ‪ ........‬وبــن‬\n‫مــورث موكلــي الجــل مماطلــة املدعــى عليــه اذا انــه اخــذ املبلــغ وليــس‬\n‫يف يــده حــل وال عقــد بخصــوص هــذا املنــزل الــذي تســلم داللتــه هكــذا‬\n‫قــرر فبنــاء علــى مــا ســلف ‪ ،‬وألن املدعــى عليــه قــد تخ ّلــف عــن احلضــور‬\n‫مــع تبلــغ وكيلــه شــخصي ًا مبوعــد هــذه اجللســة ـ حســب اإلفــادة املرفقــة‬\n‫باملعاملــة ـ‪ ،‬واســتالمه لصحيفــة الدعــوى وإفهامــه بإيــداع دفاعــه‬\n‫وجوابــه قبــل موعــد اجللســة بثالثــة أيــام‪ ،‬وحيــث إن عــدم إيــداع جوابــه‬\n‫ودفاعــه يف احملكمــة قبــل موعــد اجللســة بثالثــة أيــام وعــدم حضــوره‬\n‫بعــد علمــه بالدعــوى ومضمونهــا وموعــد اجللســة دون عــذر يعـ ّـد نكــو ًال‬\n‫عــن اجلــواب‪ ،‬والنــاكل يقضــى عليــه‪ ،‬قــال صاحــب شــرح املنتهــى‪( :‬وإن‬\n‫ســكت مدعــى عليــه) بــأن لــم يقــر بالدعــوى ولــم ينكرهــا (أو قــال)‬\n‫املدعــى عليــه‪( :‬ال أقــر وال أنكــر أو) قــال‪( :‬ال أعلــم قــدر حقــه وال بينــة)‬\n‫ملــدع بدعــواه ( قــال احلاكــم ) ملدعــى عليــه‪( :‬إن أجبــت وإال جعلتــك‬\n‫نــاكال وقضيــت عليــك) بالنكــول‪ .)...‬ا‪.‬ه ـ ويف اإلنصــاف‪( :‬قولــه‪( :‬وإن‬\n\n\n                                                                                            ‫‪206‬‬\n\f      ‫ســكت املدعــى عليــه فلــم يقــر ولــم ينكــر‪ ،‬قــال لــه القاضــي‪ :‬إن أجبــت‬\n      ‫ال وقضيــت عليــك‪ ،‬وهــو املذهــب)‪ .‬ا‪ .‬ه ـ وألن امتنــاع‬      ‫وإال جعلتــك نــاك ً‬\n      ‫املدعــى عليــه عــن احلضــور يعـ ّـد إضــرار باملدعــي والضــرر يــزال؛ لقــول‬\n      ‫النبـ ّـي ـ صلــى اهلل عليــه وسـلّم ـ‪( :‬ال ضــرر وال ضــرار) رواه اإلمــام أحمــد‪،‬‬\n      ‫ويقضــى بهــا مــن غيــر‬   ‫البينــة ُ‬\n                                       ‫أن املمتنــع عــن احلضــور ُتســمع عليــه ّ‬   ‫ومبــا َّ‬\n      ‫ميــن االســتظهار‪ ،‬قــال صاحـ ُـب حتفــة احملتــاج يف شــرح املنهــاج‪( :‬وإال‬\n      ‫البينــة‬\n            ‫لتواريــه أو تعــززه أي‪ :‬تغلبــه وقــد ثبــت ذلــك عنــد القاضــي فتســمع ّ‬\n      ‫ويحكــم بغيــر حضــوره مــن غيــر ميــن لالســتظهار علــى املنقــول املعتمــد‬\n      ‫تغليظـ ًا عليــه‪ ،‬وإال المتنــع ال َّنــاس ك ّلهــم‪ ،‬فــإن لــم يكــن للمدعــي بينــة‬\n      ‫جعــل اآلخــر يف حكــم ال ّنــاكل فيحلــف املدعــي ميــن الــر ّد ـ خالف ـ ًا‬\n      ‫للمــاوردي ومــن تبعــه ـ ثــم يحكــم لــه)‪ ،‬ومبــا ان املدعــي وكالــة اقــام‬\n      ‫بينــة علــى اســتالم املدعــى عليــه للمبلــغ املدعــى بــه وقــدره‪ :‬خمســة‬\n      ‫وســبعون ألــف ريــال‪ ،‬وهــي‪ :‬اإلقــرار املرصــود أعــاه ونــص احلاجــة‬\n      ‫منــه‪( :‬واســتلمت مــن مورثهــم هــذا املبلــغ وقــدره خمســة وســبعون الــف‬\n      ‫ريــال ولــي منهــا مبلــغ داللــه خمســة وعشــرون الــف ريــال حســب العقــد‬\n      ‫مناصفــة يف مبلــغ الداللــة بينــي وبــن شــخص اســمه ‪ ........‬مينــي اجلنســية‬\n      ‫امــا مبلــغ خمســون الــف ريــال فقــد ســلمتها للبائــع ‪ ........‬وكيــل ورثــة‬\n      ‫‪ ........‬وقــد حصــل اتفــاق حيــث طلــب مــورث املدعــي مهلــة اســبوع ثــم‬\n      ‫تغيــب ومضــت املهلــة وعلمنــا بعــد ذلــك انــه تــويف بعدهــا بشــهر ) ا‪.‬ه ـ‬\n      ‫فقــد أقــر املدعــى عليــه باســتالمه كامــل املبلــغ املدعــى بــه ودفــع بتســلم‬\n      ‫مبلغــا قــدره‪ :‬خمســون ألــف ريــال لوكيــل ورثــة البائــع‪ ،‬ودفعــه هــذا ال‬\n      ‫يلتفــت إليــه إذ إنــه لــم يقــم بينــة علــى ذلــك‪ ،‬وبنــاء علــى املــادة اخلامســة‬\n      ‫واخلمســون مــن نظــام املرافعــات الشــرعية‪ ،‬لذلــك كلــه فقــد الزمــت‬\n\n\n‫‪207‬‬\n\f‫املدعــى عليــه اصالــه ‪ ........‬ســجل رقــم ‪ ........‬بتســليم املبلــغ املدعــى بــه‬\n‫وقــدره خمســة وســبعون الــف ريــال لورثــة ‪ ........‬وبذلــك قضيــت وهــذا‬\n‫احلكــم يعــد حضوريــا يف حــق املدعــى عليــه وباعــان احلكــم قــرر‬\n‫املدعــي وكالــة قناعتــة باحلكــم امــا املدعــى عليــه فســوف يبلــغ بنســخة‬\n‫مــن احلكــم واذا اســتلم احلكــم لشــخصه فلــه احلــق يف تقــدمي اعتراضــه‬\n‫ملــدة ثالثــن يــوم مــن تاريــخ اســتالمه احلكــم فــاذا مضــت هــذه املــدة ولــم‬\n‫يقــدم اعتراضــة ســقط حقــة يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫واذا اســتلمه لغيــر شــخصة رفــع احلكــم حملكمــة االســتئناف لتدقيقــة‬\n‫حســب التعليمــات وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/20‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة املســاعد بجــدة برقــم ‪32/759673‬‬\n‫وتاريــخ ‪1434/4/30‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ........‬القاضــي باحملكمــة العامــة مبحافظــة جــدة واملســجل بعــدد‬\n‫‪ 33459984‬وتاريــخ ‪ 1433/11/20‬هـ ـ واملتضمــن دعــوى‪ ........ /‬اصالــة‬\n     ‫عــن نفســه ووكالــة ضــد‪ ........ /‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم واهلل املوفق‪.‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                        ‫وســلم ‪،،،‬‬\n\n\n\n\n                                                                                        ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":201,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"da63ce8ea8234c9ac44504163d2a01fb232cad7f2e10a8d56b223a4b5f6d1466","normalized_text_hash":"64f98432fb8db67c3ad767c7798a56e1e5a186a5219b8d41409cc054866d4ba2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p201-33459984"},{"id":"cd540b26-4ff5-58aa-8303-500c339cd30e","document_type":"judgment","category":"judicial","subcategory":"general","title":"جعالة -مطالبة باسترداد أجرة جعالة لبطان عقد البيع -دفع بأن اجلعل ليس سعيا بل على اجلمع بن املتعاقدين -دفع بإقرار املدعي بأنه غير مسترد -احلكم برد اجلعل للمدعي لثبوت بطان العقد الذي أخذ اجلعل ألجله.","document_number":"34193570","case_number":"32534792","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"جعالة -مطالبة باسترداد أجرة جعالة لبطان عقد البيع -دفع بأن اجلعل ليس سعيا بل على اجلمع بن املتعاقدين -دفع بإقرار املدعي بأنه غير مسترد -احلكم برد اجلعل للمدعي لثبوت بطان العقد الذي أخذ اجلعل ألجله.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34193570 :‬تاريخه‪1434/4/21 :‬هـ‬\n                         ‫رقم الدعوى‪32534792 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34286360‬تاريخه‪1434/8/2 :‬هـ‬\n\n\n      ‫جعالــة ‪ -‬مطالبــة باســترداد أجــرة جعالــة لبطــان عقــد البيــع ‪ -‬دفــع‬\n      ‫بــأن اجلعــل ليــس ســعيا بــل علــى اجلمــع بــن املتعاقديــن ‪ -‬دفــع بإقــرار‬\n      ‫املدعــي بأنــه غيــر مســترد ‪ -‬احلكــم بــرد اجلعــل للمدعــي لثبــوت بطــان‬\n                                               ‫العقــد الــذي أخــذ اجلعــل ألجلــه‪.‬‬\n\n\n\n\n      ‫كا َنـ ْـت‬      ‫‪ .1‬البهوتــي كشــاف القنــاع يف بــاب الصــداق مــا نصــه‪َ « :‬و ِإ ْن َ‬\n      ‫ك ُأ ْجـ َـر ِة الـ َّـد َّللِ َو َن ْح ِو َهــا )‬          ‫ا ْل َع ِط َّي ـ ُة ل َِغ ْي ـ ِر ا ْل َعاقِ َد ْيـ ِـن ِب َسـ َـب ِب ا ْل َع ْقــدِ َ‬\n      ‫ك ُأ ْجـ َـر ِة ا ْل َك َّيــالِ َوا ْل ـ َو َّزانِ ( َقــالَ ا ْبـ ُـن َعقِ يــلٍ ) ِف ال َّن َظ ِر َّيــاتِ ( ْإن فُ ِسـ َـخ‬                       ‫َ‬\n      ‫اض) مِ ـ ْـن ا ْل َعاقِ َد ْيـ ِـن ( َلـ ْـم َيـ ُـر َّد ُه)‬  ‫ـف َع َلــى َتـ َـر ٍ‬    ‫مــا َيقِ ـ ُ‬  ‫َب ْيـ ٌـع ِب ِإ َقا َلـ ٍة َو َن ْح ِو َهــا ِ َّ‬\n      ‫أ َْي َلـ ْـم َيـ ُـر َّد الـ ّـدالل َمــا أ ََخـ َـذ ُه ( َوإال ) أ َْي َو ِإ ْن َلـ ْـم َيقِ ـ ْـف ا ْل َف ْسـ ُـخ َع َلــى‬\n        ‫كا ْل َف ْسـ ِـخ ل َِع ْيـ ٍـب َو َن ْحـ ِو ِه ( َر َّد ُه ) أ َْي َر َّد الــدالل َمــا أ ََخـ َـذ ُه َّ‬\n      ‫ألن‬                                                                                                                         ‫اضيهِ َمــا َ‬     ‫َت َر ِ‬\n                                                            ‫ْالَ ِبيـ َـع َو َقـ َـع ُم َتـ َـر ِّد ًدا َب ْي َنــا ال ُّل ـ ُزو ِم َو َع َدمِ ـهِ» أ‪.‬هــ‪.‬‬\n      ‫‪ .2‬مطالــب أولــي النهــى يف بــاب الشــروط يف البيــع ‪« :‬فَ ْصــلٌ ‪َ ( :‬و َمـ ْـن َبــا َع‬\n      ‫اع ـ ُه ؛ َلـ ْـم َي ْبـ َـر ْأ ‪َ ( ،‬أ ْو )‬ ‫يمــا َب َ‬  ‫ك ِّل َع ْيـ ٍـب ) فِ َ‬      ‫َش ـ ْي ًئا ( ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة مِ ـ ْـن ُ‬\n      ‫ان ِف ْالَ ِبيـ ِـع ( َلـ ْـم َي ْبـ َـر ْأ َبا ِئـ ٌـع)‬  ‫ك َ‬   ‫كـ َـذا ) ‪ْ ،‬إن َ‬       ‫ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ( مِ ـ ْـن َع ْيـ ِـب َ‬\n      ‫ـك ‪َ ،‬ولِ ُ ْش ـ َت ٍر ا ْل َف ْسـ ُـخ ِب َع ْيـ ٍـب َلـ ْـم ُي ْع َلـ ْـم َحا َل ـ َة َع ْقــدٍ ؛ لِ َــا َر َوى أ َْح َمـ ُـد‬           ‫ِب َذ ِلـ َ‬\n      ‫أ ََّن ا ْبـ َـن ُع َمـ َـر َبــا َع َز ْيـ َـد ْبـ َـن َثا ِبـ ٍـت َع ْبـ ًـدا ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ِب َث َم ِانِا َئـ ِة ِد ْر َهـ ٍـم‪،‬‬\n      ‫ـاب َز ْيـ ٌـد ِب ـ ِه َع ْي ًبــا ‪،‬فَ ـ َأ َرا َد َر َّد ُه َع َلــى ا ْبـ ِـن ُع َمـ َـر فَ َلـ ْـم َي ْق َب ْل ـ ُه ‪ ،‬فَ َت َرافَ َعــا‬\n                                                                                                                                             ‫فَ َأ َصـ َ‬\n      ‫ـك َلـ ْـم َت ْع َلـ ْـم ِب َهـ َـذا‬   ‫ـف َأ َّنـ َ‬‫ت ِلـ ُ‬ ‫ـان ِل ْبـ ِـن ُع َمـ َـر ‪ْ َ :‬‬  ‫ـان ‪ ،‬فَ َقــالَ ُع ْث َمـ ُ‬        ‫إ َلــى ُع ْث َمـ َ‬\n‫‪209‬‬\n\f                             ‫اع ـ ُه ا ْبـ ُـن ُع َمـ َـر ِب َأ ْلـ ِ‬\n‫ـف ِد ْر َهـ ٍـم ‪َ .‬و َهــذِ ِه‬                                    ‫ا ْل َع ْيـ ِـب ؟ َقــالَ ‪َ :‬ل ‪ ،‬فَ ـ َـر َّد ُه َع َل ْي ـ ِه ‪ ،‬فَ َب َ‬\n                                         ‫اش ـ َت َه َر ْت ‪َ ،‬و َلـ ْـم ُت ْن َكـ ْـر‪ ،‬فَ َكا َنـ ْـت كاإلجمــاع»‪.‬‬         ‫َق ِض َّي ـ ٌة ْ‬\n\n\n\n\n‫ادعــى املدعــى علــى املدعــى عليــه أنــه ســلمه مبلــغ (‪ )250.000‬ريــال‬\n‫أجــرة ســعي علــى عقــد شــراء أرض ‪ ،‬وقــد ظهــر بطــان العقــد وحكــم‬\n‫بحكــم يثبــت ذلــك واحلكــم مصــدق مــن محكمــة االســتئناف‪ ،‬وقــام‬\n‫البائــع بإعــادة ثمــن األرض وهمــش علــى الصــك بذلــك ولبطــان الصــك‬\n‫يطلــب املدعــى إلــزام املدعــى عليــه بــرد مــا ســلم لــه ‪ ،‬املدعــى عليــه‬\n‫صــادق علــى حصولــه علــى املبلــغ وقــرر أنــه ال يوافــق علــى رد املبلــغ ألنــه‬\n‫قبضــه بنــاء علــى عمــل ولــم يكــن ســعي بــل جعالــة والســعي يدفــع عنــد‬\n‫اإلفــراغ ويطلــب رد الدعــوى‪ ،‬وقــدم مذكــره بالــرد ومــا فيهــا مــن دفــاع‬\n‫وقــدم املدعــى احلكــم الصــادر بإبطــال البيــع ودفــع بعلــم املدعــى عليــه‬\n‫بحــال االرض محــل احلكــم مــن انهــا موقوفــه‪ ،‬رد املدعــى عليــه بأنــه‬\n‫علــم أن األرض محــل عقــد البيــع موقوفــه الحق ـ ًا بعــد اســتالمه للمبلــغ‪.‬‬\n‫ولتأمــل الدعــوى وإلقــرار املدعــى عليــه باســتالم املبلــغ مــن املدعــى‬\n‫مقابــل جعالــة شــرط اســتحقاقها احضــار البائــع والتوقيــع علــى عقــد‬\n‫شــراء األرض وملــا يثبــت باحلكــم الســابق بطــان البيــع الختــال شــرط‬\n‫مــن شــروط صحتــه وثبــت شــرع ًا عــدم انعقــاده ألجلــه فــإن ذلــك يــؤول‬\n‫لبطــان العــوض «اجلعــل» الــذي علــق اســتحقاقه عليــه علــى الصحيــح‬\n‫مــن كالم الفقهــاء أنــه ال اثــر ملــا دفــع بــه املدعــى عليــه مــن أنــه اســتحق‬\n‫العــوض مبوجــب عقــد جعالــه ال ســعي حيــث نــص علــى جــواز مطالبــة‬\n‫الدافــع بــرد العــوض املســلم لغيــر املتعاقديــن متــى كان بســبب العقــد‬\n\n                                                                                                                                              ‫‪210‬‬\n\f      ‫كأجــرة الــدالل والــوزان وكان الفســخ مــن غيــر تراضــي مــن الطرفــن‬\n      ‫جميع ـ ًا كاإلقالــة وهــذان الشــرطان يتحققــان يف هــذه الواقعــة محــل‬\n      ‫ا عــن أن اجلعالــة والســعي والداللــة الفــاظ ملســمى واحــد هــو‬\n                                                                        ‫النظــر فضـ ً‬\n      ‫«اجلعالــة» ‪ ،‬وعليــه فقــد حكــم علــى املدعــى عليــه بدفــع مبلــغ مائتــن‬\n      ‫وخمســن ألــف ريــال للمدعــى ويعــد احلكــم حضوري ـ ًا صــدق علــى‬\n                                              ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32534792‬وتاريــخ‬\n      ‫‪1432/11/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321434064‬وتاريــخ‬\n      ‫‪1432/11/12‬ه ـ ففــي يــوم الســبت ‪1433/06/21‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪11 : 41‬وفيهــا حضــر (‪ )......‬ويحمــل الســجل املدنــي رقــم (‪)......‬‬\n      ‫ا عــن (‪ )......‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬        ‫بصفتــه وكي ـ ً‬\n      ‫العدل الثانية شمال محافظة جدة برقم ‪ 48763‬وتاريخ ‪1432/5/29‬هـ‬\n      ‫واملخــول لــه فيهــا املخاصمــة واحملاكمــة ومتابعــة القضايــا املقامــة منــه‬\n      ‫أو ضــده واملدافعــة واملرافعــة وتقــدمي البينــات ‪...‬الــخ وحضــر حلضــوره‬\n      ‫املدعــى عليــه(‪ )......‬ويحمــل الســجل املدنــي رقــم (‪ )......‬وادعــى األول‬\n      ‫ا لقــد ســلم موكلــي لهــذا احلاضــر مائتــن وخمســن ألــف ريــال‬         ‫قائ ـ ً‬\n      ‫أجــرة ســعي علــى عقــد شــراء أرض يف (‪ )......‬مــن (‪ )......‬أصالــة عــن‬\n      ‫نفســه وبوكالتــه عــن موكليــه وقــد ظهــر بطــان العقــد وحكــم‬\n      ‫بحكــم يثبــت ذلــك مــدون علــى الصــك املســجل برقــم ‪5/200/134‬‬\n\n‫‪211‬‬\n\f‫وتاريــخ ‪1431/7/30‬ه ـ واملصــدق مــن محكمــة االســتئناف بالقــرار‬\n‫رقــم ‪ 32262057‬وتاريــخ ‪1432/10/4‬ه وقــام البائــع بإعــادة ثمــن األرض‬\n‫وهمــش علــى الصــك بذلــك لــذا وحيــث ظهــر بطــان العقــد لــذا فــإن‬\n‫موكلــي يطلــب إلــزام املدعــى عليــه بإعــادة مــا ســلم لــه مائتــن وخمســن‬\n‫ألــف ريــال هــذه دعــواي وباســتجواب املدعــى عليــه قــال مــا ذكــره‬\n‫املدعــي مــن أنــي اســتلمت مائتــن وخمســن ألــف ريــال بخصــوص أرض‬\n‫يف (‪ )......‬مــن (‪ )......‬صحيــح إال أنــي ال أوافــق علــى رد املبلــغ ألنــه مت‬\n‫القبــض بنــاء علــى عمــل كمــا أن املبلــغ لــم يكــن ســعي بــل جعالــة وامنــا‬\n‫الســعي يدفــع عنــد افــراغ األرض مت لــذا فإنــي أطلــب رد دعــواه فســألته‬\n‫اجلعالــة كان علــى مــاذا فأجــاب علــى احضــار البائــع إلــى بيــت املدعــي‬\n‫شــخصي ًا واقناعــه بالتوقيــع علــى العقــد أ‪.‬ه ـ وبعرضــه علــى وكيــل‬\n‫املدعــي قــال مــا ذكــره غيــر صحيــح والصحيــح بأنــه كان ســعي ًا وبينتي‬\n‫علــى ذلــك نــص شــهادته يف صــك احلكــم حيــث أقــر بأنــه كان ســعي ًا‬\n‫أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه قــال الصحيــح بأنــه لــم يكــن ســعي ًا‬\n‫وامتســك مبــا ورد يف هــذا العقــد وأبــرز مذكــره جوابيــه جــاء فيــه مــا‬\n‫نصــه (أو ًال ‪ :‬أن املدعــي طلــب منــي البحــث عــن صاحــب األرض مــدار‬\n‫الدعــوى وان اجمعــه بالبايــع والوقــوف عليهــا ويف حالــة حتقيــق ذلــك‬\n‫وتوقيــع البائــع علــى عقــد البيــع يدفــع لــي جعالــة قدرهــا ‪ 250000‬ريــال‬\n‫مائتــان وخمســون ألــف ريــال وهــذه اجلعالــة وليــس ســعي وامنــا الســعي‬\n‫كمــا يتضــح لفضيلتكــم مــن أعقــد االتفــاق املرفــق تدفــع عنــد افــراغ‬\n‫األرض املذكــورة واحلــاق األطــوال واملســاحة اإلجماليــة عليهــا وأن املبلــغ‬\n‫املدعــى بــه ال يــرد وال يســترجع وحــرر عــن ذلــك عقــد اتفــاق مــؤرخ يف‬\n‫‪1426/11/11‬ه ـ موقــع عليــه مــن املدعــي وعليــه ختــم مؤسســته إال أن‬\n\n\n                                                                                     ‫‪212‬‬\n\f      ‫املدعــي ناقــض العقــد والعقــد‪ .‬ثانيـ ًا ‪ :‬القاعــدة الشــرعية (مــن ســعى الــى‬\n      ‫نقــض مــا مت مــن جهتــه فســعيه مــردود عليــه) فاملدعــي اتفــق معــي علــى‬\n      ‫أن املبلــغ املدعــى بــه هــو جعالــة ال تــرد وال تســترجع وحــرر عــن ذلــك عقــد‬\n      ‫اتفــاق ونــص عليــه يف البنــد الرابــع منــه‪ .‬ثالثــا ‪ :‬اننــي جمعتــه بصاحــب‬\n      ‫األرض وقــد مت التوقيــع علــى عقــد البيــع بتاريــخ ‪1426/11/11‬ه ـ بــن‬\n      ‫املدعــي وبــن البائــع واصبــح املبلــغ املدعــى بــه جعالــة حتققــت شــروطها‬\n      ‫وصيغتهــا الشــرعية وال يحــق للمدعــي املطالبــة بهــا شــرع ًا ‪ .‬رابعـ ًا ‪ :‬البينة‬\n      ‫حجــة متعديــة واإلقــرار حجــة قاصــرة واإلقــرار شــرع ًا أقــوى يف االثبــات‬\n      ‫مــن الشــهادة الن الشــهادة اخبــار عــن حــس أمــا اإلقــرار فهــو انشــاء‬\n      ‫وكــون املدعــي أقــر مبوجــب إقــرار خطــي بــأن هــذا املبلــغ املدعــى بــه‬\n      ‫هــو جعالــة غيــر مســترد وغيــر مســترجع وأن الســعي لــم يتــم دفعــه الن لــم‬\n      ‫يتــم اكمــال البيــع حســب االتفــاق املبــرم واحملــرر بــن املدعــي والبائــع‬\n      ‫وكذلــك عقــد االتفــاق الــذي بينــه وبــن املدعــي‪ .‬خامس ـ ًا ‪ :‬ملــا كان‬\n      ‫اإلقــرار حجــة قاصــرة علــى املقــر وأن القاعــدة الشــرعية التــي تنــص‬\n      ‫علــى أن العقــد شــريعة املتعاقديــن اعمــا ًال لقولــه تعالــى (يــا أيهــا الذيــن‬\n      ‫آمنــوا أوفــوا بالعقــود) ولعمــوم قــول النبــي صلــى اهلل عليــه وســلم‬\n      ‫«املؤمنــون علــى شــروطهم»وأن الثابــت بينــي وبــن املدعــي العقــد املبــرم‬\n      ‫بيننــا واملشــروط فيــه بــأن املبلــغ املدعــى بــه ال يــرد وال يســترجع ألنــه‬\n      ‫جعالــة إلحضــار البائــع وجمعــه مــع املدعــي واحضــار العقــود واملســتندات‬\n      ‫والتفــاوض مــع البائــع لتســهيل البيــع للمدعــي علــى أن يتــم دفــع الســعي‬\n      ‫بعــد اإلفــراغ ولكــن املدعــي خالــف قــول اهلل تعالــى [وليملــل الــذي عليــه‬\n      ‫احلــق وليتــق اهلل ربــه وال يبخــس منــه شــيئا]‪ .‬سادسـ ًا ‪ :‬ان املدعــي تناقــض‬\n      ‫يف دعــواه تناقض ـ ًا يبطلهــا وقاصــد ًا مــن ذلــك االضــرار والكيــد بــي‬\n\n\n‫‪213‬‬\n\f‫وذلــك ألنــه طلبنــي يف الشــهادة ضــد البائــع ولكنــي شــهدت احلقيقــة‬\n‫والواقــع وكانــت هــذه الشــهادة ال تلــق قبولــه ‪ .‬فضيلــة الشــيخ (‪)...‬‬\n‫حفظــه اهلل أن الدعــوى واضحــة فهــي دعــوى كيديــة فكيــف للمدعــي‬\n‫أن يســلمني املبلــغ املذكــور جعالــة إلحضــار البائــع ولقائــه بــه ووقوفــه‬\n‫علــى املوقــع وبــذل مجهــود شــاق حتــى وقــع علــى عقــد البيــع وقــد وافــق‬\n‫ومبحــض إرادتــه أن املبلــغ املدعــى بــه ليــس ســعي ًا وال جــزء مــن الســعي‬\n‫ولكنــه جعالــة علــى عمــل محــدد إذا مت هــذا العمــل واالتفــاق مبوجــب‬\n‫إقــرار موثــق بعقــد وأصبحــت اجلعالــة مســتحقة وملزمــة‪ .‬اتفــق القائلــون‬\n‫باجلعالــة علــى أن عقــد اجلعالــة بعــد متــام العمــل يصبــح الزمــا ألنــه ال أثــر‬\n‫يترتــب علــى رجــوع اجلاعــل عــن العقــد أو تــرك العامــل العمــل حينئــذ ألن‬\n‫اجلعــل قــد لــزم واســتقر علــى اجلاعــل وحيــث أن مــا مت االتفــاق عليــه مــن‬\n‫األعمــال املتعاقــد عليهــا يف عقــد اجلعالــة فإنــه يلــزم اجلعالــة بعــد متــام‬\n‫العمــل لــذا فأننــي اطلــب مــن فضيلتكــم احلكــم بصــرف النظــر عــن‬\n‫دعــوى املدعــي واخــاء ســبيلي مــن الدعــوى) وأضــاف بأنــه متمســك يف‬\n‫الفقــرة الرابعــة بــأن املبلــغ ال يــرد وال يســترجع وأن أجــرة الســعي يف‬\n‫الفقــرة الرابعــة «أ‪.‬ه ـ ثــم حضــر وكيــل املدعــي واملدعــى عليــه أصالــة‬\n‫وقــد جــرى اإلطــاع علــى الوثيقــة املؤرخــة يف ‪1426/11/11‬ه ـ ونصهــا‬\n‫(احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪،،،‬‬\n‫أنه يف يوم االثنني ‪ 11‬ذو القعدة ‪1426 ،‬هـ املوافق ‪12‬ديسمبر ‪2005،‬م‬\n‫بعــون اهلل وتوفيقــه قــد اتفــق كل مــن ‪ -:‬الطــرف األول ‪ )......( -:‬حامــل‬\n‫حفيظــة رقــم (‪ )......‬تاريــخ ‪1402/11/17‬ه ـ إصــدار مكــة املكرمــة ‪.‬‬\n‫الطرف الثاني ‪ )......( -:‬حامل حفيظة رقم (‪ )......‬بتاريخ ‪1392/11/1‬هـ‬\n‫إصــدار مكــة املكرمــة ‪ .‬متهيــد حيــث أن الطــرف األول ســعى وأحضــر‬\n\n\n                                                                                          ‫‪214‬‬\n\f      ‫األرض الواقعــة يف طريــق (‪ )......‬اململوكــة بالصــك رقــم (‪ )......‬والصــك‬\n      ‫رقــم (‪ )......‬واملســجلة يف محكمــة الليــث برقــم ‪ 58‬و‪59‬بتاريــخ ‪1347‬ه ـ‬\n      ‫البالــغ مســاحتها (‪ )321000000‬متــر مربــع‪( ،‬فقــط ثالثمائــة وواحــد‬\n      ‫وعشــرين مليــون متــر مربــع تقريبــا) عليــه فقــد إتفــق الطرفــان علــى مــا‬\n      ‫يلــي ‪ -:‬أو ًال يعتبــر التمهيــد جــزء مــن العقــد ‪ .‬ثانيـ ًا ‪ :‬يلتــزم الطــرف الثانــي‬\n      ‫بدفــع مبلــغ وقــدره (‪ )250.000‬ريــال ‪ ،‬فقــد مائتــان وخمســون ألــف‬\n      ‫ريــال عنــد توقيــع عقــد األرض املذكــورة أعــاه ‪.‬ثالث ـاً‪ :‬يلتــزم الطــرف‬\n      ‫الثانــي بدفــع مبلــغ وقــدره (‪)20000000‬ريــال‪ ،‬فقــط عشــرون مليــون‬\n      ‫ريــال ســعودي عنــد إفــراغ األرض املذكــورة أعــاه وإحلــاق األطــوال‬\n      ‫واملســاحة اإلجماليــة عليهــا‪ .‬رابع ـ ًا ‪ :‬املبلــغ املدفــوع للســعاة عنــد توقيــع‬\n      ‫العقــد ال يــرد وال يســترجع ‪ .‬طــرف أول (‪ )......‬توقيعــه‪ ،‬طــرف ثانــي‬\n      ‫(‪ )......‬توقيعــه ‪ ،‬ختــم مؤسســة (‪ )......‬أ‪.‬ه ـ وبعرضهــا علــى وكيل املدعي‬\n      ‫قــال إن موكلــي يقــر بــأن هــذه الوثيقــة صحيحــة ومنطوقهــا نــص صريح‬\n      ‫يف أن املبلــغ املســلم كان مقابــل ســعي أمــا مــا ورد يف الفقــرة الرابعــة‬\n      ‫فموكلــي يطلــب عــدم االلتفــات لهــا لكونــه غــار ًا حيــث كان يعلــم أن‬\n      ‫علــى األرض ايقافـ ًا ولــم يخبــر بذلــك موكلــي أ‪.‬هـ وبعرضــه على املدعى‬\n      ‫عليــه قــال مــا ذكــره بأنــي كنــت أعلــم بحــال األرض وأن التصــرف‬\n      ‫فيهــا موقــوف غيــر صحيــح أ‪.‬ه ـ وبعرضــه علــى املدعــي قــال الصحيــح مــا‬\n      ‫ادعيــت بــه مــن أنــه يعلــم ولــدي البينــة أ‪.‬ه ـ وأبــرز صــورة الصــك الصــادر‬\n      ‫مــن هــذه احملكمــة برقــم ‪ 5/200/134‬وتاريــخ ‪1431/7/30‬ه ـ‬\n      ‫بخصــوص دعــوى موكلــه ضــد البائــع وقــد جــاء يف شــهادته مــا نصــه‬\n      ‫(‪ )......‬بالســجل املدنــي رقــم (‪ )......‬وطلــب ســماع مــا لديــه مــن شــهادة‬\n      ‫فأذنــت بذلــك وشــهد قائــا أشــهد بــاهلل العظيــم أنــي كنــت الوســيط‬\n\n\n‫‪215‬‬\n\f‫بــن (‪ )......‬و(‪ )......‬يف بيــع األرض الواقعــة بالليــث وقــد إجتمعنــا يف منــزل‬\n‫(‪ )......‬يف مســاء ‪1426/11/11‬ه ـ وقــد جــرى التفــاوض علــى البيــع‬\n‫واتفقــا علــى بيعهــا مبائــة مليــون ريــال واختلفــا علــى الدفعــة األولــى‬\n‫فــكان (‪ )......‬يطلــب املزيــد فتراضيــا علــى أن تكــون الدفعــة األولــى‬\n‫حســبما هــو مــدون يف العقــد احملــرر يف ذلــك اليــوم مليونــن وســتمائة أو‬\n‫ســبعمائة ألــف ال أذكــر حتديــدا ولكنــه مقــارب لهــذا املبلــغ وتكــون‬\n‫غيــر مســترجعة بحــال مــن األحــوال حتــى ولــو لــم يتمكــن (‪ )......‬مــن‬\n‫اســتخراج صــك عليهــا أي تكــون مــن زكاة مالــه وقــام (‪ )......‬وبنــاء‬\n‫علــى هــذا االتفــاق باســتالم مبلــغ مبوجــب شــيكني وجــرى التوقيــع علــى‬\n‫العقــد األول وبعــد مضــي فتــرة اتصــل بــي (‪ )......‬وطلــب منــي إقنــاع (‪)......‬‬\n‫بتوقيــع عقــود أخــرى حيــث طلــب مكتــب (‪ )......‬تغييــر صيغــة العقــد‬\n‫صوريــا لتســهيل األمــر حســب قولــه وكان (‪ )......‬يرفــض ذلــك فجــرى‬\n‫إقناعــه مــن قبلــي بعدمــا وعدتــه بــأن آتيــه بورقــة مضــادة مــن قبــل (‪)......‬‬\n‫للتحقــق مــن جعلهــا صوريــة هــذا مــا حصــل فقــد حضــر لــدي (‪ )......‬أحــد‬\n‫املوظفــن لديــه وســلم لــي عقديــن بثمانــن مليون ـ ًا كل عقــد بأربعــن‬\n‫وقمنــا بإيصالهــا إلــى (‪ )......‬ووقــع عليهمــا وبعــد توقيعــي عليهــا أعدناهــا‬\n‫إلــى (‪ )......‬بعــد مــا صــاغ لــي (‪ )......‬الورقــة امللغيــة لهذيــن العقديــن‬\n‫الصوريــة وقــام مكتــب (‪ )......‬بطباعتهــا وضمهــا ثــم عرضهــا علــى‬\n‫املدعــي فقــام بالتوقيــع عليهــا وأعدتهــا إلــى (‪ )......‬هــذا مــا لــدي وبــه‬\n‫أشــهد‪ .‬فســألت الشــاهد هــل قــام البائــع بإخطــاره عمــا حصــل لــأرض‬\n‫ســابق ًا مــن أوامــر ونحوهــا؟ قــال‪ :‬نعــم لقــد أخبــره بــأن أحــد أفــراد‬\n‫األســرة املالكــة حــاول أن يســتخرج صــكا عليهــا إال إنــه لــم يتمكــن‪،‬‬\n‫أخبــره بذلــك قبــل التوقيــع علــى العقــد األول عندمــا كنــا يف اســتراحة‬\n\n\n                                                                                        ‫‪216‬‬\n\f      ‫(‪،)......‬كما أخبره بوجود اعتداءات عليها‪ ،‬واستعد (‪ )....‬بتعويضهم‪،‬‬\n      ‫وطلــب مــن البائــع أن يتنــازل عــن جــزء مــن األرض مقابــل مــا ســيتم‬\n      ‫تعويــض املعتديــن عليهــا ‪.‬أ‪.‬ه ـ فجــرى عــرض صــورة العقــد املبــرز مــن قبل‬\n      ‫وكيــل املدعــي علــى الشــاهد فقــرر بــأن هــذا العقــد هــو أحــد العقــود‬\n      ‫الصوريــة ال احلقيقيــة والعقــد احلقيقــي املعتمــد هــو العقــد األول مبائــة‬\n      ‫مليــون )أ‪.‬ه ـ وبعرضــه عليــه قــال مــا جــاء يف الشــهادة صحيــح وقــد علمــت‬\n      ‫بحالهــا الحق ـ ًا ووقــت اســتالمي للمبلــغ لــم أكــن أعلــم أ‪.‬ه ـ وبعرضــه‬\n      ‫علــى وكيــل املدعــي قــال الصحيــح مــا ادعيــت بــه أ‪.‬ه ـ ويف يــوم األحــد‬\n      ‫‪1434/4/7‬ه ـ فتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر‬\n      ‫وكيــل املدعــي ولــم يحضــر املدعــى عليــه ولــم يتقــدم بعــذر مقبــول حتــى‬\n      ‫اآلن عليــه وبعــد قفــل بــاب املرافعــة وتأمــل الدعــوى واإلجابــة وإلقــرار‬\n      ‫املدعــى عليــه بأنــه اســتلم مــن املدعــي مئتــن وخمســن ألــف ريــال مقابــل‬\n      ‫جعالــة شــرط اســتحقاقها احضــار البائــع والتوقيــع علــى عقــد شــراء‬\n      ‫األرض جــاء ذلــك نصــا يف مذكرتــه املدونــة يف اجللســة األولــى بقولــه «‬\n      ‫ويف حالــة حتقــق ذلــك وتوقيــع البائــع علــى عقــد البيــع يدفــع لــي جعالــة‬\n      ‫قدرهــا مئتــن وخمســن ألــف ريــال « عليــه وألن مجــرد احضــار البائــع‬\n      ‫أمــر تبعــي املقصــود منــه غايتــه وهــو « التوقيــع علــى العقــد « فيســتحق‬\n      ‫املدعــى عليــه اجلعــل مبجــرده ولــو لــم يتحقــق اللقــاء بينهمــا ‪ ،‬عليــه وملــا‬\n      ‫ثبــت باحلكــم الســابق بطــان هــذا البيــع الختــال شــرط مــن شــروط‬\n      ‫صحتــه وثبــت شــرع ًا عــدم انعقــاده ألجلــه فــإن ذلــك يــؤول لبطــان‬\n      ‫العــوض «اجلعــل» الــذي علــق اســتحقاقه عليــه علــى الصحيــح مــن كالم‬\n      ‫الفقهــاء قــال البهوتــي ‪ -‬رحمــه اهلل‪ -‬يف كشــاف القناع يف باب الصداق‬\n                    ‫كا َنـ ْـت ا ْل َع ِط َّيـ ُة ِل َغ ْيـ ِـر ا ْل َعاقِ َد ْيـ ِـن ِب َسـ َـب ِب ا ْل َع ْقــدِ َ‬\n      ‫ك ُأ ْجـ َـر ِة‬                                                                                              ‫مــا نصــه ‪َ ( »:‬و ِإنْ َ‬\n\n‫‪217‬‬\n\f‫ك َّيــالِ َوا ْلـ َـو َّزانِ ( قَ ــالَ ا ْبـ ُـن َعقِ يـ ٍـل ) ِف‬                          ‫ك ُأ ْجـ َـر ِة ا ْل َ‬  ‫الـ َّـد َّللِ َون َْح ِو َهــا) َ‬\n   ‫اض) مِ ــنْ‬  ‫ـف َع َلــى َتـ َـر ٍ‬          ‫مــا َيقِ ـ ُ‬  ‫ـات ( إنْ ُف ِسـ َـخ َب ْيـ ٌـع ِب ِإقَ ا َل ـ ٍة َون َْح ِو َهــا ِ َّ‬        ‫ال َّن َظ ِر َّيـ ِ‬\n‫ا ْل َعاقِ َد ْيـ ِـن ( َلـ ْـم َيـ ُـر َّد ُه ) َأ ْي َلـ ْـم َيـ ُـر َّد الـ َّـد َّللُ َمــا َأ َخـ َـذ ُه ( َو ِإ َّل ) َأ ْي َو ِإنْ َلـ ْـم‬\n‫(ر َّد ُه) َأ ْي َر َّد‬   ‫كا ْل َف ْسـ ِـخ ل َِع ْيـ ٍـب َون َْح ـ ِو ِه َ‬               ‫اضيه َِمــا َ‬       ‫ـف ا ْل َف ْسـ ُـخ َع َلــى َت َر ِ‬       ‫َيقِ ـ ْ‬\n‫وم َو َع َدمِ ـ ِه «أ‪.‬ه ـ وهــذا‬                                                                                 ‫الـ َّـد َّللُ َمــا َأ َخـ َـذ ُه ِ َل َّن ْ َ‬\n                                                 ‫ال ِبيـ َـع َوقَ ـ َـع ُم َتـ َـر ِّد ًدا َب ْي َنــا ل ُّلـ ُـز ِ‬\n‫النــص الفقهــي العــام يبــن لنــا أنــه ال أثــر ملــا دفــع بــه املدعــى عليــه مــن أنــه‬\n‫اســتحق العــوض مبوجــب عقــد اجلعالــة ال ســعي حيــث نــص علــى جــواز‬\n‫مطالبــة الدافــع بــرد العــوض املســلم لغيــر املتعاقديــن متــى كان بســبب‬\n‫العقــد كأجــرة الــدالل والكيــال والــوزان وكان الفســخ مــن غيــر‬\n‫تــراض مــن الطرفــن جميعــا كاإلقالــة وهــذا الشــرطان متحققــان يف‬\n‫هــذه الواقعــة محــل النظــر ‪ ،‬فضــا عــن أن « اجلعالــة والســعي والداللــة»‬\n‫ألفــاظ ألصــل شــرعي واحــد هــو «اجلعالــة « فــإن اختلفــت األســماء‬\n‫فاملســمى واحــد ‪ ،‬وأمــا الدفــع اآلخــر الــذي متســك بــه املدعــى عليــه وهــو‬\n‫إقــرار املدعــي بــأن املبلــغ املســلم ال يــرد وال يســترجع فاألظهــر بأنــه‬\n‫شــرط غيــر صحيــح ألن إســقاط احلــق قبــل ســببه لغــو ال أثــر لــه وهــو ال‬\n‫يســتحق اجلعــل بعــد تســليمه للعامــل « املدعــى عليــه « إال بعــد ثبــوت‬\n‫بطــان البيــع ونظيــره مــن الشــروط الفاســدة وأقربــه إليــه البيــع بشــرط‬\n‫البــراءة مــن العيــب فــإن الصحيــح مــن كالم أهــل العلــم أن الشــرط‬\n‫باطــل ال أثــر إلشــتراطه يف اســقاط حــق خيــار العيــب للمشــتري ‪ ،‬قــال‬\n‫يف مطالــب أولــي النهــى يف بــاب الشــروط يف البيــع ‪َ »:‬ف ْصــلٌ ‪َ ( :‬و َمــنْ َبــا َع‬\n‫اعـ ُه ؛ َلـ ْـم َي ْبـ َـر ْأ ‪َ ( ،‬أ ْو )‬        ‫يمــا َب َ‬    ‫كلِّ َع ْيـ ٍـب ) فِ َ‬           ‫) َشـ ْيئًا ( ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة مِ ــنْ ُ‬\n‫ال ِبيـ ِـع ( َلـ ْـم َي ْبـ َـر ْأ َبا ِئـ ٌـع‬\n                                             ‫ان ِف ْ َ‬      ‫ك َ‬    ‫كـ َـذا ) ‪ ،‬إنْ َ‬                 ‫ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ( مِ ــنْ َع ْيـ ِـب َ‬\n‫) ِب َذ ِلـ َـك ‪َ ،‬ولِ ُْشـ َت ٍر ا ْل َف ْسـ ُـخ ِب َع ْيـ ٍـب َلـ ْـم ُي ْع َلـ ْـم َحا َلـ َة َع ْقــدٍ ؛ لِ َــا َر َوى َأ ْح َمـ ُـد َأ َّن‬\n\n\n                                                                                                                                                                   ‫‪218‬‬\n\f      ‫ا ْبـ َـن ُع َمـ َـر َبــا َع َز ْيـ َـد ْبـ َـن ثَا ِبـ ٍـت َع ْبـ ًـدا ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ِبث ََمانِ ِا َئ ـ ِة د ِْر َهـ ٍـم ‪،‬‬\n      ‫‪،‬فـ َأ َرا َد َر َّد ُه َع َلــى ا ْبـ ِـن ُع َمـ َـر َف َلـ ْـم َي ْق َب ْلـ ُه ‪َ ،‬ف َت َر َاف َعــا‬\n                                                                                                          ‫ـاب َز ْيـ ٌـد ِبـ ِه َع ْي ًبــا َ‬‫َف َأ َصـ َ‬\n      ‫ـف َأ َّنـ َـك َلـ ْـم َت ْع َلـ ْـم ِب َهـ َـذا ا ْل َع ْيـ ِـب‬                                  ‫ـان ‪َ ،‬ف َقــالَ ُع ْث َمـ ُ‬\n                                                                           ‫ـان ِل ْبـ ِـن ُع َمـ َـر ‪ْ َ :‬‬\n                                                                     ‫ت ِلـ ُ‬                                                            ‫إ َلــى ُع ْث َمـ َ‬\n      ‫ـف د ِْر َهـ ٍـم َ‪.‬و َهــذِ ِه قَ ِض َّي ـ ٌة‬      ‫اع ـ ُه ا ْبـ ُـن ُع َمـ َـر ِب َأ ْلـ ِ‬\n                                                                                               ‫؟ قَ ــالَ ‪َ :‬ل ‪َ ،‬فـ َـر َّد ُه َع َل ْي ـ ِه ‪َ ،‬ف َب َ‬\n      ‫اع»‪.‬وهــذا علــى فــرض أن‬                                  ‫ال ْج َم ِ‬‫ك ِْ‬ ‫كا َنـ ْـت َ‬      ‫كـ ْـر‪َ ،‬ف َ‬                                         ‫ْ‬\n                                                                                                                    ‫اش ـ َت َه َر ْت ‪َ ،‬و َلـ ْـم ُت ْن َ‬\n      ‫العبــارة تشــمل الواقعــة محــل النظــر وإال فإنــه يــرد احتمــال قــوي بــأن‬\n      ‫مرادهمــا مــا لــو عجــز املشــتري عــن إحلــاق الــذرع علــى الصــك فإنــه ال‬\n      ‫يحــق املطالبــة باســترداد اجلعــل « العــوض « وهــذا ظاهــر إذ ال يســتحق‬\n      ‫حينهــا املطالبــة بــرده ألنــه ال يلــزم مــن عــدم قدرتــه علــى ذلــك بطــان بيــع‬\n      ‫العــن والشــرط جــاء ل ــتأكيد هــذا األمــر وهــذا االحتمــال الــوارد علــى‬\n      ‫اللفــظ يضعــف أيضــا األخــذ بإطالقــه مــع مــا تقــدم ‪ ،‬عليــه وملجمــوع مــا‬\n      ‫تقــدم فقــد حكمــت علــى املدعــى عليــه (‪ )......‬بدفــع مائتــن وخمســن‬\n      ‫ألــف ريــال للمدعــي (‪ )......‬عليــه وألن تخلفــه بعــد تبلغــه لشــخصه مبوعــد‬\n      ‫اجللســة وســماع جوابــه فيعــد احلكــم حضوريــا وجــرى النطــق بــه يف يــوم‬\n      ‫‪1434/4/7‬ه ـ وأمــرت بإخــراج صــك مبوجبــه وبعــث صورتــه للمدعــى‬\n      ‫عليــه لــه مــن بعــد اســتالمه لهــا ثالثــون يومــا يقــدم خاللهــا الئحتــه‬\n      ‫اإلعتراضيــة فــإن لــم يفعــل يســقط حقــه يف اإلعتــراض ويكتســب‬\n      ‫احلكــم الصفــة القطعيــة وأقفلــت اجللســة الســاعة احلادية عشــرة ‪ .‬وصلى‬\n                                               ‫اهلل وسلم على نبينا محمد وعلى آله وصحبه أجمعني‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبكــة املكرمــة ففــي يــوم األحــد ‪1434/09/06‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الواحــدة ظهــرا بعدمــا وردتنــا املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫بالقــرار رقــم ‪ 34286360‬وتاريــخ ‪1434/08/02‬ه ـ ونــص احلاجــة‬\n\n\n‫‪219‬‬\n\f‫منــه (وبدراســة احلكــم وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم) قاضــي اســتئناف (‪ )......‬ختمــه‬\n‫وتوقيعــه ‪ ،‬قاضــي اســتئناف (‪ )......‬ختمــه وتوقيعــه ولــه وجهــة نظــر‪،‬‬\n‫رئيــس الدائــرة (‪)......‬ختمــه وتوقيعــه ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/9/6‬ه ـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ (‪ )......‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫املســجل بعــدد ‪ 34193570‬وتاريــخ ‪ 1434/4/21‬املتضمــن دعــوى (‪)......‬‬\n‫ضــد (‪ )......‬احملكــوم في ــه مبــا دون باطــن الصــك‪ ،‬وبدراســة احلكــم‬\n‫وص ــورة ضبط ــه والئحتــه االعتراضيــة تق ــرر باألكثريــة املوافق ــة عل ــى‬\n‫احلكــم‪ .‬وبــاهلل التوفيــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه‬\n                                                              ‫وصحب ــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪220‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":209,"source_page_end":220,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cdf3970588d4e05a3223b8c4c9de041e46ce3b6309ad4ddd1263a06d519cb259","normalized_text_hash":"d7e00379204599748ef1dff08964c1f8da3d678564600f743513e99da9eb1834","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p209-34193570"},{"id":"48497706-45ee-50ec-a1c4-4930a730889f","document_type":"judgment","category":"judicial","subcategory":"general","title":"عمالة -مطالبة برسوم استقدام خادمة -مت ارجاعها ملكتب اخلدمات -حضور املدعى عليه -جلنة صلح -الصلح على مبلغ معن لم يلتزم به املدعى عليه عدم حضور املدعى عليه جلسة احلكم رغم تبليغه باملوعد حلف املدعي على املبلغ الذي دفعه األدلة الشرعية دلت على أنه لو لم يحكم على املستتر جلعل ال لتضييع احلقوق احلكم على املدعى عليه بدفع االستتار سبي املبلغ للمدعي -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى","document_number":"34168504","case_number":"33136578","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"عمالة -مطالبة برسوم استقدام خادمة -مت ارجاعها ملكتب اخلدمات -حضور املدعى عليه -جلنة صلح -الصلح على مبلغ معن لم يلتزم به املدعى عليه عدم حضور املدعى عليه جلسة احلكم رغم تبليغه باملوعد حلف املدعي على املبلغ الذي دفعه األدلة الشرعية دلت على أنه لو لم يحكم على املستتر جلعل ال لتضييع احلقوق احلكم على املدعى عليه بدفع االستتار سبي املبلغ للمدعي -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34168504 :‬تاريخه ‪1434/3/22 :‬هـ‬\n                        ‫رقم الدعوى ‪33136578 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34289497‬تاريخه‪1434/8/7 :‬هـ‬\n\n\n      ‫عمالــة ‪ -‬مطالبــة برســوم اســتقدام خادمــة ‪ -‬مت ارجاعهــا ملكتــب‬\n      ‫اخلدمــات ‪ -‬حضــور املدعــى عليــه ‪ -‬جلنــة صلــح ‪ -‬الصلــح علــى مبلــغ‬\n      ‫معــن لــم يلتــزم بــه املدعــى عليــه ـ عــدم حضــور املدعــى عليــه جلســة‬\n      ‫احلكــم رغــم تبليغــه باملوعــد ـ حلــف املدعــي علــى املبلــغ الــذي دفعــه‬\n      ‫ـ األدلــة الشــرعية دلــت علــى أنــه لــو لــم يحكــم علــى املســتتر جلعــل‬\n      ‫ال لتضييــع احلقــوق ـ احلكــم علــى املدعــى عليــه بدفــع‬  ‫االســتتار ســبي ً‬\n      ‫املبلــغ للمدعــي ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى‬\n                                                                             ‫عليــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬ما روى أبو موسى األشعري ـ رضي اهلل عنه ـ قال ‪ ( :‬كان اخلصمان‬\n      ‫إذا اختصمــا إلــى رســول اهلل صلــى اهلل عليــه وســلم فاتعــدا املوعــد فوفــى‬\n      ‫أحداهمــا ولــم يــوف اآلخــر قضــى للــذى وفــى ) أخرجــه الطبرانــي يف‬\n                                                                              ‫األوســط ‪.‬‬\n      ‫ال لتضييــع احلقوق‬    ‫‪ .2‬لــو لــم يحكــم علــى املســتتر جلعــل االســتتار ســبي ً‬\n                                                        ‫( الشــرح الكبير ‪. ) 508/28‬‬\n      ‫‪ .3‬املــادة (‪ )55‬و (‪ )103‬مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n                                                                         ‫التنفيذيــة ‪.‬‬\n\n\n\n‫‪221‬‬\n\f‫حضــر املدعــي ولــم يحضــر املدعــى عليــه رغــم إبالغــه عــدة مــرات‬\n‫ـ ورغــم حضــوره جلســة جلنــة الصلــح باحملكمــة ـ بنــاء علــى املــادة‬\n‫(‪ )55‬مــن نظــام املرافعــات قــرر ناظــر الدعــوى ســماع الدعــوى ـ ادعــى‬\n‫املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه قــد ســلمه‬\n‫مبلــغ وقــدره ســبعة آالف وخمســمائة ريــال قيمــة رســوم عاملــة منزليــة‬\n‫أحضرهــا عــن طريــق مكتــب املدعــى عليــه لالســتقدام وبعــد قدومهــا‬\n‫رفضــت العمــل فقــام بإعادتهــا للمكتــب خــال فتــرة التجربــة وتســلمها‬\n‫املدعــى عليــه ووعــده بإعــادة املبلــغ الــذي دفعــه إال أنــه قــد ماطــل ولــم يقم‬\n‫بإنهــاء إجــراءات اخلادمــة حيــث إنهــا مــا زالــت يف كفالــة املدعــي وطلــب‬\n‫إلــزام املدعــى عليــه بإعــادة املبلــغ الــذي ســلمه لــه وقــدره ســبعة آالف‬\n‫وخمســمائة ريــال ‪ - 7500‬مت ســؤال املدعــي البينــة علــى دعــواه فأشــار‬\n‫إلــى أن املدعــى عليــه قــد حضــر لــدى جلنــة الصلــح باحملكمــة واصطلحــا‬\n‫أن يدفــع املدعــى عليــه للمدعــي خمســة آالف ريــال يف ‪1433/5/29‬ه ـ‬\n‫ويتنــازل املدعــي عــن ألفــن وخمســمائة ريال إال أن املدعــى عليه لم يلتزم‬\n‫بالصلــح ـ جــرى االطــاع علــى األوراق فوجــد بهــا خطــاب جلنــة الصلــح‬\n‫املتضمــن أنــه حضــر املدعــي واملدعــى عليــه واصطلحــا أن يدفــع املدعــى‬\n‫عليــه للمدعــي مبلغـ ًا وقــدره خمســة آالف ريــال يف ‪1435/5/29‬ه ـ ويف‬\n‫حــال تأخــره عــن دفــع املبلــغ يف املوعــد احملــدد فإنــه يكون ملزم ًا بســداد‬\n‫كامــل املدعــى بــه وقــدره ســبعة آالف وخمســمائة ريــال ويكــون هــذا‬\n‫الصلــح منهــي للنــزاع بــن الطرفــن ‪ -‬حلــف املدعــي اليمــن ‪ -‬بنــاء علــى‬\n‫مــا ورد يف خطــاب جلنــة الصلــح وحللــف املدعــي اليمــن ‪ -‬وألن املدعــى‬\n\n                                                                                          ‫‪222‬‬\n\f      ‫عليــه لــم يــف مبــا وعــد بــه وألن الرســول صلــى اهلل عليــه وســلم قضــى‬\n      ‫للــذي وفــى علــى مــن لــم يــف ‪ -‬وبنــاء علــى املــواد (‪ )55‬و (‪ )103‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ‪ -‬صــدر احلكــم بــأن يدفــع املدعــى عليــه للمدعــي‬\n      ‫املبلــغ وقــدره ســبعة آالف وخمســمائة ريــال ‪ -‬مت بعــث صــورة مــن احلكــم‬\n      ‫للمدعــى عليــه لتبليغــه وإفهامــه بتعليمــات االســتئناف ‪ -‬صــدق احلكــم‬\n                                                        ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫ـاء علــى املعاملــة احملالــة‬\n                                 ‫أنــا ‪........‬القاضــي باحملكمــة اجلزئيــة بجــدة بنـ ً‬\n      ‫لنــا مــن فضيلــة رئيــس هــذه احملكمــة املســاعد برقــم ‪33357873‬‬\n      ‫يف ‪1433/2/22‬ه ـ واملتعلقــة بدعــوى ‪........‬ضــد ‪........‬ومبوجبهــا ففــي‬\n      ‫هــذا اليــوم االثنــن املوافــق ‪1434/2/18‬ه ـ الســاعة التاســعة صباحــا‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي ‪........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪........‬ولــم يحضــر املدعــى عليــه يف هــذه اجللســة‬\n      ‫أصالــة وال وكالــة رغــم طلبــه عــدة مــرات مبوجــب اإلبــاغ رقــم ‪........‬يف‬\n      ‫‪1433/5/12‬ه ـ و اإلبــاغ رقــم ‪........‬يف ‪1433/7/2‬ه ـ و ورغــم حضــوره‬\n      ‫جللســة جلنــة الصلــح بهــذه احملكمة بتاريخ االثنــن ‪1433/5/17‬هـ وبناء‬\n      ‫علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n      ‫التنفيذيــة فقــد قــررت ســماع الدعــوى وأذنــت للمدعــي بتحريــر دعــواه‬\n      ‫فادعــى علــى خصمــه الغائــب عــن املجلــس الشــرعي قائــا إن لــي يف ذمــة‬\n      ‫املدعــى عليــه مبلغــا وقــدره ســبعة آالف وخمســمائة ريــال قيمــة رســوم‬\n      ‫عاملــة منزليــة احضرهــا املدعــى عليــه عــن طريــق مكتبــه مكتــب‬\n\n‫‪223‬‬\n\f‫‪........‬لالســتقدام إال أنهــا رفضــت العمــل لــدي وقمــت بإعادتهــا للمكتــب‬\n‫خــال فتــرة التجربــة وتســلمها املذكــور ووعدنــي بإعــادة املبلــغ إال انــه‬\n‫بعــد ذلــك ماطلنــي ولــم يقــم بإنهــاء إجــراءات خروج الشــغالة حيــث إنها ال‬\n‫تــزال علــى كفالتــي ولــم يعيــد لــي املبلــغ لــذا أطلــب إلزامــه بســداد املبلــغ‬\n‫وقــدره ســبعة آالف وخمســمائة ريــال أطالبــه بذلــك فجــرى ســؤاله هــل‬\n‫لديــك بينــة علــى دعــواك أجــاب قائــا نعــم لقــد حضــر املدعــى عليــه لــدى‬\n‫جلنــة الصلــح بهــذه احملكمــة بتاريــخ االثنــن ‪1433/5/17‬ه ـ واصطلحنا‬\n‫علــى أن يدفــع لــي مبلــغ خمســة آالف ريــال يف تاريــخ ‪1433/5/29‬ه ـ‬\n‫وأتنــازل لــه عــن ألفــن وخمســمائة ريــال إال انــه لــم يلتــزم بذلــك الصلــح‬\n‫فجــرى االطــاع علــى األوراق فوجــد بهــا خطــاب جلنــة الصلــح بهــذه‬\n‫احملكمــة برقــم ‪ 33357873‬يف ‪ 1434/5/17‬ه ـ واملتضمــن انــه حضــر‬\n‫لديهــم املدعــي واملدعــى عليــه واصطلحــا علــى ان يدفــع املدعــى عليــه‬\n‫للمدعــي مبلــغ خمســة االف ريــال يف تاريــخ ‪1433/5/29‬ه ـ ويف حــال‬\n‫تأخــره عــن دفــع املبلــغ يف املوعــد احملــدد فانــه يكــون ملزمــا بســداد‬\n‫كامــل املبلــغ املدعــى بــه وقــدره ســبعة االف وخمســمائة ريــال ويكــون‬\n‫هــذا الصلــح منهيــا جلميــع النزاعــات القائمــة بــن الطرفــن انتهــى فجــرى‬\n‫ســؤال املدعــي هــل حتلــف اليمــن علــى أن لــك يف ذمــة املدعــى عليه مبلغا‬\n‫وقــدره ســبعة آالف وخمســمائة ريــال فأجــاب قائــا نعــم أحلــف فجــرى‬\n‫وعظــه وتخويفــه مــن مغبــة اليمــن الكاذبــة وأنهــا تغمــس صاحبهــا يف‬\n‫نــار جهنــم فحلــف بــاهلل قائــا واهلل العظيــم الــذي ال الــه إال هــو عالــم‬\n‫الغيــب والشــهادة احلــي القيــوم بــأن لــي يف ذمــة املدعــى عليــه ‪ ........‬مبلغــا‬\n‫وقــدره ســبعة آالف وخمســمائة ريــال حالــة ولــم يســلمني منهــا شــيئا‬\n‫واهلل العظيــم انتهــى وعليــه فبنــاء علــى دعــوى املدعــي املرصــودة أعــاه‬\n\n\n                                                                                          ‫‪224‬‬\n\f      ‫وبنــاء علــى مــا ورد يف محضــر جلنــة الصلــح املشــار لــه بعاليــه وبنــاء علــى‬\n      ‫اليمــن التــي حلفهــا املدعــي باســتحقاقه مبلــغ ســبعة االف وخمســمائة‬\n      ‫ريــال يف ذمــة املدعــى عليــه وملــا رواه أبــو موســى األشــعري رضــي اهلل‬\n      ‫عنــه قــال ( كان اخلصمــان إذا اختصمــا إلــى رســول اهلل صلــى اهلل‬\n      ‫عليــه وســلم فاتعــد املوعــد فوفــى احدهمــا ولــم يــوف اآلخــر قضــى للــذي‬\n      ‫وفــى ) أخرجــه الطبرانــي يف األوســط وغيــره وألنــه لــو لــم يحكــم‬\n      ‫عليــه جلعــل االســتتار ســبيال لتضييــع احلقــوق كمــا ذكــر يف الشــرح‬\n      ‫الكبيــر‪ 508/28‬وغيــره وبنــاء علــى املــادة اخلامســة واخلمســن واملــادة‬\n      ‫الثالثــة بعــد املائــة مــن نظــام املرافعــات الشــرعية ولوائحهمــا التنفيذيــة‬\n      ‫فقــد حكمــت علــى املدعــى عليــه ‪ ........‬حضوريــا بــأن يدفــع للمدعــي‬\n      ‫‪ ........‬مبلغــا وقــدره ســبعة آالف وخمســمائة ريــال وبــه حكمــت وأمــرت‬\n      ‫بتنظيــم هــذا الصــك مبوجبــه وبعــث صــورة منــه للمدعــى عليــه لتبليغــه‬\n      ‫وإفهامــه بأنــه إذا لــم يتقــدم باعتراضــه خــال املــدة املقــررة نظامــا‬\n      ‫فســوف يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة واهلل‬\n      ‫املوفــق وصلــى اهلل علــى ســيدنا محمــد وعلــى الــه وصحبــه وســلم حــرر‬\n                                                                     ‫يف ‪1434/2/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد وحيــث جــرى بعــث صــورة مــن احلكــم لتبليــغ‬\n      ‫املدعــى عليــه وردتنــا افــادة مديــر شــرطة محافظــة جــدة برقــم ‪........‬‬\n      ‫يف ‪1434/5/28‬ه ـ متضمنــة انــه لــم يتــم االســتدالل علــى املدعــى عليــه‬\n      ‫وجــرى االتصــال علــى االرقــام التــي زودهــم بهــا املدعــي ولــم يتــم الــرد‬\n      ‫‪.‬انتهــى ‪.‬وعليــه قــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم اســتنادا للمــادة اخلامســة واخلمســن مــن نظــام املرافعات‬\n      ‫الشــرعية والئحتهــا التنفيذيــة واهلل املوفــق وصلــى اهلل علــى ســيدنا‬\n\n\n‫‪225‬‬\n\f              ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/6/10‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪........‬القاضــي باحملكمــة اجلزائيــة مبحافظــة جــدة برقــم‬\n‫‪ 34168504‬وتاريــخ ‪1434/3/22‬ه ـ املتضمــن دعــوى ‪........‬ضــد ‪........‬‬\n‫واحملكــوم فيــه مبــادون باطنــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم والغائــب علــى حجتــه إذا حضــر‬\n‫واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                                 ‫‪،.،.،.،.،‬‬\n\n\n\n\n                                                                                ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":221,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a79db35299f96c525493704adc3c30279593d5295a1a47df54f5c858fa4b532d","normalized_text_hash":"7a4c24a5b47e102b20762460b2ff8ca9a3d519a796d780556c6e3a6477a7238b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p221-34168504"},{"id":"ad1db665-b09b-5344-b77b-1a3cfa318d42","document_type":"judgment","category":"judicial","subcategory":"general","title":"اتعاب -اعمال تعقيب -مطالبة بإعادة جزء من األجرة لعدم إجناز األجير للعمل -وجوب الوفاء بالعقود -االصل يف العقود و الشروط احلل -احلكم برد دعوى املدعى والزام املدعي بدفع اتعاب احملاماة ملوكل املدعى عليه .","document_number":"33204853","case_number":"19263","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/21","year":"1434","subject":"اتعاب -اعمال تعقيب -مطالبة بإعادة جزء من األجرة لعدم إجناز األجير للعمل -وجوب الوفاء بالعقود -االصل يف العقود و الشروط احلل -احلكم برد دعوى املدعى والزام املدعي بدفع اتعاب احملاماة ملوكل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33204853 :‬تاريخه‪1433/4/21 :‬هـ‬\n                            ‫رقم الدعوى‪19263 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3434009‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n      ‫اتعــاب‪ -‬اعمــال تعقيــب‪ -‬مطالبــة بإعــادة جــزء مــن األجــرة لعــدم إجنــاز‬\n      ‫األجيــر للعمــل‪ -‬وجــوب الوفــاء بالعقــود‪ -‬االصــل يف العقــود و الشــروط‬\n      ‫احلــل ‪ -‬احلكــم بــرد دعــوى املدعــى والــزام املدعــي بدفــع اتعــاب احملامــاة‬\n                                                               ‫ملــوكل املدعــى عليــه ‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قول اهلل تعالى‪(( :‬يا أيها الذين آمنوا أوفوا بالعقود))‪.‬‬\n                                               ‫‪ -2‬األصل يف العقود الصحة‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن موكلــه اتفــق مــع املدعــى عليــه علــى أن يقــوم‬\n      ‫الثانــي بأعمــال التعقيــب واملتابعــة يف إنهــاء موضوعــه املتعلــق بتالعــب‬\n      ‫أحــد املصــارف بحســاباته كمــا اتفــق معــه علــى أن يدفــع لــه املبلــغ‬\n      ‫املذكــور يف الدعــوى بشــيك ليبقــى ضمان ـ ًا لديــه بشــرط أال يصرفــه‬\n      ‫ا إال أن املدعــى عليــه قــام بصــرف الشــيك‬    ‫حتــى ينهــي املوضــوع كام ـ ً‬\n      ‫دون إنهــاء مــا اتفــق عليــه‪ ،‬لــذا طلــب إلزامــه بإعــادة مــا اســتلمه مــن‬\n      ‫موكلــه‪ -‬أقــر وكيــل املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع بــأن‬\n      ‫االتفاقيــة التــي بينهمــا تنــص علــى حــق موكلــه يف صــرف الشــيك كمــا‬\n      ‫دفــع بــأن املدعــي هــو مــن قــام بفســخ وكالــة موكلــه دون أن ُيبلغــه‬\n\n‫‪227‬‬\n\f‫بالفســخ أو ســببه ‪ -‬العقــد املبــرم بــن املتداعيــن يتضمــن أن الشــيك‬\n‫محــل الدعــوى حــق مــن حقــوق الطــرف الثانــي لــه احلــق يف صرفــه دون‬\n‫الرجــوع للطــرف األول كمــا يتضمــن أن الطــرف الثانــي يســتحق جميــع‬\n‫حقوقــه عنــد فســخ الطــرف األول لوكالتــه‪ -‬قضــت احملكمــة بــرد‬\n‫دعــوى املدعــي لعــدم اســتحقاقه ملــا يدعيــه ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n‫وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                       ‫احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ ....‬وتاريــخ ‪ 1431/04/18‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 3166610‬وتاريــخ ‪ 1431/04/14‬ه ـ ففــي يــوم االحــد املوافــق‬\n‫‪ 1432/03/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 44‬وفيهــا حضــر ‪........‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ .....‬بالوكالــة عــن ‪ ........‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جده برقم‬\n‫‪ 12261‬يف ‪1431/2/9‬ه ـ جلــد ‪ 9269‬وادعــى علــى احلاضــر معــه ‪........‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ ........‬بالوكالــة عــن ‪ ........‬مبوجب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم‬\n‫ا يف دعــواه عليــه إن موكلــي‬   ‫‪ 18987‬يف ‪1432/3/9‬ه ـ جلــد ‪ 4640‬قائـ ً‬\n‫اتفــق مــع مــوكل املدعــى عليــه علــى التعقيــب ومتابعــة يف موضوعــه‬\n‫املتعلــق بتالعــب بنــك ‪ ...‬بحســاباته اجلاريــة واالســتثمارية وبــذل قصــارى‬\n‫جهــده إلنهــاء املوضــوع كــون موكلــي رجــل أعمــال وحصــل هنــاك‬\n\n                                                                                   ‫‪228‬‬\n\f      ‫تالعــب مــن بنــك ‪ ........‬ووكل املدعــى عليــه أصالــة بإنهــاء مــا يتعلــق بهذا‬\n      ‫األمــر وقــد أتفــق موكلــي مــع مــوكل املدعــى عليــه علــى أن يدفــع لــه‬\n      ‫موكلــي مبلــغ مليونــن شــرط أن ينهــي مــوكل املدعــى عليــه املوضــوع‬\n      ‫ا وكذلــك بقــاء هــذا املبلــغ ضمانـ ًا حلــن اســترجاع أموالــه التــي‬   ‫كامـ ً‬\n      ‫مت االســتيالء عليهــا مــن حســابه يف أحــد البنــوك إال أن موكلــي تفاجــأ‬\n      ‫بقيــام مــوكل املدعــى عليــه بصــرف الشــيك دون إنهــاء مــا اتفــق عليــه‬\n      ‫لــذا أطلــب احلكــم علــى مــوكل املدعــى عليــه بإعــادة مــا اســتلمه مــن‬\n      ‫موكلــي مبلغ ـ ًا وقــدره مليونــا ريــال وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫وكالــة أجــاب بأنــي أطلــب إمهالــي للرجــوع إلــى موكلــي واإلفــادة يف‬\n      ‫اجللســة القادمــة لــذا رفعــت اجللســة ويف يــوم االثنــن ‪1432/06/06‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر الطرفــان وســألت املدعــى عليــه عــن‬\n      ‫جوابــه علــى الدعــوى فقــال إن جوابــي هــو مــا ذكــره املدعــي مــن طلــب‬\n      ‫موكلــي لــه يف التعقيــب عنــه فهــذا صحيــح حيــث إن املدعــي أصالــة‬\n      ‫طلــب مــن موكلــي أن ميثلــه يف التعقيــب واملرافعــة يف معاملتــه لــدى جلنــة‬\n      ‫املنازعــات املصرفيــة ضــد بنــك ‪ ...‬فطلــب منــه موكلــي قبــل أن يتفــق معه‬\n      ‫أن يكتــب لــه وكالــة لكــي يســتطيع مبوجبهــا معرفــة حقيقــة الدعــوى‬\n      ‫‪ .‬وبالفعــل كتــب لــه وكالــة برقــم (‪ ).....‬وتاريــخ ‪1430/3/21‬ه ـ مرفــق‬\n      ‫رقــم (‪ )1‬وعلــى ضــوء هــذه الوكالــة قــام موكلــي مبراجعــة اجلهــات‬\n      ‫املختصــة ملعرفــة حقيقــة هــذه الدعــوى ومالبســاتها وبقــي موكلــي‬\n      ‫مــدة وهــو يســأل عــن قضيــة املدعــي وبعــد أن عــرف قضيتــه أبلغــه أنــه‬\n      ‫ال مانــع لديــه مــن الســعي يف الدعــوى وحرصـ ًا مــن املدعــي قــام وكتــب‬\n      ‫لــه شــيك ًا مببلــغ مليونــي ريــال (‪ 2000.000‬ريــال) وأرســله ملوكلــي‬\n      ‫وطلــب مــن موكلــي عــدم صرفــه فكتــب لــه موكلــي إقــرار ًا موقع ـ ًا‬\n\n\n‫‪229‬‬\n\f‫منــه فقــط مؤرخ ـ ًا يف ‪1430/4/12‬ه ـ أنظــر مرفــق رقــم (‪ )2‬واشــترط‬\n‫عليــه موكلــي أنــه ال بــد مــن كتابــة اتفاقيــة حتــدد حقــوق كل منهمــا‬\n‫كمــا هــو متعــارف عليــه فوافــق املدعــي ثــم حضــر بعــد ثالثــة أيــام‬\n‫مــن إقــرار موكلــي املــؤرخ يف ‪1430/4/12‬ه ـ وكتبــا بينهمــا اتفاقيــة‬\n‫مؤرخــه يف ‪1430/4/15‬ه ـ املوافــق ‪2009/4/11‬م مرفــق (‪ )3‬موقعــة‬\n‫مــن املدعــي أصالــة بقلمــه وإبهامــه وكذلــك موكلــي ومــن ثالثــة شــهود‪.‬‬\n‫وعلــى ضــوء هــذه االتفاقيــة قــام موكلــي بصــرف الشــيك املمثــل للمبلــغ‬\n‫املدعــى بــه ألنــه جــاء يف هــذه االتفاقيــة بنــد (‪ )6‬أن ملوكلــي حــق صــرف‬\n‫الشــيك‪ .‬وموكلــي منــذ أن وقــع اتفاقــه مــع املدعــي بــل منــذ أن وكلــه لــم‬\n‫يألــو جهــد ًا يف كشــف احلقيقــة للمســئولني ومــن ذلــك علــى ســيبل املثــال‬\n‫ال احلصــر خطــاب موكلــي املوجــه لســعادة األمــن العــام للجنــة تســوية‬\n‫املنازعــات املصرفيــة املــؤرخ يف ‪1430/4/9‬ه ـ املوافــق ‪2009/4/5‬م‬\n‫مرفــق (‪)4‬ومنهــا اخلطــاب املــؤرخ يف ‪1430/4/24‬ه ـ مرفــق (‪ )5‬ومنهــا‬\n‫اخلطاب املؤرخ يف ‪1430/5/3‬هـ املوافق ‪2009/4/28‬م مرفق (‪ )6‬ومنها‬\n‫اخلطــاب املــؤرخ يف ‪1430/5/22‬ه ـ املوافــق ‪2009/5/17‬م مرفــق(‪)8-7‬‬\n‫وضـ َـح للمســئولني‬ ‫ومــن يتأمــل هــذا اخلطــاب يظهــر لــه أن موكلــي قــد ّ‬\n‫حقيقــة دعــوى موكلــه وج ـ ـ ـ ــاء يف الفقـ ـ ــرة (‪ )9‬مــن هــذا اخلط ـ ـ ــاب مــا‬\n‫نصــه ( ليصبــح إجمـ ـ ــالي مط ـ ـ ــالبتي للبنــك خمســة ماليــن وثالثمائــة‬\n‫واثنــان وثمانــون ألفـ ًا وخمســمائة وأربعــة ريــاالت وســبعة وعشــرون هللــه‬\n‫((‪ 5.382.504.27‬ريــال‪ .‬وهــذا يعتبــر مهــارة مــن موكلــي حيــث عـ ّـدل‬\n‫باســتدعائه هــذا الدعــوى التــي ســبق أن رفعــت مــن وكيــل املدعــى‬\n‫الــذي قبلــه أنظــر مرفــق (‪ )10-9‬حيــث جــاء يف الفقــرة (‪ )3‬منــه أن املبلــغ‬\n‫الــذي يطالــب بــه املدعــي ثالثــة ماليــن وثالثمائــة وثمانــون الفـ ًا وســتمائة‬\n\n\n                                                                                         ‫‪230‬‬\n\f      ‫وثالثــة وعشــرون ريــا ًال وســبعة وعشــرون هللــه (‪ .)3.380.623.27‬ألنــه‬\n      ‫اكتشــف مــا لــم يكشــفه غيــره بعــد اطالعــه علــى األوراق التــي تخــص‬\n      ‫املدعــي‪ .‬وقــد حضــر موكلــي اجللســة املنعقــدة بتاريــخ ‪1430/10/17‬ه ـ‬\n      ‫يف جلنــة تســوية املنازعــات حســبما يظهــر مــن خطــاب األمــن العــام‬\n      ‫ـاء علــى طلبــه رقــم (‪/578‬ل ت) وتاريــخ‬          ‫للجنــة املوجــه ملوكلــي بنـ ً‬\n      ‫‪1432/3/25‬ه ـ مرفــق (‪ )12-11‬وممــا يــدل علــى اهتمــام موكلــي‬\n      ‫أنــه أجــاب إلــى استفســار جلنــة تســوية املنازعــات التــي ُطلبــت منــه يف‬\n      ‫اجللســة املؤرخــة يف ‪1430/10/17‬ه ـ حيــث أجابهــم بخطابــه املــؤرخ يف‬\n      ‫‪1430/10/21‬ه ـ املوافــق ‪2009/10/10‬م مرفــق (‪ )14-13‬وممــا يــدل‬\n      ‫علــى اهتمــام موكلــي أنــه ُيطلــع موكلــه ( املدعــي) علــى كل مــا يقــوم‬\n      ‫بــه أو مــا يحتــاج إلــى استفســار حيــث كتــب لــه خطاب ـ ًا بعــد جلســة‬\n      ‫‪1430/10/17‬ه ـ أنظــر مرفــق (‪ .)15‬وممــا يــدل علــى رضــا املدعــي‬\n      ‫أصالــة عــن عمــل موكلــي مــا قالــه ابــن املدعــي (‪ )........‬حيــث قــال مــا‬\n      ‫نصــه «وقــد رضينــا رض ـ ًا تــام علــى مــا قــام بــه الوكيــل الشــرعي‪........‬‬\n      ‫مــن عمــل وجهــد يف متابعــة قضيــة املدعــو ‪ ........‬وقــد أعطينــاه الوقــت‬\n      ‫الــكايف حتــى تنتهــي القضيــة»‪ .‬أنظــر مرفــق (‪ )16‬ســطر (‪.)10-9‬‬\n      ‫وممــا يــدل علــى مواصلــة موكلــي لعملــه أنــه كتــب مذكــرة للجنــة‬\n      ‫تســوية املنازعــات املصرفيــة مؤرخــة يف ‪1430/12/26‬ه ـ املوافــق‬\n      ‫‪2009/12/13‬م أنظــر مرفــق (‪ .)17‬وعندمــا حضــر موكلــي للجلســة‬\n      ‫املؤرخــة يف ‪1431/1/2‬ه ـ تفاجــأ بأنــه جــرى فســخ وكالتــه بــدون أن‬\n      ‫ُيبلغــه املدعــي أو يتفاهــم معــه أو ُيبــن لــه وجــه القصــور أو الســبب‬\n      ‫احلامــل لــه علــى فســخ الوكالــة‪ .‬واملدعــي هــداه اهلل عمــل هــذا العمــل‬\n      ‫مــع محامــن ســابقني ملوكلــي حيــث فســخ وكاالتهــم أنظــر مرفــق‬\n\n\n‫‪231‬‬\n\f‫(‪ .)19-18‬أمــا مــا طلبــه مــوكل املدعــى مــن احلكــم علــى موكلــي‬\n‫بإعــادة مــا اســتلمه وقــدره مليونــا ريــال (‪ 2000.000‬ريــال) فموكلــي‬\n‫ال يوافــق علــى ذلــك ألنــه اســتحق هــذا املبلــغ منــذ أن وقــع االتفاقيــة مــع‬\n‫املدعــي املؤرخــة يف ‪1430/4/15‬ه ـ ومــن يطلــع علــى هــذه االتفاقيــة‬\n‫يظهــر لــه جلي ـ ًا أنهــا بعــد إقــرار موكلــي بعــدم صــرف الشــيك املــؤرخ‬\n‫يف ‪1430/4/12‬ه ـ ألن االتفــاق املوقــع عليــه مــن الطرفــن هــو األســاس‬\n‫يف التعامــل بينهمــا وهــو املتأخــر تاريخ ـ ًا ومــن املعلــوم أن املتأخــر ناســخ‬\n‫ملــا قبلــه الســيما أنــه جــاء يف البنــد (‪ )6‬منــه مــا نصــه « ويعتبــر اإلقــرار‬\n‫الــذي صــدر مــن الطــرف الثانــي يف ‪1430/4/12‬ه ـ ملغــي وال ميثــل أي‬\n‫شــيء بــن الطرفــن»‪ .‬مــع اإلحاطــة ان املدعــى وكالــة قــال يف دعــواه أن‬\n‫موكلــي رجــل أعمــال ومــن هــذه حالــه فهــو يعــرف معنــى االتفــاق ومــا‬\n‫يــدل عليــه وهــو ليــس بجاهــل بــل رجــل أعمــال وســبق أن فســخ وكالتــن‬\n‫لوكيلــن قبــل أن يكتــب الوكالــة ملوكلــي ومــن يعمــل هــذا ال بــد أنــه‬\n‫أخــذ حــذره وحيطتــه مــع مــن ســيتفق معــه وهــذا مــا عملــه مــع موكلــي‬\n‫حيــث لــم يكتفــي بالتوقيــع بــل طلــب التوقيــع بالقلــم واإلبهــام‪ .‬ومــن هــذا‬\n‫كلــه يظهــر أن موكلــي قــام بعملــه علــى الوجــه املطلــوب ولكــن ملــا‬\n‫ظهــر للمدعــي أن موكلــي ســار يف القضيــة ســير ًا صحيحـ ًا وتكشــفت‬\n‫حقائقهــا قــام بفســخ وكالتــه لكــي ال يطالبــه بنســبة ال ـ ـ ـ (‪) %20‬‬\n‫يف املئــة املتفــق عليهــا يف العقــد املوقــع عليــه بينهمــا مرفــق (‪ )3‬فقــرة‬\n‫(‪ )4‬وموكلــي يحتفــظ بحقــه بإقامــة الدعــوى بهــذه النســبة ‪ .‬أطلــب‬\n‫صــرف النظــر عــن دعــوى املدعــي وتكليــف املدعــي بأجــرة احملامــاة‬\n‫التــي خســرها موكلــي وقدرهــا مئتــان ألــف ريــال (‪ 200.000‬ريــال)‬\n‫هــذه إجابتــي وبعــرض ذلــك علــى املدعــي وكالــة قــال أطلــب تزويــدي‬\n\n\n                                                                                         ‫‪232‬‬\n\f      ‫نســخة مــن رد املدعــى عليــه حتــى امتكــن مــن الــرد عليــه يف اجللســة‬\n      ‫القادمــة وجــرى تزويــده بنســخة مــن رد املدعــى عليــه وكالــة ومرفقاتــه‬\n      ‫ورفعــت اجللســة ثــم لــدي أنــا ‪ ........‬املكلــف بعمــل املكتــب رقــم (‪ )3‬لــدى‬\n      ‫فضيلــة الشــيخ ‪ ........‬القاضــي يف احملكمــة العامــة بالريــاض مبوجــب‬\n      ‫خطــاب فضيلــة رئيــس احملكمــة رقــم ‪ 32/823650‬يف ‪1432/7/4‬ه ـ‬\n      ‫ففــي يــوم االربعــاء ‪1432/7/6‬ه ـ افتتحــت اجللســة الســاعة ‪ 9:30‬وفيهــا‬\n      ‫حضــر الطرفــان وبقــراءة مــا مت ضبطــه ســابقا صادقــا عليــه وبســؤال‬\n      ‫املدعــي وكالــة عــن جوابــه عــن جــواب املدعــى عليــه وكالــة قــال جوابــه‬\n      ‫لــم يالقــي الدعــوى هكــذا قــال وعلــى هــذا رفعــت اجللســة للتأمــل ثــم‬\n      ‫لــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة بالريــاض ويف يــوم الســبت‬\n      ‫املوافــق ‪ 1432/11/3‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 12‬وفيهــا حضــر‬\n      ‫املدعــى عليــه وكالــة ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬ولــم‬\n      ‫يحضــر املدعــي وال مــن ينــوب عنــه بوكالــة شــرعيه وفيهــا قــدم املدعــي‬\n      ‫عليــه وكالــه ردا مــن ورقتــن ضمــت بأصــل املعاملــة ونصهــا ومضمونهــا‬\n      ‫قائــا يف رده علــى إجابــة املدعــي يف اجللســة املاضيــة مــن أن إجابتــي‬\n      ‫غيــر مالقيــة لدعــواه ‪ .‬أجيــب عــن ذلــك بــأن إجابتــي مالقيــة وبصــورة‬\n      ‫وافيــة لدعــواه فهــو ذكــر يف دعــواه مــا نصــه (ثاني ـاً) إلــزام املدعــى‬\n      ‫عليــه ‪ ........‬بالتضامــن مــع أعوانــه املذكوريــن بــرد مــا اســتولوا عليــه‬\n      ‫مــن مبالــغ مــن موكلــي وقدرهــا مليونــا ريــال (‪ 2.000.000‬ريــال) دون‬\n      ‫وجــه حــق واحلكــم بذلــك) وموكلــي هــو الــذي اســتلم املبلــغ مــن املدعــي‬\n      ‫أصالــة ووضحــت يف إجابتــي بصــورة مفصلــه ســبب اســتالم موكلــي‬\n      ‫لهــذا املبلــغ ومــن هــذا يتضــح أن إجابتــي مالقيــة للدعــوى‪ .‬ثــم حضرنــا‬\n      ‫اجللســة املاضيــة بتاريــخ ‪1432/8/2‬ه ـ ولــم يقــدم املدعــي شــيئاً‪ .‬وما عدم‬\n\n\n‫‪233‬‬\n\f‫حضــور املدعــي جللســة هــذا اليــوم إ ّال لعلمــه بعــدم أحقيــة موكلــه لهــذه‬\n‫الدعــوى‪ .‬ولــو كان لديــه شــيء لقدمــه إذ ليــس مــن املعقــول أن يتــرك‬\n‫دعــواه يف هــذا املبلــغ الكبيــر لــو كان لديــه بينــة‪ .‬صاحــب الفضيلــة‬\n‫إن املدعــي ذكــر ان مســتنده هــو االتفــاق بــن موكلــه وموكلــي وأن‬\n‫موكلــه قــام بتوقيــع عــدة مســتندات كمــا جــاء يف صفحــة الدعــوى‬\n‫ا علــى دعــواه يف مذكرتــي املعطــى‬       ‫أخــر ســطر(‪ )3‬وقــد أجبــت تفصيـ ً‬\n                                                ‫للمدعــي وكالــة صــورة منهــا ‪.‬‬\n‫وموكلــي لــم يأتــي بجديــد يف رده علــى دعــوى املدعــي وإمنــا قــام‬\n‫بتوضيــح االتفــاق الــذي وقعــه مــع املدعــي أصالــة وكــذا قــام بتوضيــح‬\n‫العمــل الــذي قــام بــه ألن املدعــي قــال يف دعــواه (أنــه اســتولى عليــه‬\n‫دون وجــه حــق) الســطر األخيــر مــن صحيفــة الدعــوى‪ .‬ومــن هــذا كلــه‬\n‫يتضــح أن املدعــي قــدم جميــع مــا لديــه مــن مســتندات وألن املــادة ( ‪)54‬‬\n‫مــن نظــام املرافعــات الشــرعية نصــت علــى انــه ( إذا حضــر املدعــى عليــه‬\n‫يف اجللســة التــي غــاب عنهــا املدعــي فلــه أن يطلــب مــن احملكمــة عــدم‬\n‫شــطب الدعــوى واحلكــم يف موضوعهــا إذا كانــت صاحلــة للحكــم‬\n‫فيهــا) وهــذه القضيــة صاحلــة للحكــم فيهــا‪ .‬ألنــه لــم يبــق للمدعــي مــا‬\n‫يقدمــه إذ لــو كان لديــه شــيء لقدمــه يف هــذه اجللســة‪ .‬وكــذا املــادة‬\n‫( ‪ 84‬و ‪ )85‬مــن نظــام املرافعــات الشــرعية فيهــا إذا تهيــأت الدعــوى‬\n‫للحكــم فــا تنقطــع اخلصومــة وعلــى احملكمــة احلكــم فيهــا وتعــد‬\n‫الدعــوى مهيــأة للحكــم إذا أبــدى اخلصــوم أقوالهــم وطلباتهــم اخلتاميــة‬\n‫يف جلســة املرافعــة‪ .‬لــذا أطلــب احلكــم يف القضيــة وصــرف النظــر يف‬\n‫الدعــوى هــذه إجابتــي عنــد ذلــك رفعــت اجللســة للتأمــل يف يــوم الثالثــاء‬\n‫املوافــق‪ 1433/04/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 12‬وفيهــا‬\n\n\n                                                                                    ‫‪234‬‬\n\f      ‫حضــر املدعــي وكالــة ‪ ........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫بالوكالــة عــن ‪........‬واملدونــة وكالتــه ســابق ًا كمــا حضــر حلضــوره‬\n      ‫املدعــى عليــه وكالــة ‪........‬مبوجــب الســجل املدنــي رقــم ‪........‬بالوكالــة‬\n      ‫عــن ‪........‬واملــدون وكالتــه أعــاه وقــدم املدعــي وكالــة ردا مــن ورقــة‬\n      ‫واحــدة جــرى ضمهــا باملعاملــة ونصهــا افيــد فضيلتكــم بــأن مــا ذكــره‬\n      ‫املدعــى عليــه غيــر صحيــح كونــه اســتدرج موكلــي للريــاض وغــرر‬\n      ‫بــه للتوقيــع علــى االتفاقيــة بينهمــا مخالفــة ألصــل العقــد والــذي يتعهــد‬\n      ‫فيــه بعــدم صــرف مبلــغ شــيك وان يبقــى لديــه ضمــان حلــن اجنــاز مــا‬\n      ‫اوكل اليــه اال انــه بعــد ان احضــره للريــاض ونظــرا لكبــر ســنه حيــث‬\n      ‫يبلــغ خمســة وثمانــون عامــا دون ان يعلــم موكلــي مــا اضمــره املدعــى‬\n      ‫عليــه مــن احتيــال لتحصيــل الشــيك دون وجــه حــق وقبــل بــدء العمــل‬\n      ‫وممــا يثبــت التغريــر واالســتدراج والغــن ان مطالبــة موكلــي التــي تقــدم‬\n      ‫بهــا املدعــى عليــه امــام جلنــة تســوية املنازعــات املصرفيــة مببلــغ خمســة‬\n      ‫ماليــن ريــال فقــط فكيــف يســتحق مقــدم اتعــاب مبلــغ مليونــي ريــال‬\n      ‫واملطالبــة هــي مــا ذكــر كمــا يثبــت ذلــك ان املدعــى عليــه ادعــى بأنــه‬\n      ‫يعمــل محامــي للخصــم يف مثــل هــذه الدعــاوى علــى عكــس احلقيقــة‬\n      ‫لــذا اطلــب احلكــم علــى املدعــى عليــه بــرد مبلــغ وقــدره مليونــي ريــال‬\n      ‫ملوكلــي لعــدم اســتحقاقه لذلــك املبلــغ لقولــه جــل وعــا ( وال تأكلــوا‬\n      ‫أموالكــم بينكــم بالباطــل ) اآليــة وبعرضهــا علــى املدعــى عليــه وكالــة‬\n      ‫اجــاب ليــس لــدي زيــادة علــى مــا قدمــت واكتفــي بــه هــذه اجابتــي عنــد‬\n      ‫ذلــك قــرر املدعــي وكالــة بأنــي اكتفــي بحصــر دعــوى موكلــي ضــد‬\n      ‫املدعــى عليــه ‪ ........‬كونــه هــو مــن أجــرى االتفــاق مــع موكلــي فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة والن املدعــى عليــه وكالــة صــادق‬\n\n\n‫‪235‬‬\n\f‫علــى بعــض دعــوى املدعــي وكالــة وانكــر البعــض ونظــرا للعقــد املبــرم‬\n‫بــن املتداعيــن اصالــة وفيــه مــا نصــه توقيــع الطرفــن علــى هــذا العقــد‬\n‫يعتبــر الشــيك املوضــح يف البنــد رقــم (‪ )3‬حــق مــن حقــوق الطــرف الثانــي‬\n‫لــه احلــق يف صرفــه دون الرجــوع للطــرف األول وال يحــق للطــرف األول‬\n‫أو الحــد مــن طرفــه املطالبــة بهــذا الشــيك بــأي حــال وألن هــذا الشــرط‬\n‫نــص يف النــزاع ولقولــه تعالــى « يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود «‬\n‫وألن األصــل يف العقــود الصحــة وال يصــار إلــى ابطالهــا إال إذا اشــتملت‬\n‫علــى مــا ينــايف مقتضــى العقــود وملطالبــة املدعــى عليــه وكالــة بأجــرة‬\n‫احملامــاة مبلغ ـ ًا وقــدره مئتــا ألــف ريــال لــذا فقــد حكمــت بــرد دعــوى‬\n‫املدعــي وكالــة وعــدم اســتحقاق موكلــه ملــا يدعيــه كمــا حكمــت‬\n‫بإلــزام مــوكل املدعــي بدفــع مبلــغ وقــدره مئتــا ألف ريال ملــوكل املدعى‬\n‫عليــه أتعابـ ًا للمحامــاة وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليه‬\n‫وكالــة القناعــة بــه أمــا املدعــي وكالــة فقــرر عــدم قناعتــه باحلكــم‬\n‫وطلــب االســتئناف فأجيــب لطلبــه وجــرى تســليمه نســخة مــن احلكــم‬\n‫لتقــدمي االعتــراض عليــه خــال مــدة ثالثــن يومـ ًا وان لــم يقــدم اعتراضــه‬\n‫خاللهــا ســقط حقــه يف االســتئناف واكتســب احلكــم الصفــة القطعيــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪ 1433/04/20‬ه ـ‬\n‫احلمــد هلل وحــده ففــي يــوم األحــد املوافــق‪ 1433/11/21‬ه ـ افتتحــت‬\n‫اجللســة الــس‪ : 08‬وفيهــا حضــر املدعــى عليــه وكالــة ‪ ........‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬بالوكالــة عــن ‪ ........‬واملــدون‬\n‫ا عنــه وقــد وردت املعاملــة‬ ‫وكالتــه أعــاه ولــم يحضــر املدعــي او وكيـ ً‬\n‫مــن رئيــس محكمــة االســتئناف برقــم ‪ 331056932‬يف ‪1433/8/6‬ه ـ‬\n\n\n                                                                                      ‫‪236‬‬\n\f      ‫ومرفــق بــه القــرار رقــم ‪ 33334042‬يف ‪1433/7/9‬ه ـ واملتضمــن‬\n      ‫مالحظــة أصحــاب الفضيلــة حفظهــم اهلل مــا يلــي أو ًال ‪ :‬وجــد أن‬\n      ‫فضيلتــه لــم يطلــب العقــد املبــرم بــن الطرفــن ويطلــع عليــه ويرصــد‬\n      ‫مضمونــه بالضبــط والصــك وال بــد مــن ذلــك ثانيـ ًا ‪ :‬لــم يتحقــق فضيلتــه‬\n      ‫مــن اســتحقاق املدعــى عليــه للمبلــغ املدعــى بــه حســب االتفــاق املبــرم‬\n      ‫بينهمــا ملالحظــة مــا ذكــر وباإلجابــة علــى مالحظــة أصحــاب الفضيلــة‬\n      ‫أقــول وبــاهلل التوفيــق فقــد جــرى منــا االطــاع علــى العقــد املبــرم بــن‬\n      ‫الطرفــن وجــرى رصــد مضمونــه وهــذا نصــه « بســم اهلل الرحمــن‬\n      ‫الرحيــم التاريــخ ‪1430/4/15‬ه ـ املوافــق ‪2009/4/11‬م عقــد اتفاقيــة‬\n      ‫انــه يف يــوم الســبت ‪1430/4/15‬ه ـ املوافــق ‪2009/4/11‬م مت االتفــاق‬\n      ‫بعــون اهلل بــن كل مــن ‪ /1‬الســيد ‪........‬ويشــار إليــه فيمــا بعــد بالطــرف‬\n      ‫األول ‪ /2‬الســيد ‪ ........‬ويشــار اليــه فيمــا بعــد بالطــرف الثانــي حيــث‬\n      ‫ان للطــرف األول قضيــة تنحصــر بتالعــب بنــك ‪ ...‬يف حســاباته اجلاريــة‬\n      ‫واالســتثمارية وحيــث قبــل الطــرف الثانــي القيــام عــن الطــرف األول يف‬\n      ‫التعقيــب ومتابعــة القضيــة يف جميــع الدوائــر احلكوميــة ذات العالقــة‬\n      ‫ومنهــا وال تقتصــر علــى مؤسســة النقــد وجلانهــا واإلمــارة واحملاكــم‬\n      ‫ووزارة الداخليــة واألمــن العــام وبنــك ‪ ........‬قــد اتفقــا علــى مــا يلــي ‪/1 :‬‬\n      ‫مقدمــة هــذا العقــد جــزء ال يتجــزأ مــن هــذه االتفاقيــة ‪ /2‬يلتــزم الطــرف‬\n      ‫الثانــي ببــذل قصــارى جهــده يف متابعــة هــذه القضيــة بالتعــاون املبــذول‬\n      ‫مــن قبــل الطــرف األول ‪ /3‬اصــدار الطــرف األول شــيك مصــريف رقــم‬\n      ‫‪ 998100‬يف ‪2009/4/7‬م بقيمــة ( ‪ ) 2000,000‬ريــال علــى البنــك ‪........‬‬\n      ‫لصالــح الطــرف الثانــي مقابــل اتعابــه يف التعقيــب علــى قضيــة الطــرف‬\n      ‫املوضحــة يف مقدمــة هــذا العقــد ‪ /4‬يف حــال اســتطاع الطــرف الثانــي‬\n\n\n‫‪237‬‬\n\f‫تكليــف بنــك ‪ ........‬بدفــع غرامــة ماليــة جزائيــة ملــا قامــوا بــه مــن تالعــب‬\n‫يف حســابات الطــرف األول أو اســتطاع تكليفهــم بإعــادة أربــاح أو‬\n‫خســائر الطــرف األول يف حســاباته االســتثمارية واجلاريــة فــأن للطــرف‬\n‫الثانــي نســبة قدرهــا ( ‪ ) % 20‬مــن هــذا املبلــغ تضــاف إلــى قيمــة أتعابــه‬\n‫املوضحــة يف البنــد ( ‪ /5 ) 3‬تنتهــي مســئوليات الطــرف الثانــي أمــام‬\n‫الطــرف األول مــع اســتحقاقه جميــع حقوقــه املبينــة يف هــذا العقــد عنــد‬\n‫بــت جلنــة املنازعــات املصرفيــة أو إذا اســترجع بنــك ‪ ........‬حقــوق الطــرف‬\n‫األول مباشــرة أو عــن طريــق الصلــح أو عنــد إخــال الطــرف األول يف‬\n‫هــذه االتفاقيــة كقيامــة بفســخ وكالــة الطــرف الثانــي أو توكيــل غيره‬\n‫قبــل نهايــة هــذه القضيــة ‪ /6‬بتوقيــع الطرفــن علــى هــذا العقــد يعتبــر‬\n‫الشــيك املوضــح يف البنــد رقــم ( ‪ ) 3‬حــق مــن حقــوق الطــرف الثانــي‬\n‫لــه حــق صرفــه دون الرجــوع للطــرف األول وال يحــق للطــرف األول أو‬\n‫ألحــد مــن طرفــه املطالبــة بهــذا الشــيك بــأي حــال ويعتبــر االقــرار الــذي‬\n‫صــدر مــن الطــرف الثانــي يف ‪1430/4/12‬ه ـ ملغــى وال ميثــل أي شــيء‬\n‫بــن الطرفــن واهلل املوفــق الطــرف األول ‪........‬توقيعــه وبصمتــه الطــرف‬\n‫الثانــي ‪........‬توقيعــه وبصمتــه الشــاهد األول ‪........‬وتوقيعــه والشــاهد‬\n‫الثانــي ‪........‬وتوقيعــه والشــاهد الثالــث ‪........‬وتوقيعــه « أه ـ وباإلجابــة‬\n‫علــى املالحظــة الثانيــة أجيــب أصحــاب الفضيلــة انــه باالطــاع علــى‬\n‫العقــد املبــرم بــن الطرفــن الفقــرة اخلامســة ونصهــا « تنتهــي مســئوليات‬\n‫الطــرف الثانــي أمــام الطــرف األول مــع اســتحقاقه جميــع حقوقــه املبينــة‬\n‫يف هــذا العقــد عنــد بــت جلنــة املنازعــات املصرفيــة أو إذا اســترجع بنــك‬\n‫‪ ......‬حقــوق الطــرف األول مباشــرة أو عــن طريــق الصلــح أو عنــد إخــال‬\n‫الطــرف األول يف هــذه االتفاقيــة كقيامــة بفســخ وكالــة الطــرف‬\n\n\n                                                                                         ‫‪238‬‬\n\f      ‫الثانــي أو توكيــل غيــره قبــل نهايــة هــذه القضيــة « وألن مــوكل املدعــي‬\n      ‫قــام بفســخ الوكالــة مبــا يخالــف مقتضــى العقــد فقــد اســتحق املدعــى‬\n      ‫عليــه املبلــغ املدعــى بــه وعليــه ليــس لــدي ســوى مــا حكمــت بــه واغلقــت‬\n      ‫اجللســة يف متــام الســاعة ‪ 44:08‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بالرياض‪/‬املســاعد برقــم ‪ 2156931‬وتاريــخ‬\n      ‫‪ 1434/01/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3428802‬وتاريــخ‬\n      ‫‪ 1434/01/06‬ه ـ ففــي يــوم األربعــاء املوافــق ‪ 1434/01/14‬ه ـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 08،06‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالريــاض مرفــق بهــا قرارهــم ‪ 33477343‬يف ‪1433/12/25‬هـ املتضمن‬\n      ‫قولهــم جــواب فضيلــة القاضــي علــى املالحظــة الثانيــة من القرار الســابق‬\n      ‫ال يكفــي ‪ ،‬الن العقــد املوقــع بــن الطرفــن ال يتجــزأ ثانيــا ‪ -:‬لم يذكر‬\n      ‫فضيلتــه مســتنده علــى إلــزام املدعــي بدفــع مائتــي الــف ريــال للمدعــى‬\n      ‫عليــه أجــرة اتعــاب احملامــاة ‪ .‬وعليــه أجيــب اصحــاب الفضيلــة مشــايخنا‬\n      ‫الفضــاء أجيــب عــن امللحوظــة األولــى أنــه ال يســلم يف كل حــال عــدم‬\n      ‫جتزئــة العقــود فمتــى حصــل نقــص الحــد شــروط العقــد نقــص كلــه‬\n      ‫الن نقــص البعــض نقــص للــكل وإال ملــا صــار للعقــود والشــروط فيهــا‬\n      ‫أي حجــة وأجيــب عــن املالحظــة الثانيــة أن املدعــى عليــه قــدم وكالــة‬\n      ‫صــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 3448913‬يف‬\n      ‫‪1434/1/13‬ه ـ ونصهــا مــا يلــي ‪ ( :‬وقــد مت االقــرار بتوكيــل ‪ ........‬فيمــا‬\n      ‫يخــص املطالبــات واحملاكــم وذلــك بالتنــازل بشــأن القضيــة املرفوعــة‬\n      ‫بخصــوص مطالبتــي ل ‪ ........‬يف أتعــاب احملامــاة وقدرهــا مئتــا ألــف ريــال‬\n\n\n‫‪239‬‬\n\f‫ومراجعــة جميــع اجلهــات ذات العالقــة وإنهــاء جميــع اإلجــراءات الالزمــة‬\n‫والتوقيــع فيمــا يتطلــب ذلك)‪.‬ا‪.‬ه ـ وعليــه رجعــت عمــا حكمــت بــه مــن‬\n‫إلــزام مــوكل املدعــي بدفــع مبلــغ وقــدره مائتــا ألــف ريــال للمدعــى‬\n‫عليــه أجــرة للمحامــاة وليــس لــدي ســوى مــا حكمــت بــه ســائال املولــى‬\n‫جــل وعــا ألصحــاب الفضيلــة مشــايخنا الكــرام التوفيــق والســداد ‪.‬‬\n‫وأغلقــت اجللســة الســاعة ‪ 08،10‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/14‬ه ـ‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3434009‬وتاريــخ‬\n                                             ‫‪ 1434/12/25‬ه ـ‬\n\n\n\n\n                                                                                ‫‪240‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":227,"source_page_end":240,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0dcb22d91c490c7afb9651acbc6dcf29b9649bc41476178b4edfa84bef4b79fb","normalized_text_hash":"34cef6a374bd2ba8996af30c87bf2ba790de5f53f8e10b375e9a8bfce1b368f2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p227-33204853"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"c3692dd3-0e5a-54f9-9c18-4272341d58aa","document_type":"judgment","category":"judicial","subcategory":"general","title":"سمسرة -مطالبة بإعادة عربون -السمسار يستحق السعي بالتوفيق بن الطرفن -ال يسترد السعي بفسخ البيع -صرف النظر عن دعوى املدعي.","document_number":"33313847","case_number":"32191693","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":"الدائرة احلقوقية اخلامسة مبحكمة الاستئناف بالرياض.","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/6/24","year":"1434","subject":"سمسرة -مطالبة بإعادة عربون -السمسار يستحق السعي بالتوفيق بن الطرفن -ال يسترد السعي بفسخ البيع -صرف النظر عن دعوى املدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33313847:‬تاريخه‪1433/6/24:‬هـ‬\n                  ‫رقم الدعوى‪32191693:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3429191‬تاريخه‪1434/2/4 :‬هـ‬\n\n\n‫سمســرة ‪ -‬مطالبــة بإعــادة عربــون ‪ -‬السمســار يســتحق الســعي‬\n‫بالتوفيــق بــن الطرفــن ‪ -‬ال يســترد الســعي بفســخ البيــع ‪ -‬صــرف‬\n                                         ‫النظــر عــن دعــوى املدعــي‪.‬‬\n\n\n\n\n‫‪ .1‬جــاء يف شــرح منتهــى اإلرادات ‪( 153/5‬ومــن قبــض شــيئ ًا بســبب عقــد‬\n‫كــدالل يف بيــع فــإن فســخ البيــع باإلقالــة ونحوهــا ممــا يقــف علــى‬\n                                              ‫تــراض الطرفــن لــم يــرده)‪.‬‬\n‫‪ .2‬جــاء يف جامــع الفصولــن ‪(211/2‬لــو اســتحق املبيــع أو رد بعيــب ال‬\n                                                           ‫تســترد الداللــة)‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه وكالــة بــأن موكلــه رغــب‬\n‫بشــراء فلــة عــن طريــق مكتــب عقــاري عائــد ملــوكل املدعــى عليــه‬\n‫وذلــك مببلــغ أربعــة ماليــن ومائتــي ألــف ريــال وبعــد أن وافــق البائــع علــى‬\n‫البيــع رجــع موكلــه وطلــب اإلقالــة مــن البائــع ووافــق البائــع وقــد ســلم‬\n‫موكلــه مبلــغ مائــة ألــف ريــال عربــون شــراء الفلــة مبوجــب شــيك وقــد‬\n‫صــدر علــى موكلــه احلكــم بدفــع املبلــغ مــن مكتــب الفصــل يف األوراق‬\n‫التجاريــة ومبــا أن البيــع ُفســخ يطلــب إلــزام املدعــى عليــه بعــدم اســتالم‬\n\n                                                                                       ‫‪104‬‬\n\f      ‫املبلــغ وإعــادة الشــيك املرفــق باملعاملــة هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n      ‫عليــه باملصادقــة علــى الدعــوى وعلــى صــدور حكــم ملوكلــه بالشــيك‬\n      ‫محــل الدعــوى مــن مكتــب الفصــل يف األوراق التجاريــة وموكلــه يطلب‬\n      ‫تســليمه الشــيك ورد الدعــوى ‪ -‬جــرى ســؤال املدعــي هــل اإلقالــة حصلت‬\n      ‫بعــد إمتــام البيــع فأجــاب باملصادقــة وأنهــا حصلــت بعــد اإليجــاب والقبــول‬\n      ‫وأن مالــك العقــار قــد تنــازل عــن العربــون وكتــب إقــرار بذلــك ‪ -‬قــرر‬\n      ‫املدعــي أصالــة بــأن ســعي الفيــا فيمــا لــو مت البيــع مبلــغ وقــدره مائــة‬\n      ‫وخمســة وعشــرون ألــف ريــال وصادقــه املدعــى عليــه علــى ذلــك ‪ -‬ومبــا‬\n      ‫أن املدعــي قــد أقــر بــأن اإلقالــة حصلــت بعــد إمتــام البيــع وأن الســعي‬\n      ‫حســب العــرف مبلــغ وقــدره مائــة وخمســة وعشــرون ألــف ريــال ‪ -‬ومبــا أن‬\n      ‫السمســار يســتحق الســعي بالتوفيــق بــن الطرفــن ‪ -‬ملــا قــرره أهــل العلــم‬\n      ‫انظــر شــرح منتهــى اإلرادات ‪ 153/5‬وجامــع الفصولــن ‪ - 211/2‬ملــا‬\n      ‫تقــدم صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه‬\n      ‫مــا يدعيــه ‪ -‬وتســليم الشــيك الــذي يف املعاملــة للمدعــى عليــه ‪ -‬قنــع‬\n      ‫املدعــى عليــه باحلكــم واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن‬\n                   ‫الدائــرة احلقوقيــة اخلامســة مبحكمــة االســتئناف بالريــاض‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬لقاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالريــاض برقــم ‪ 32191693‬وتاريــخ ‪1432/05/23‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 32599387‬وتاريــخ ‪1432/05/23‬ه ـ واملنقوضــة‬\n      ‫ســابقا مــن محكمــة االســتئناف بقــرار رقــم ‪/347‬ق‪ /5‬ب يف‬\n\n‫‪105‬‬\n\f‫‪1432/4/11‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1433/06/24‬ه ـ حضــر‬\n‫‪ ........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ) ........‬بصفتــه وكيــا عــن‬\n‫‪ ........‬نــوب عنــه يف املطالبــة واملرافعــة واملدافعــة وطلــب اليمــن واإلقــرار‬\n‫واإلنــكار وقبــول احلكــم ونفيــه واالعتــراض عليــه ومتييــزه واالســتالم‬\n‫والتســليم مبوجــب صــك وكالــة صــادر مــن كتابــة عــدل الدرعيــة‬\n‫برقــم ‪ 410602062171‬يف ‪1431/6/26‬ه ـ وادعــى علــى احلاضــر معــه‬\n‫‪ ........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ) ........‬بصفتــه وكيــا‬\n‫عــن ‪ ........‬ينــوب عنــه يف املطالبــة واملرافعــة واملدافعــة وطلــب اليمــن‬\n‫واإلقــرار واإلنــكار والصلــح وقبــول احلكــم ونفيــه واالعتــراض عليــه‬\n‫وطلــب متييــزه واالســتالم والتســليم مبوجــب صــك وكالــة صــادر مــن‬\n‫كتابــة عــدل الريــاض الثانيــة رقــم ‪ 43946‬يف ‪1431/6/11‬ه ـ قائــا‬\n‫يف حتريــر دعــواه عليــه‪ :‬إن موكلــي رغــب يف شــراء فيــا تقــع يف حــي‬\n‫الواحــة مبدينــة الريــاض والعائــدة للمدعــو ‪ ........‬عــن طريــق مكتــب‬\n‫‪ ........‬العائــد ملــوكل هــذا وأشــار إلــى املدعــى عليــه وذلــك مببلــغ‬\n‫أربعــة ماليــن ومائتــي ألــف ريــال وبعــد أن وافــق البائــع علــى البيــع رجــع‬\n‫موكلــي وطلــب اإلقالــة مــن البائــع ووافــق وقــد دفــع موكلــي مبلــغ مائــة‬\n‫ألــف ريــال عربــون شــراء الفيــا مبوجــب شــيك وصــدر علــى موكلــي‬\n‫احلكــم مــن مكتــب الفصــل يف األوراق التجاريــة ونفــذ احلكــم حيــث‬\n‫ســلم هــذا املبلــغ جلهــة قاضــي التنفيــذ مبوجــب شــيك مرفــق باملعاملــة‬\n‫وحيــث أن هــذا املبلــغ سيســلم للمدعــى عليــه بــدون حــق نظــرا ألن البيــع‬\n‫فســخ أطلــب إلــزام املدعــى عليــه بعــدم اســتالم املبلــغ وإعــادة الشــيك‬\n‫املرفــق باملعاملــة الــذي سيســلم لــه وقــدره (‪ )100000‬حيــث حــرر علــى‬\n‫أنــه عربــون وليــس مــن حقــه االحتفــاظ بــه ألنــه ليــس البائــع وإمنــا دالل‬\n\n\n                                                                                       ‫‪106‬‬\n\f      ‫للبيــع هــذه دعــواي وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي مــن أن موكلــه ســلم ملوكلــي الشــيك‬\n      ‫املذكــور يف دعــواه مببلــغ مائــة ألــف ريــال عربــون شــراء فيــا مــن‬\n      ‫الشــخص املذكــور هــذا صحيــح والشــيك محــل الدعــوى قــد صــدر‬\n      ‫بــه حكــم مــن مكتــب الفصــل يف األوراق التجاريــة بالريــاض برقــم‬\n      ‫‪ 1496‬يف ‪1430/6/15‬ه ـ وهــو حكــم مكتســب القطعيــة وهــو اآلن يف‬\n      ‫التنفيــذ وموكلــي يطلــب تســليمه الشــيك لــذا أطلــب رد دعــوى املدعــي‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة رد قائــا صحيــح‬\n      ‫أنــه ســبق أن صــدر احلكــم املذكــور ولكنــه لــم يتطــرق إلــى موضــوع‬\n      ‫الشــيك وإمنــا بنــاء علــى الشــيك أداة وفــاء جتــري مجــرى النقــود يف الوفــاء‬\n      ‫وموكلــي يطالــب بــرد الشــيك ألنــه حــرر علــى أنــه عربــون وليــس مــن‬\n      ‫حقــه االحتفــاظ بــه والســعي الــذي يطالــب بــه صاحــب املكتــب يكــون‬\n      ‫حســب العــرف والصحيــح أن موكلــي اســتلم هــذا املبلــغ علــى أن يكــون‬\n      ‫ســعي يف حــال انعقــاد البيــع ثــم إن موكلــي قــد اشــترط شــرطا علــى‬\n      ‫أن املبلــغ يفقــد يف حــال تراجــع املشــتري أو املســتأجر واملؤمنــون علــى‬\n      ‫شــروطهم فطلــب مــن الطرفــن القــرار الصــادر مــن مكتــب الفصــل‬\n      ‫فأحضــر يف هــذه اجللســة القــرار املذكــور برقــم ‪ 30/1496‬وتاريــخ‬\n      ‫‪1430/6/15‬ه ـ واملكــون مــن ثالثــة أوراق وقــد جــرى االطــاع عليــه‬\n      ‫فجــرى ســؤال املدعــي أصالــة هــل اإلقالــة حصلــت بعــد إمتــام البيــع قــال‬\n      ‫هــذا صحيــح فبعــد اإليجــاب والقبــول تراجعــت عــن الشــراء وعرضــت‬\n      ‫ذلــك علــى املالــك ووافــق وعلــى هــذا ال يســتحق الوســيط املبلــغ الــذي‬\n      ‫حــرر يف الشــيك وأبــرز ورقــة نصهــا إقــرار بالتنــازل ( أقــر أنــا ‪........‬‬\n      ‫ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم (‪ ) ........‬وأنــا بكامــل قواي‬\n\n\n‫‪107‬‬\n\f‫العقليــة ويف متــام أهليتــي املعتبــرة شــرعا ونظامــا بأننــي تنازلــت لــأخ‬\n‫‪ ........‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم (‪ ) ........‬عــن العربــون‬\n‫الــذي ســبق وأن صــدر بــه شــيك رقــم ‪ 301162‬بتاريــخ ‪2008/9/23‬م‬\n‫مببلــغ قــدره مائــة ألــف ريــال علــى بنــك ‪ ........‬إلــى ‪ ........‬صاحــب‬\n‫مكتــب ‪ ........‬بشــأن مفاوضــات شــراء الفيــا العائــدة لنــا ومســاحتها‬\n‫(‪800‬م‪ )2‬ثمامنائــة متــر مربــع يف حــي ‪ ........‬علمــا أن مفاوضــات الشــراء‬\n‫املذكــورة لــم يتــم عليهــا أي شــيء وهــذا تنــازل منــي بذلــك املقــر مبــا‬\n‫فيــه املتنــازل ‪ ........‬توقيعــه بتاريــخ ‪1431/4/27‬ه ـ الشــاهد األول ‪........‬‬\n‫‪ ........‬توقعيــه الشــاهد الثانــي ‪ ........‬توقيعه)‪.‬أه ـ فجــرى ســؤال املدعــي‬\n‫أصالــة عــن ثمــن الفيــا املشــتراة فقــال مبلــغ أربعــة ماليــن ومائتــي ألــف‬\n‫ريــال فجــرى ســؤاله عــن الســعي لهــذا املبلــغ لــو مت البيــع قــال الســعي‬\n‫حســب العــرف مبلــغ مائــة وخمســة وعشــرين ألــف ريــال وصــادق املدعــى‬\n‫عليــه علــى ذلــك فبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وبنــاء علــى ما‬\n‫أقــر بــه املدعــي مــن أن اإلقالــة حصلــت بعــد إمتــام البيــع وأن ثمــن العقــار‬\n‫مبلــغ أربعــة ماليــن ومائتــي ألــف ريــال والســعي مبلــغ مائــة وخمســة‬\n‫وعشــرين ألــف ريــال حســب العــرف ومبــا أن السمســار يســتحق الســعي‬\n‫بالتوفيــق بــن الطرفــن ومبــا أنــه قــد مت البيــع بإقــرار املدعــي وملــا قــرره‬\n‫أهــل العلــم قــال يف منتهــى اإلرادات (‪ ()153/5‬ومــن قبــض شــيئا بســبب‬\n‫عقــد كــدالل يف بيــع فــإن فســخ البيــع باإلقالــة ونحوهــا ممــا يقــف‬\n‫علــى تــراض الطرفــن لــم يــرده) ويف جامــع الفصولــن (‪ ( )211/2‬لــو‬\n‫اســتحق املبيــع أو رد بعيــب ال تســترد الداللــه) جلميــع ذلــك فقــد صرفــت‬\n‫النظــر عــن دعــوى املدعــي لعــدم اســتحقاقه مــا يدعيــه وامــرت بتســليم‬\n‫الشــيك املرفــق باملعاملــة للمدعــى عليــه وبذلــك حكمــت وبعرضــه علــى‬\n\n\n                                                                                        ‫‪108‬‬\n\f      ‫الطرفــن قنــع املدعــى عليــه ولــم يقنــع املدعــي وطالــب بتمييــزه واســتعد‬\n      ‫بتقــدمي الئحــة اعتراضيــة وأفهــم بــأن عليــه تقــدمي اعتراضــه خــال ثالثني‬\n      ‫يومــا مــن اآلن وإذا انتهــت املــدة احملــددة لالعتــراض ولــم يقــدم شــيئا‬\n      ‫ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1433/06/24‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة لتمييــز‬\n      ‫القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n      ‫‪ 32599387‬وتاريــخ ‪1434/1/7‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ......../‬برقــم ‪ 33313847‬وتاريــخ‬\n      ‫‪1433/6/24‬ه ـ اخلــاص بدعــوى‪ ......../‬ضــد‪ ......../‬يف مبلــغ مــن املــال‬\n      ‫علــى الصفــة املوضحــة يف الصــك واملتضمــن حكــم فضيلتــه كمــا هــو‬\n      ‫موضــح بالصــك وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضية‬\n      ‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى احلكــم‪ .‬واهلل‬\n                    ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪109‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":104,"source_page_end":109,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1f1d5f42f754d4df34a710b1a7e9dc2aed13cddc6cde31575e36c81bf6bee5ac","normalized_text_hash":"fca0868a424073876dfd321abbed53901db614262ebf1b916a64229c21cd6261","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p104-33313847"},{"id":"ca6ed427-e0ae-56e0-9764-9fc6db3453d4","document_type":"judgment","category":"judicial","subcategory":"general","title":"أتعاب -أتعاب محاماة -مرافعة وإنهاء اإلجراءات ومتابعة لدى اجلهات -عقد جعالة -األتعاب نسبة من احلق -وفاة احملامي وانتقال حقه لورثته -عدم حتديد األتعاب كتابة قبل البدء يف العمل- إبرام عقد اتفاق بن احملامي وورثة املوكل ملزم للطرفن -إنهاء احملامي العمل وإعادة احلق ينفي حدوث ضرر ملوكله -استطالع رأي أهل اخلبرة يف تقدير األتعاب -إقرار الوكيل ملزم للموكل .","document_number":"34220573","case_number":"32223955","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/22","year":"1434","subject":"أتعاب -أتعاب محاماة -مرافعة وإنهاء اإلجراءات ومتابعة لدى اجلهات -عقد جعالة -األتعاب نسبة من احلق -وفاة احملامي وانتقال حقه لورثته -عدم حتديد األتعاب كتابة قبل البدء يف العمل- إبرام عقد اتفاق بن احملامي وورثة املوكل ملزم للطرفن -إنهاء احملامي العمل وإعادة احلق ينفي حدوث ضرر ملوكله -استطالع رأي أهل اخلبرة يف تقدير األتعاب -إقرار الوكيل ملزم للموكل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34220573 :‬تاريخه‪1434/5/22 :‬هـ‬\n                   ‫رقم الدعوى‪32223955 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34316063‬تاريخه‪1434/9/9 :‬هـ‬\n\n\n‫أتعــاب ‪ -‬أتعــاب محامــاة‪ -‬مرافعــة وإنهــاء اإلجــراءات ومتابعــة لــدى‬\n‫اجلهات‪ -‬عقد جعالة‪ -‬األتعاب نسبة من احلق‪ -‬وفاة احملامي وانتقال‬\n‫حقــه لورثتــه‪ -‬عــدم حتديــد األتعــاب كتابــة قبــل البــدء يف العمــل‪-‬‬\n‫إبــرام عقــد اتفــاق بــن احملامــي وورثــة املــوكل ملــزم للطرفــن‪ -‬إنهــاء‬\n‫احملامــي العمــل وإعــادة احلــق ينفــي حــدوث ضــرر ملوكلــه‪ -‬اســتطالع‬\n‫رأي أهــل اخلبــرة يف تقديــر األتعــاب ‪ -‬إقــرار الوكيــل ملــزم للمــوكل ‪.‬‬\n\n\n\n\n‫‪ -1‬قــول املــرداوي يف اإلنصــاف‪ »:‬وأنــه لــو قــال (أي اجلاعــل للعامــل)‬\n‫فلــك ثلــث الضالــة أو ربعهــا صــح علــى مــا نــص عليــه يف الثــوب ينســج‬\n          ‫بثلثــه والــزرع يحصــد والنخــل يصــرم بسدســه ال بــأس بــه ا‪.‬ه ـ‬\n‫‪ -2‬وقــال يف كشــاف القنــاع ‪ 484/9‬وأن جعــل ملــن عمــل لــه عمــا عوضــا‬\n‫مجهــوال فلــه أجــره املثــل ا‪.‬ه ـ وينظــر الشــرح الكبيــر ‪ 168/16‬واإلنصــاف‬\n                                                                      ‫‪.168/16‬‬\n‫‪ -3‬قولــه يف كشــاف القنــاع ‪« 286/8‬ويصــح الصلــح عــن املجهــول‬\n‫مبعلــوم‪ ،‬إذا كان املجهــول ممــا ال ميكــن معرفتــه ســواء كان املجهــول‬\n‫عينــا أودينــا ‪ ،‬أو كان اجلهــل مــن اجلانبــن ‪ ،‬كصلــح الزوجــة عــن‬\n‫صداقهــا الــذي ال بينــة لهــا بــه ‪،‬وال علــم لهــا وال للورثــة مببلغــه ‪،‬‬\n‫وكذلــك الرجــان بينهمــا معاملــة وحســاب قــد مضــى عليــه زمــن‬\n‫طويــل ‪ ،‬وال علــم لــكل منهمــا مبــا عليــه لصاحبــه ‪ ،‬أو كان اجلهــل‬\n                                                                                 ‫‪110‬‬\n\f      ‫ممــن الديــن عليــه بــأن كان عليــه حــق ال علــم لــه بقــدره ولــو علمــه‬\n                                  ‫صاحــب احلــق وال بينــة لــه مبــا يدعيــه» ا‪.‬هــ‪.‬‬\n\n\n\n\n      ‫ا‬\n      ‫أقــام املدعــون دعواهــم ضــد املدعــى عليهــم بــأن مورثهــم كان وكيـ ً‬\n      ‫ملــورث املدعــى عليهــم بخصــوص أرض مبكــة ولــم يتفقــوا كتابــة علــى‬\n      ‫أتعابــه وبعــد اســترجاع األرض مت االتفــاق بــن مورثهــم واملدعــى عليهــم‬\n      ‫كتابــة علــى أتعــاب قدرهــا ‪ %20‬مــن ثمــن األرض إال أن املدعــى عليهــم‬\n      ‫امتنعــوا عــن ســداد هــذه القيمــة وقامــوا ببيــع األرض مببلــغ ســتني مليــون‬\n      ‫ريــال لذلــك فإنهــم يطلبــون إلــزام املدعــى عليهــم بســداد مبلــغ اثنــي عشــر‬\n      ‫مليــون ريــال نصيــب مورثهــم كأتعــاب يف ثمــن األرض املشــار إليهــا ‪-‬‬\n      ‫دفــع وكيــل املدعــى عليهــم أن هــذا االتفــاق كان مشــروط أن يتــم البيــع‬\n      ‫لشــخص معــن ولكــن ذلــك لــم يحــدث وطلــب تعويض ـ ًا مــن املدعــن‬\n      ‫لقــاء األضــرار التــي نتجــت عــن تصرفــات مورثهــم مببلــغ وقــدره ثالثــة‬\n      ‫وثالثــون مليــون ريــال وبعــد أن اســتعرضت احملكمــة كافــة األوراق‬\n      ‫وســماع الشــهود قــررت إعتبــار موضــوع الدعــوى عقــد جعالــة وأن العمــل‬\n      ‫املتفــق عليــه بــن مورثــي الطرفــن فقــد مت علــى النحــو املطلــوب وبذلــك‬\n      ‫ينتفــي الضــرر يف حــق املدعــى عليهــم‪ -‬وألن املدعــى عليهــم ومــورث‬\n      ‫املدعــن اتفقــوا علــى ‪ %20‬مــن قيمــة األرض مقابــل أتعــاب ‪ -‬حكمــت‬\n      ‫احملكمــة بإلــزام املدعــى عليهــم بســداد مبلــغ اثنــي عشــر مليــون ريــال‬\n      ‫للمدعــن ‪ -‬أعتــرض املدعــى عليهــم علــى احلكــم ‪ -‬جــرى تصديقــه‬\n      ‫مــن محكمــة اإلســتئناف قــدم املدعــى عليهــم التمــاس إلــى محكمــة‬\n                                                                 ‫اإلســتئناف ورفــض ‪.‬‬\n\n‫‪111‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....................‬القاضــي يف احملكمــة‬\n‫العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة املقيــدة باحملكمــة برقــم‬\n‫‪ 32575209‬وتاريــخ ‪1432/05/20‬ه ـ حضــر ‪..........................‬بالســجل‬\n‫املدنــي رقــم ‪ 1039132012‬بوكالتــه عــن ‪ ......................‬بالوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانية بجنوب جدة برقم ‪ 3537/34729‬يف‬\n‫‪1432/10/7‬ه ـ وبوكالتــه أيضــا عــن ‪ ............‬بوكالته عن ‪...............‬و‪.‬‬\n‫‪..................‬بالوكالــة‬                 ‫‪...........‬و‪...............‬و‪.............‬و‪..........‬أوالد‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم ‪3526/33694‬‬\n‫يف ‪1432/9/16‬ه ـ وكلتــا الوكالتــن تخولــه إقامــة وســماع الدعــاوى‬\n‫واملرافعــة واملدافعــة وحضــور اجللســات ‪..‬الــخ وادعــى علــى احلاضــر معــه‬\n‫‪.........................‬بالســجل املدنــي رقــم …………… بوكالتــه عــن‬\n‫‪ ..............................‬بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫بشــمال محافظــة جــدة برقــم ‪ 10277/8577‬يف ‪1432/1/26‬ه ـ وعــن‬\n‫‪ ..............................‬أصالــة عــن نفســه وبوكالتــه عــن ‪.........................‬‬\n‫بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف برقــم‬\n‫‪ 4584/26273‬يف ‪1431/6/5‬ه ـ وعــن ‪ ............................‬بالوكالــة‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف برقــم ‪4587/26522‬‬\n‫يف ‪1431/6/8‬ه ـ وعــن ‪ ..........................‬أصالــة عــن نفســه وبوكالتــه‬\n‫عــن ‪ .......................‬و‪.............‬و‪.............‬و‪..................‬و‪ ...................‬أوالد‬\n‫‪ ....................‬بالوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالطائــف‬\n\n\n                                                                                                         ‫‪112‬‬\n\f      ‫برقــم ‪ 4526/20454‬يف ‪1431/4/29‬ه ـ وعــن ‪ .....................‬أصالــة عن‬\n      ‫نفســه وبوكالتــه عــن أختــه ‪ .............‬بالوكالــة الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة مبكــة برقم ‪ 3878/55115‬يف ‪1429/11/10‬هـ وجميع‬\n      ‫الــوكاالت تخولــه ســماع الدعــاوى واملرافعــة املدافعــة ‪...‬الــخ قائــا يف‬\n      ‫دعــوه عليــه أدعــى أنــا ‪ ................‬ســعودي اجلنســية بالســجل املدنــي‬\n      ‫ا‬ ‫رقــم ‪ ...............‬الوكيــل الشــرعي عــن ‪ ......................‬وبصفتــه وكي ـ ً‬\n      ‫عــن (‪...............................‬ابنــاء ‪ ........................‬و‪ .......................‬أبنــاء‬\n      ‫‪........................‬وادعــى علــى املدعــى عليهــم ورثــة ‪.............................‬‬\n      ‫وهــم ورثــة (‪ ، ...........‬وورثــة ‪ ...................‬وهــم (أبنائــه ‪ ...........‬و‪).............‬‬\n      ‫ا يف‬   ‫وورثــة ‪ .............‬وهــم ‪ .........‬و‪ ).............‬و‪ ............‬و‪ ...............‬قائ ـ ً‬\n      ‫حتريــر دعــواي إن مــورث موكلــي قبــل وفاتــه كان قــد ترافــع بصفتــه‬\n      ‫الوكيــل الشــرعي عــن مــورث املدعــى عليهــم يف األرض الكائنــة‬\n      ‫‪...‬مبكــة املكرمــة ولــم يكــن هنــاك اتفــاق مبــرم مــع مــورث املدعــى‬\n      ‫عليهــم يحــدد أتعــاب مــورث موكلـ ّـي حتــى عــام ‪1426‬ه ـ حيــث اتفــق‬\n      ‫معــي جميــع الورثــة بــأن أتعابــي ‪ %20‬مــن قيمــة األرض وذلــك حســب‬\n      ‫العقــد املــؤرخ ‪1426/2/3‬ه ـ وحيــث أن مــورث موكلي يف العام ‪1415‬هـ‬\n      ‫أقــام دعــوى يف مكــة املكرمــة ضــد املدعــى عليــه ‪.....................‬مطالبـ ًا‬\n      ‫بإرجــاع األرض املذكــورة وقــد نظــرت لــدى مكتــب فضيلــة الشــيخ‬\n      ‫‪ .....................‬وقــد صــدر يف هــذه الدعــوى الصــك رقــم ‪5/19/53‬‬\n      ‫وتاريــخ ‪1416/4/1‬ه ـ وحكــم بعــدم االختصــاص وقــد اكتســب‬\n      ‫احلكــم القطعيــة ويف العــام ‪1417‬ه ـ قــام مــورث موكلــي برفــع دعــوى‬\n      ‫أخــرى بالريــاض ضــد ‪ ..........................‬مطالــب بقيمة األرض املذكورة‬\n      ‫نظــرت لــدى مكتــب الشــيخ ‪ ....‬القاضــي باحملكمــة الكبــرى‬\n\n\n‫‪113‬‬\n\f‫بالريــاض وصــدر بذلــك الصــك رقــم ‪ 16/176‬بتاريــخ ‪1419/5/24‬ه ـ‬\n‫والقاضــي باحلكــم علــى ‪ ...................‬بدفــع مبلــغ ‪( 54.000.000‬أربعــة‬\n‫وخمســون مليــون ريــال) لصالــح مــورث املدعــى عليهــم وقــد اكتســب‬\n‫هــذا الصــك القطعيــة وبنــاء ًا علــى أوامــر ملكيــة أحيلــت القضيــة‬\n‫لدراســتها مــن قبــل مجلــس القضــاء األعلــى بهيئتــه الدائمــة وتوصــل‬\n‫إلــى احلكــم رقــم ‪ 4/140‬وتاريــخ ‪1423/2/24‬ه ـ يقضــي بإلغــاء كال‬\n‫الصكــن الصادريــن مــن احملكمــة الكبــرى مبكــة املكرمــة واملنــوه‬\n‫عنــه بعاليــة والصــك الصــادر مــن احملكمــة الكبــرى بالريــاض وإرجــاع‬\n‫األرض إلــى مــورث املدعــى عليهــم واملدعــى عليهــم يعلمــون أن مــورث‬\n‫موكلــي قــد بــذل مجهــود ًَا جبــار ًا بحثــا وراء حقــوق مــورث املدعــى‬\n‫عليهــم طيلــة أكثــر مــن (‪)14‬عامـ ًا وقــد كللــت مســاعيه بالنجــاح وهلل‬\n‫احلمــد وقــد أعيــدت األرض إلــى أصحابهــا واملدعــى عليهــم أقــروا مبــا‬\n‫قــام بــه موكلــي ومــا بذلــه مــن جهــد يف هــذه الدعــوى وقــد كتبــوا لــه‬\n‫اإلقــرار املشــار إليــه بعاليــة طالــب مــورث موكلــي املدعــى عليهــم مــرار ًا‬\n‫وتكــرار ًا بتســليمه أتعابــه إال أنهــم أثــروا املماطلــة والتهــرب حتــى توفــى‬\n‫مــورث موكلــي وال زال املدعــى عليهــم مياطلــون بدفــع حقــوق موكلــي‬\n‫يف هــذه األتعــاب وملــا كان ملوكلــي بذمــة املدعــى عليهــم نســبة وقدرهــا‬\n‫‪ %20‬مــن قيمــة األرض إال أنهــم أثــروا املماطلــة والتهــرب الســيما بيعهــم‬\n‫األرض واســتحقاق نســبة موكلــي املشــار إليهــا ‪ ،‬وملــا كان ذلــك ميثــل‬\n‫ضرب ـ ًا مــن ضــروب أكل أمــوال النــاس بالباطــل وال شــك أن ذلــك ميثــل‬\n‫إضــرار ًا متعمــد ًا مبوكلــي وحيــث قــال تعالــي( يأيهــا الذيــن آمنــوا ال‬\n‫تأكلــوا أموالكــم بينكــم بالباطــل) وحيــث قــال صلــى اهلل عليــه‬\n‫وســلم (أعــط األجيــر أجــره قبــل أن يجــف عرقــه ) وقــال صلــى اهلل عليــه‬\n\n\n                                                                                      ‫‪114‬‬\n\f                                                           ‫وســلم (مطــل الغنــي ظلــم)‬\n      ‫موكلي‬\n       ‫ّ‬          ‫وأطلــب مــا يلــي ‪ :‬احلكــم علــى املدعــى عليهــم وإلزامهــم بتســليم‬\n      ‫مــا نســبته ‪ %20‬مــن قيمــة األرض املباعــة وحيــث أن املدعــى عليهــم‬\n      ‫أصالــة باعــوا األرض بســتني مليــون ريــال فأطلــب إلزامهــم بدفــع مــا‬\n      ‫يقابــل هــذه النســبة مــن هــذا املبلــغ وقــدره اثنــا عشــر مليــون ريــال هــذه‬\n      ‫دعــواي وبســؤال املدعــى عليــه وكالــة عــن دعــوى املدعــي أصالــة ثــم يف‬\n      ‫جلســة أخــرى حضــر الطرفــان وكالــة وبســؤال املدعــى عليــه وكالــة‬\n      ‫عــن اجابتــه علــى الدعــوى أبــرز ورقــة هــذا نصهــا يعلــم فضيلتكــم أن‬\n      ‫املــواد (‪ )28-27-26‬مــن نظــام احملامــاة والئحتــه التنفيذيــة قواعــد آمــره‬\n      ‫حــددت أن احملكمــة املختصــة بتحديــد أتعــاب احملامــي هــي احملكمــة‬\n      ‫التــي الــم بدقائــق الوقائــع والظــروف واملالبســات وعــدد اجللســات‬\n      ‫والعنايــة مــن واقــع املســتندات واملذكــرات املقدمــة مــن احملامــي ‪ .‬وهــذا‬\n      ‫مــا أي ــده صــك احلكــم الصــادر مــن احملكمــة العامــة بالطائــف رقــم‬\n      ‫‪ 4/5/91‬وتاريــخ ‪1431/7/16‬ه ـ واملؤيــد بقــرار محكمــة االســتئناف‬\n      ‫رقــم ‪ 1/2/357‬وتاريــخ ‪1432/4/8‬ه ـ بنــاء علــى الدفــع بعــدم اختصاص‬\n      ‫احملكمــة العامــة بالطائــف وأن محكمــة الريــاض هــي املختصــة بنظــر‬\n      ‫القضيــة إال أن املدعــي وكالــة آثــر جتاهــل حكــم فضيلتــه وحيــث أن‬\n      ‫احملكمــة العامــة مبكــة املكرمــة ســبق أن صرفــت النظــر عــن دعوانــا‬\n      ‫وكالــة ضــد ‪ .................‬نظــرا ملطالبــة الوكيــل بالقيمــة والقيمــة بذمــة‬\n      ‫‪...................‬ومت نظــر الدعــوى ضــد ‪ .........‬بالريــاض وقــد أبطلــت جميــع‬\n      ‫الصكــن بقــرار مــن مجلــس القضــاء األعلــى وأمــر ملكــي ســامي‪.‬‬\n      ‫وبنــاء عليــه أطلــب مــن فضيلتكــم صــرف النظــر عــن الدعــوى لعــدم‬\n      ‫اختصــاص احملكمــة وأن ينظــر يف طلبــي هــذا كدفــع شــكلي يبــت‬\n\n\n‫‪115‬‬\n\f‫فيــه قبــل نظــر القضيــة حرصــا علــى كســب الوقــت لنــا كمتداعــن ‪.‬‬\n‫إجابــة علــى دعــوى املدعــي أجيــب مبــا يلــي أوال «‪-:‬ال يفتــر املدعــي عــن‬\n‫تزييــف احلقائــق وتضليــل القضــاء وااللتــواء عن احلــق ‪ ،‬فها هو يدعي بأن‬\n‫الورثــة مقريــن بـ ـ ‪ %20‬وثبــوت أتعابــه!! ونتســاءل ملــاذا أقــام هــذه الدعــوى‬\n‫؟ أليــس إلثبــات أتعابــه ‪ ،‬وهــل تناســى أنــه كان شــريك يف الشــراء‬\n‫مــن الورثــة يف البيــع احليلــة الباطــل لتثبيــت األتعــاب والوصايــا الباطلــة‬\n‫بعــد أن أبطــل العقــد ومــا يدعيــه احملكمــة العامــة بالطائــف فضيلــة‬\n‫الشــيخ ‪ ...................‬بالصــك رقــم ‪ 5/8/194‬وتاريــخ ‪1429/3/10‬هــ‪ .‬ثم‬\n‫إن الورثــة لــم يقــروا ويلحــظ فضيلتكــم أن العقــد الــذي ذكــرت فيــه‬\n‫أتعابــه مبوجــب صلــح باطــل وذلــك ال يعت ــبر إقــرار ذكــر يف كشــاف‬\n‫القنــاع ‪ )425/10‬مــن ُأدعــي عليــه بحــق فأنكــره ‪ ،‬ثــم قــال صاحلنــي‬\n‫عــن املــال الــذي تدعيــه لــم يكــن مقــرا بــه وذكــر أيضـ ًا يف ‪( 424/10‬‬\n‫فمتــى كان أحدهمــا عاملـ ًا بكــذب نفســه فالصلــح باطــل يف حقــه ومــا‬\n‫أخــذه العالــم بكــذب نفســه حــرام عليــه ألنــه مــن أكل املــال بالباطــل‬\n‫وال يشــهد لــه الشــاهد بــه إن علــم ظلمــه ألنــه إعانــة علــى باطــل ) وهــذا‬\n‫مــا شــهد بــه الشــهود نظــر ًا ملــا علمــوه‪ .‬ثانيــا»‪ -:‬ليــس صحيحــا مــا ذكــره‬\n‫وكيــل املدعــي بــأن الوكيــل رحمــه اهلل طالــب بعــودة األرض ويظهــر‬\n‫لفضيلتكــم أن الوكيــل رحمــة اهلل لــم يطالــب بعــودة األرض بــل طالــب‬\n‫بالثمــن ممــا كان لــه بالــغ الضــرر علــى تكييــف القضيــة بشــكلها‬\n‫الصحيــح وأخــذ يخبــط يف رفــع الدعــاوى ويضلــل القضــاء حتــى مت‬\n‫تكييفهــا بالشــكل الصحيــح مــن مجلــس القضــاء األعلــى وعــودة‬\n‫األرض عــن طريــق أعلــى ســلطات الدولــة ولــذا فــإن ورثــة املدعــن أصالــة‬\n‫ال يســتحق أي شــيء مقابــل عملــه ونطلــب صــرف النظــر عــن دعــواه هــذه‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫إجابتــي وبعــرض هــذه اإلجابــة علــى املدعــي وكالــة ثــم يف جلســة أخــرى‬\n      ‫حضــر الطرفــان وكالــة وجــرى ســؤال املدعــي وكالــة هــل أحضــر ردا‬\n      ‫علــى إجابــة املدعــى عليــه وكالــة فأبــرز ورقــة هــذا نصهــا ‪ -:‬إن ردي‬\n                                      ‫علــى مــا قدمــه املدعــى عليــه هــو مــا يلــي ‪-:‬‬\n      ‫‪ .1‬إن املــادة ( ‪ ) 5/28‬مــن الالئحــة التنفيذيــة لنظــام احملامــاة قــد ورد‬\n      ‫فيهــا مــا نصــه (وتنظــر مــن القاضــي الــذي نظــر القضيــة األصليــة‬\n      ‫‪...‬الــخ ) وال شــك أن عبــارة ( القضيــة األصليــة ) تعنــى القضيــة التــي مت‬\n      ‫ـداء حســب النظــام ومت الترافــع فيهــا وصــدر فيهــا حكــم‪،‬‬         ‫رفعهــا ابتـ ً‬\n      ‫وهــذا مــا ينطبــق بالتمــام علــى القضيــة التــي رفعــت مــن قبــل مــورث‬\n      ‫موكلــي مطالب ـ ًا بــأرض مــورث املدعــى عليهــم والتــي نظــرت مــن قبــل‬\n      ‫فضيلــة الشــيخ ‪ ...................‬القاضــي بهــذه احملكمــة يف العــام ‪1415‬ه ـ‬\n      ‫وانتهــت بالصــك رقــم ‪ 5/19/53‬وتاريــخ ‪1416/4/1‬ه ـ ‪ ،‬وال شــك أن‬\n      ‫الدعــوى التــي رفعــت ضــد ‪ ...........................‬بالريــاض دعــوى متفرعــة‬\n      ‫عــن دعوانــا أمــام فضيلــة الشــيخ ‪ .....................‬وهــذا مــا جــاء يف عجــز‬\n      ‫املــادة ( ‪ ) 26‬مــن نظــام احملامــاة والتــي تنــص ( ويطبــق هــذا احلكــم‬\n      ‫كذلــك إذا نشــأ عــن الدعــوى األصليــة أي دعــوى فرعيــة ) ‪ .‬أمــا فيمــا‬\n      ‫يخــص الصــك الصــادر مــن محكمــة الطائــف بالرقــم ‪ 4/5/91‬وتاريــخ‬\n      ‫‪1431/7/16‬ه ـ واملصــادق عليــه مــن محكمــة االســتئناف وإن كان‬\n      ‫قــد صــدر بعــدم االختصــاص إال أنــه لــم يبــن احملكمــة املختصــة وذلــك‬\n      ‫لوجــود النصــوص النظاميــة التــي حتكــم ذلــك ‪ ،‬لــذا التمــس مــن‬\n      ‫فضيلتكــم صــرف النظــر عــن الدفــع الشــكلي وذلــك لتعــارض الطلــب‬\n                   ‫مــع النصــوص النظاميــة التــي حتكــم مســألة االختصــاص‪.‬‬\n      ‫‪ .2‬أمــا فيمــا يخــص مــا جــاء يف ( ثانيـ ًا ) مــن مذكرتــه ‪ :‬نــرد بــأن فضيلــة‬\n\n\n‫‪117‬‬\n\f‫الشــيخ ‪ .....................‬القاضــي باحملكمــة العامــة بالطائــف لــم يبطــل‬\n‫اســتحقاق مــورث موكلــي فيمــا يخــص األتعــاب بــل ذكــر أن ملــورث‬\n‫موكلــي املطالبــة مبــا نســبته ‪ %20‬مــن ثمــن األرض وبدعــوى مســتقلة‪،‬‬\n‫وال شــك أن املدعــى عليهــم أقــروا بنســبة ال ـ ‪ %20‬مــن قيمــة األرض‬\n‫كأتعــاب ملــورث موكلــي فهنــاك أقــرار موثــق مــن الورثــة يؤكــدون‬\n‫فيــه علــى أحقيــة مــورث موكلــي بهــذه النســبة ‪ ،‬أمــا مــن حيــث دعواهــم‬\n‫فقــد حصروهــا يف إبطــال البيــع فقــط ولــم يطالبــوا بأكثــر مــن ذلــك ‪.‬‬\n‫‪ .3‬وال شــك أن مــورث موكلــي يســتحق هــذه النســبة بالنظــر إلــى مــا‬\n‫بذلــه مــن جهــد ومــا عــاد مــن نفــع طــوال ‪ 14‬عــام ‪ - ،‬أمــا مــا جــاء يف (‬\n‫ـداء‬\n‫ثالثـ ًا ) مــن مذكرتــه‪ :‬فنــرد بــأن مــورث موكلنــا كان قــد طالــب ابتـ ً‬\n‫بعــن املزرعــة وهــذا مــا يظهــر يف حتريــر دعــواه األصليــة واملضمنــة يف‬\n‫الصــك رقــم ‪ 5/19/53‬وتاريــخ ‪1416/4/1‬ه ـ والتــي جــاء فيهــا ( اطلــب‬\n‫حجــز املزرعــة وإعادتهــا ملوكلــي وعــدم التصــرف فيهــا والســير يف‬\n‫القضيــة مبــا يضمــن تســليم ثمنهــا أو إعادتهــا إلــى موكلــي ) وال شــك‬\n‫ـداء علــى بيــع هــذه األرض ألن‬   ‫أن مــورث املدعــى عليهــم لــم يعتــرض ابتـ ً‬\n‫ذلــك بالضبــط مــا كان يطلبــه انــذاك عنــد إفراغهــا ل‪، .....................‬‬\n‫وبالتالــي فليــس ملــورث موكلــي اخليــرة مــن أمــره يف أن ميضــي قدمـ ًا يف‬\n‫املطالبــة بثمــن األرض لــدى ‪ ..........‬ال ســيما وقــد مت إفهامــه من قبل ناظر‬\n‫الدعــوى األصليــة بــأن الدعــوى بالثمــن تتوجــه علــى ‪،.................‬وصرفــه‬\n                                      ‫النظــر عــن الدعــوى ضــد مــن بيــده العــن‪.‬‬\n‫‪ .4‬أمــا فيمــا يخــص تقديــر األتعــاب يف حــدود الــ‪ %20‬املذكــورة يف‬\n‫أقــرار املدعــى عليهــم فقــد مت نظــر دعــوى األتعــاب أمــام فضيلــة الشــيخ‬\n‫‪ ...................‬القاضــي باحملكمــة العامــة بالطائــف وقــد أجــرى عليهــا‬\n\n\n                                                                                       ‫‪118‬‬\n\f      ‫املســتلزمات الشــرعية الكفيلــة بتقديرهــا التقديــر الشــرعي وقــد‬\n      ‫خاطــب هيئــة النظــر باحملكمــة للتدخــل وتقديــر األتعــاب وقــد مت‬\n      ‫تقديرهــا بحضــور مــورث موكلــي واملدعــى عليهــم بعــد االســتعانة بأهــل‬\n      ‫اخلبــرة يف هــذا اخلصــوص وقــد صــدر منهــم قــرار يقضــي باســتحقاق‬\n      ‫مــورث موكلــي مــا نســبته ‪ %20‬مــن قيمــة األرض ونلتمــس مــن احملكمة‬\n                                                  ‫املوقــرة طلــب هــذا التقريــر رســمي ًا ‪.‬‬\n      ‫لــذا ولــكل مــا ذكــرت التمــس مــن فضيلتكــم إلــزام املدعــى عليهــم‬\n      ‫بتســليم موكلــي مــا نســبته ‪ %20‬مــن قيمــة األرض احلقيقيــة ا‪.‬ه ـ ثــم‬\n      ‫جــرى اطالعــي علــى الصــك الصــادر مــن احملكمــة العامــة بالطائــف‬\n      ‫برقــم ‪ 5/8/194‬يف ‪1429/3/10‬ه ـ فوجدتــه يتضمــن دعــوى بعــض‬\n      ‫ورثــة ‪ .......................‬ضــد ‪ ..................‬ويطالــب فيهــا تركــة مورثهــم‬\n      ‫‪ ................‬ثــم تدخــل يف القضيــة ‪ .................‬وذكــر أن مــن أعيــان‬\n      ‫التركــة املزرعــة املســماة ‪ ...‬وســبق أن باعهــا مــورث الطرفــن ‪...............‬‬\n      ‫مــع ‪ ....................‬مببلــغ ســتة وثمانــن مليونــا وأربعمائــة ألــف ريــال ولــم‬\n      ‫يســلم لــه هــذا املبلــغ واشــترط عــدم صرفــه حتــى تنــزع املزرعــة لصالــح‬\n      ‫الدولــة ومت إفــراغ العقــار لألميــر واحتفــظ البائــع بالصــك إال أن ‪...........‬‬\n      ‫لــم يلتــزم بهــذا الشــرط واســتخرج صــك بــدل فاقــد منــه وبــاع العقــار‬\n      ‫علــى ‪ ..................‬فأقــام ‪ .............‬بصفتــه وكيــل عــن ‪ ..................‬مــورث‬\n      ‫الطرفــن دعــوى ضــد ‪ .................‬يطالبــه بالثمــن فصــرف النظــر عــن‬\n      ‫دعــواه وافهــم بــأن تقــام الدعــوى بالثمــن علــى ‪ ...............‬يف مقــر إقامتــه‬\n      ‫بالريــاض فأقــام ‪..............‬دعــواه ضــد ‪ ............‬وصــدر احلكــم بإلــزام‬\n      ‫‪ .........‬بدفــع الثمــن ثــم صــدر قــرار الهيئــة الدائمــة ملجلــس القضــاء‬\n      ‫األعلــى بإعــادة املزرعــة ملالكهــا األصلــي ‪ .................‬ومــن ثــم ورثتــه‬\n\n\n‫‪119‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":110,"source_page_end":119,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"815d2b2f132c050327ca109da6f0acf04b586e891f5bbed6a863317c90ae6172","normalized_text_hash":"3f05988c07e9ddd033f349af93f231388b981af7181665b5c6c8933f7748d65d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p110-34220573"},{"id":"e955a9aa-42e8-549b-b922-15fb3f9cbcb0","document_type":"judgment","category":"judicial","subcategory":"general","title":"سمسرة -مطالبة بإعادة مبلغ معن -عدم حضور املدعى عليه دون عذر رغم تبلغه يعد نكو ال عن اجلواب -املمتنع عن احلضور تسمع عليه البينة ويقضى بها من غير مين االستظهار -احلكم يف حق املدعى عليه حضوري لتبلغه -إلزام املدعى عليه بتسليم املبلغ","document_number":"33459984","case_number":"32252771","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/20","year":"1434","subject":"سمسرة -مطالبة بإعادة مبلغ معن -عدم حضور املدعى عليه دون عذر رغم تبلغه يعد نكو ال عن اجلواب -املمتنع عن احلضور تسمع عليه البينة ويقضى بها من غير مين االستظهار -احلكم يف حق املدعى عليه حضوري لتبلغه -إلزام املدعى عليه بتسليم املبلغ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33459984:‬تاريخه‪1433/11/20:‬هـ‬\n                         ‫رقم الدعوى‪32252771:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34220971‬تاريخه‪1434/5/25 :‬هـ‬\n\n\n      ‫سمســرة ‪ -‬مطالبــة بإعــادة مبلــغ معــن ‪ -‬عــدم حضــور املدعــى عليــه دون‬\n      ‫عــذر رغــم تبلغــه يعــد نكــو ًال عــن اجلــواب ‪-‬املمتنــع عــن احلضــور تســمع‬\n      ‫عليــه البينــة ويقضــى بهــا مــن غيــر ميــن االســتظهار ‪ -‬احلكــم يف حــق‬\n      ‫املدعــى عليــه حضــوري لتبلغــه ‪ -‬إلــزام املدعــى عليــه بتســليم املبلــغ‬\n                                                                         ‫املدعــى بــه ‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار) رواه أحمد‪.‬‬\n      ‫‪ .2‬جــاء يف شــرح املنتهــى (وإن ســكت مدعــى عليــه بــأن لــم يقــر بالدعــوى‬\n      ‫ولــم ينكرهــا أو قــال املدعــى عليــه ال أقــر وال أنكــر أو قــال ال أعلــم قــدر‬\n      ‫حقــه وال بينــة ملــدع بدعــواه قــال احلاكــم ملدعــى عليــه إن أجبــت وإال‬\n                                    ‫ال وقضيــت عليــك بالنكــول ‪.)..‬‬ ‫جعلتــك نــاك ً‬\n      ‫‪ .3‬جــاء يف اإلنصــاف (وإن ســكت املدعــى عليــه فــم يقــر ولــم ينكــر قــال‬\n      ‫ال وقضيــت عليــك وهــو‬         ‫لــه القاضــي إن أجبــت وإال جعلتــك نــاك ً‬\n                                                                             ‫املذهــب)‪.‬‬\n      ‫‪ .4‬جــاء يف حتفــة احملتــاج (وإال لتواريــه أو تعــززه أي تغلبــه وقــد ثبــت‬\n      ‫ذلــك عنــد القاضــي فتســمع البينــة ويحكــم بغيــر حضــوره مــن غيــر‬\n                   ‫ميــن االســتظهار علــى املنقــول املعتمــد تغليظ ـ ًا عليــه ‪.)..‬‬\n                                            ‫‪ .5‬املادة ‪ 55‬من نظام املرافعات الشرعية‪.‬‬\n\n\n‫‪201‬‬\n\f‫ادعــى املدعــي ضــد املدعــى عليــه بــأن مــورث موكلــه اشــترى فلــة بحــي‬\n‫‪ ...‬بواســطة املدعــى عليــه ثــم اســتلم املدعــى عليــه مبلــغ وقــدره خمســون‬\n‫ألــف ريــال بشــيك وخمســة وعشــرون ألــف ريــال داللــه وأخــذ مياطــل يف‬\n‫إمتــام البيــع حتــى تاريخــه ويطلــب إلــزام املدعــى عليــه بــرد املبلــغ وقــدره‬\n‫خمســة وســبعون ألــف ريــال هكــذا ادعــى ‪ -‬طلــب املدعــى عليــه اإلمهــال‬\n‫للجــواب يف اجللســة القادمــة ‪ -‬لــم يحضــر املدعــى عليــه مــع تبلغــه جــرى‬\n‫ســؤال املدعــي عــن بينتــه ‪ -‬قــدم املدعــى الشــيك رقــم ‪ ...‬مببلــغ خمســن‬\n‫ألــف ريــال وإقــرار املدعــى عليــه باســتالم املبلــغ املدعــى بــه يف صــك‬\n‫احلكــم املنقــوض وشــهادة الشــاهد املثبتــة يف الصــك ‪ -‬ومبــا أن املدعــى‬\n‫عليــه تخلــف عــن احلضــور رغــم تبلــغ وكيلــه الشــرعي وإفهامــه بإيــداع‬\n‫جوابــه قبــل موعــد اجللســة بثالثــة أيــام ومبــا أن عــدم حضــوره وإيــداع‬\n‫دفاعــه دون عــذر يعــد نكــو ًال عــن اجلــواب والنــاكل يقضــى عليــه ملــا‬\n‫قــرره الفقهــاء ‪ -‬ومبــا أن امتنــاع املدعــى عليــه عــن احلضــور يعــد إضــرار ًا‬\n‫باملدعــي والضــرر يــزال ‪ -‬ومبــا أن املمتنــع عــن احلضور تســمع عليه البينة‬\n‫ويقضــى بهــا مــن غيــر ميــن االســتظهار ‪ -‬وبنــاء علــى إقــرار املدعــى عليــه‬\n‫باملبلــغ املدعــى بــه يف صــك احلكــم املنقــوض ‪ -‬ملــا تقــدم صــدر احلكــم‬\n‫بإلــزام املدعــى عليــه بتســليم املبلــغ املدعــى بــه وقــدره خمســة وســبعون‬\n‫ألــف ريــال ملــوكل املدعــي ‪ -‬يعــد هــذا احلكــم يف حــق املدعــى عليــه‬\n‫حضوري ـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات وســيبلغ باحلكــم ‪-‬‬\n‫قنــع املدعــي وكالــة باحلكــم ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n                  ‫األولــى مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n                                                                                        ‫‪202‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪32252771‬‬\n      ‫وتاريــخ ‪ 1432/06/27‬ه ـ املقيــدة باحملكمــة برقــم ‪32759673‬‬\n      ‫وتاريــخ ‪ 1432/06/22‬ه ـ واملنقــوض بالقــرار رقــم ‪/1/21‬ن وتاريــخ‬\n      ‫‪1432/6/11‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1433/03/08‬ه ـ أفتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 53‬وفيهــا حضــر ‪ ........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ........‬بصفتــه وكيــا عــن ‪ ........‬ولــي اصالــة‬\n      ‫عــن نفســه وبواليتــه علــى اخويــه ‪ ........‬و‪ ........‬مبوجــب صــك الواليــة‬\n      ‫الصــادر مــن احملكمــة العامــة بجــدة برقــم ‪ 13/120‬يف ‪1427/7/26‬ه ـ‬\n      ‫وبوكالتــه عــن ‪ ........‬ولــي و‪ ........‬و‪ ....‬و‪ ........‬و‪ ........‬بصفتهــم مــن‬\n      ‫ورثــة املتــويف ‪ ........‬مبوجــب صــك حصــر الورثــة الصــادر مــن احملكمــة‬\n      ‫العامــة بجــدة برقــم ‪ 15/104‬وتاريــخ ‪1427/7/25‬ه ـ مبوجــب الوكالــة‬\n      ‫رقــم ‪ 51636‬وتاريــخ ‪1428/6/12‬ه ـ وادعــى علــى احلاضــر معــه ‪........‬‬\n      ‫ســعودي اجلنســية مبوجب الســجل املدني رقم ‪ ........‬بصفته وكيال عن‬\n      ‫‪ ........‬مبوجــب الوكالــة رقــم ‪ 15928‬وتاريــخ ‪1433/2/17‬ه ـ قائــا يف‬\n      ‫دعــواه أن مــورث موكلــي اشــترى فلــه بحــي ‪ ...‬بواســطة املدعــى عليــه ثــم‬\n      ‫اســتلم مبلــغ وقــدره خمســون ألــف ريــال شــيك وخمســة وعشــرون ألــف‬\n      ‫ريــال داللــه وإخــذ مياطــل حتــى تاريخــه يف إكمــال البيــع نطلــب إلزامــه‬\n      ‫بإرجــاع املبلــغ الــذي يف ذمتــه وهــو خمســة وســبعون ألــف ريــال هــذه‬\n      ‫دعــواي وبعــرض ذلــك علــى املدعــى عليــه قــال أطلــب مهلــة للــرد هكــذا‬\n\n‫‪203‬‬\n\f‫قــال ويف يــوم الثالثــاء املوافــق‪ 1433/06/24‬ه ـ افتتحت اجللســة الســاعة‬\n‫‪ 10 : 01‬وفيهــا حضــر ‪ ........‬واملدونــه هويتــه ووكالتــه ســابق ًا ولــم‬\n‫يحضــر املدعــى عليــه رغــم تبلغــه باملوعــد يف اجللســه املاضيــه وبســؤال‬\n‫املدعــي وكالــه قــال أطلــب تبليغــه عــن طريــق البحــث والتحــري لــذا‬\n‫جــرى تأجيــل اجللســه لتبليــغ املدعــى عليــه عــن طريــق البحــث والتحــري‪.‬‬\n‫ويف يــوم الســبت املوافــق‪ 1433/11/20‬ه ـ لــدي أنــا ‪ ........‬القاضــي‬\n‫يف احملكمــة العامــة مبحافظــة جــدة وخلــف فضيلــة الشــيخ ‪، ........‬‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة ‪ ........‬ولــم يحضــر املدعى‬\n‫عليــه وال مــن ميثلــه وقــد وردنــا أصــل ورقــة البــاغ موقعــة مــن املســتلم‪........‬‬\n‫وصفتــه وكيــل شــرعي ومتبلــغ عــن طريــق املشــرف اإلداري مبكتبنــا‬\n‫وتوقيعــه‪ .‬ا‪.‬ه ـ وقــد وردنــا كتــاب مديــر شــعبة التحريــات والبحــث‬\n‫اجلنائــي رقــم‪/4/20/1733 :‬ع‪ 22‬يف‪1433/1/25 :‬ه ـ ونــص احلاجــة‬\n‫منــه‪( :‬عليــه نفيــد فضيلتكــم بأنــه حضــر لدينــا املذكــور وأقــر بإقــراره‬\n‫املرفــق بأنــه مســتعد مبراجعتكــم وإنهــاء الدعــوى املقامــة ضــده)‪ .‬ا‪.‬‬\n‫ه ـ وباالطــاع علــى احملضــر املرفــق وجدنــا مــا نصــه‪( :‬أتعهــد أنــا ‪........‬‬\n‫بــأن أراجــع احملكمــة العامــة مبحافظــة جــدة لــدى الشــيخ ‪ ........‬إلنهــاء‬\n‫الدعــوى املقامــة ضــدي مــن ‪ ........‬وعليــه جــرى التوقيــع‪ .‬توقيــع)‪ .‬ا‪ .‬ه ـ‬\n‫وبســؤال املدعــي وكالــة عــن بينتــه أجــاب قائــا‪ :‬بينتــي الشــيك رقــم‬\n‫‪ ...‬يف ‪1427/6/18‬ه ـ الصــادر مــن ‪ ........‬ولــي لصالــح الســيد ‪........‬‬\n‫مببلــغ قــدره خمســون الــف ريــال وذلــك عربــون فيــا ورثــة ‪ ...‬املســحوب‬\n‫علــى بنــك ‪ ........‬ا‪.‬ه ـ وباالطــاع علــى صورتــه وجدنــاه طبقــا ملــا ذكــر‬\n‫وبســؤاله هــل لديــه زيــادة بينــه اجــاب قائــا نعــم وابــرز الشــيك رقــم ‪14‬‬\n‫يف ‪1427/6/18‬ه ـ الصــادر مــن ‪ ........‬ولــي لصالــح الســيد ‪ ........‬مببلــغ‬\n\n\n                                                                                            ‫‪204‬‬\n\f      ‫قــدره خمســة وعشــرون ألــف ريــال ســعودي وذلــك داللــة فيــا ورثــة ‪........‬‬\n      ‫املســحوب علــى بنــك ‪ ........‬ا‪.‬ه ـ وباالطــاع علــى صورتــه وجدنــاه طبقــا‬\n      ‫ملــا ذكــر وبســؤاله هــل لديــه زيــادة بينــه اجــاب قائــا نعــم وهــي اقــراره‬\n      ‫باســتالم املبلــغ املشــار إليــه املثبــت علــى الصــك املنقــوض مــن املكتــب‬\n      ‫القضائي الثالث رقم‪ 3/200/109 :‬يف ‪1430/5/11‬هـ وباالطالع عليه‬\n      ‫وجدنــا أن املدعــي ‪ ....‬ولــي باالصالــة عن نفســه وبوكالته عن ورثة ‪........‬‬\n      ‫واملدعــى عليــه ‪ ........‬واملتضمــن مــا نصــه ( واســتلمت مــن مورثهــم هــذا‬\n      ‫املبلــغ وقــدره خمســة وســبعون ألــف ريــال ولــي منهــا مبلــغ داللــه خمســة‬\n      ‫وعشــرون ألــف ريــال حســب العقــد مناصفــة يف مبلــغ الداللــة بينــي وبــن‬\n      ‫شــخص اســمه ‪ ........‬مينــي اجلنســية أمــا مبلــغ خمســون ألــف ريــال فقــد‬\n      ‫ســلمتها للبائــع ‪ ........‬وكيــل ورثــة ‪ ........‬وقــد حصــل اتفــاق حيــث طلــب‬\n      ‫مــورث املدعــي مهلــة أســبوع ثــم تغيــب ومضــت املهلــة وعلمنــا بعــد ذلــك‬\n      ‫انــه تــويف بعدهــا بشــهر ) ا‪.‬ه ـ ثــم أضــاف‪ :‬علــى فــرض أنــه ســلمها لـ ــ‪........‬‬\n      ‫فإنــه ليــس وكيــا عــن الورثــة هكــذا أضــاف‪ .‬وبســؤاله هــل لديــه زيــادة‬\n      ‫بينــه أجــاب قائــا نعــم وهــي شــهادة الشــاهد املثبتــة يف صــك احلكــم‬\n      ‫املشــار إليــه أعــاه وباالطــاع عليــه وجدنــا مــا نصــه‪( :‬فأحضــر الشــاهد‬\n      ‫‪ ........‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‪ ........ :‬وبســؤاله‬\n      ‫عمــا لديــه مــن شــهادة قــال أشــهد هلل بأننــي كنــت حاضــرا يف وقــت‬\n      ‫كتابــة املبايعــة التــي كانــت بــن ‪ ........‬و‪ ........‬وأشــهد أن التأخيــر‬\n      ‫كان مــن املدعــى عليــه ‪...‬ويقــول إن صاحــب العقــار ‪ ........‬مســافر إلــى‬\n      ‫خــارج اململكــة وأنــه ســيعود بعــد أســبوعني ثــم اتصلنــا باملدعــى عليــه‬\n      ‫‪...‬فقــال لــم يعــد مــن الســفر فأشــهد أن التأخيــر لــم يكــن مــن ‪........‬‬\n      ‫بــل كان مــن املدعــى عليــه ‪ ...‬هكــذا شــهد)‪ .‬ا‪ .‬ه ـ وبســؤاله هــل لديــه‬\n\n\n‫‪205‬‬\n\f‫زيــادة بينــة أجــاب قائــا ليــس لــدي ســوى مــا ذكــرت هكــذا اجــاب‪.‬‬\n‫وباالطــاع علــى أصــل الصــك رقــم‪ 3/200/109 :‬يف‪1430/5/11 :‬ه ـ‬\n‫وجدنــا مــا نصــه‪( :‬وعليــه ورد خطــاب رئيــس قســم اخلبــراء باحملكمــة‬\n‫رقــم‪ 30/51691 :‬يف‪1431/2/11 :‬ه ـ املعطــوف علــى رئيــس طائفــة‬\n‫العقــار مبحافظــة جــدة املتضمــن أنــه بحســب املتعــارف عليــه فيجــب أوال‬\n‫أن تكــون الدفعــة األولــى باســم البائــع وليــس باســم صاحــب املكتــب‬\n‫ثانيــا تصــرف الداللــة للمكتــب بعــد امتــام عملــة اإلفــراغ ثالثــا مــا لــم‬\n‫يتــم توقيــع عقــد املبايعــة مــن الطــرف االول البائــع او مــن ينــوب عنــه‬\n‫بوكالــه شــرعية وهــذا يبطــل البيــع وتكــون املبايعــة غيــر صحيحــه)‬\n‫ا‪.‬ه ـ ثــم قــرر املدعــي وكالــة قائــا ان البيــع لــم يتــم بــن ورثــة ‪ ........‬وبــن‬\n‫مــورث موكلــي الجــل مماطلــة املدعــى عليــه اذا انــه اخــذ املبلــغ وليــس‬\n‫يف يــده حــل وال عقــد بخصــوص هــذا املنــزل الــذي تســلم داللتــه هكــذا‬\n‫قــرر فبنــاء علــى مــا ســلف ‪ ،‬وألن املدعــى عليــه قــد تخ ّلــف عــن احلضــور‬\n‫مــع تبلــغ وكيلــه شــخصي ًا مبوعــد هــذه اجللســة ـ حســب اإلفــادة املرفقــة‬\n‫باملعاملــة ـ‪ ،‬واســتالمه لصحيفــة الدعــوى وإفهامــه بإيــداع دفاعــه‬\n‫وجوابــه قبــل موعــد اجللســة بثالثــة أيــام‪ ،‬وحيــث إن عــدم إيــداع جوابــه‬\n‫ودفاعــه يف احملكمــة قبــل موعــد اجللســة بثالثــة أيــام وعــدم حضــوره‬\n‫بعــد علمــه بالدعــوى ومضمونهــا وموعــد اجللســة دون عــذر يعـ ّـد نكــو ًال‬\n‫عــن اجلــواب‪ ،‬والنــاكل يقضــى عليــه‪ ،‬قــال صاحــب شــرح املنتهــى‪( :‬وإن‬\n‫ســكت مدعــى عليــه) بــأن لــم يقــر بالدعــوى ولــم ينكرهــا (أو قــال)‬\n‫املدعــى عليــه‪( :‬ال أقــر وال أنكــر أو) قــال‪( :‬ال أعلــم قــدر حقــه وال بينــة)‬\n‫ملــدع بدعــواه ( قــال احلاكــم ) ملدعــى عليــه‪( :‬إن أجبــت وإال جعلتــك‬\n‫نــاكال وقضيــت عليــك) بالنكــول‪ .)...‬ا‪.‬ه ـ ويف اإلنصــاف‪( :‬قولــه‪( :‬وإن‬\n\n\n                                                                                            ‫‪206‬‬\n\f      ‫ســكت املدعــى عليــه فلــم يقــر ولــم ينكــر‪ ،‬قــال لــه القاضــي‪ :‬إن أجبــت‬\n      ‫ال وقضيــت عليــك‪ ،‬وهــو املذهــب)‪ .‬ا‪ .‬ه ـ وألن امتنــاع‬      ‫وإال جعلتــك نــاك ً‬\n      ‫املدعــى عليــه عــن احلضــور يعـ ّـد إضــرار باملدعــي والضــرر يــزال؛ لقــول‬\n      ‫النبـ ّـي ـ صلــى اهلل عليــه وسـلّم ـ‪( :‬ال ضــرر وال ضــرار) رواه اإلمــام أحمــد‪،‬‬\n      ‫ويقضــى بهــا مــن غيــر‬   ‫البينــة ُ‬\n                                       ‫أن املمتنــع عــن احلضــور ُتســمع عليــه ّ‬   ‫ومبــا َّ‬\n      ‫ميــن االســتظهار‪ ،‬قــال صاحـ ُـب حتفــة احملتــاج يف شــرح املنهــاج‪( :‬وإال‬\n      ‫البينــة‬\n            ‫لتواريــه أو تعــززه أي‪ :‬تغلبــه وقــد ثبــت ذلــك عنــد القاضــي فتســمع ّ‬\n      ‫ويحكــم بغيــر حضــوره مــن غيــر ميــن لالســتظهار علــى املنقــول املعتمــد‬\n      ‫تغليظـ ًا عليــه‪ ،‬وإال المتنــع ال َّنــاس ك ّلهــم‪ ،‬فــإن لــم يكــن للمدعــي بينــة‬\n      ‫جعــل اآلخــر يف حكــم ال ّنــاكل فيحلــف املدعــي ميــن الــر ّد ـ خالف ـ ًا‬\n      ‫للمــاوردي ومــن تبعــه ـ ثــم يحكــم لــه)‪ ،‬ومبــا ان املدعــي وكالــة اقــام‬\n      ‫بينــة علــى اســتالم املدعــى عليــه للمبلــغ املدعــى بــه وقــدره‪ :‬خمســة‬\n      ‫وســبعون ألــف ريــال‪ ،‬وهــي‪ :‬اإلقــرار املرصــود أعــاه ونــص احلاجــة‬\n      ‫منــه‪( :‬واســتلمت مــن مورثهــم هــذا املبلــغ وقــدره خمســة وســبعون الــف‬\n      ‫ريــال ولــي منهــا مبلــغ داللــه خمســة وعشــرون الــف ريــال حســب العقــد‬\n      ‫مناصفــة يف مبلــغ الداللــة بينــي وبــن شــخص اســمه ‪ ........‬مينــي اجلنســية‬\n      ‫امــا مبلــغ خمســون الــف ريــال فقــد ســلمتها للبائــع ‪ ........‬وكيــل ورثــة‬\n      ‫‪ ........‬وقــد حصــل اتفــاق حيــث طلــب مــورث املدعــي مهلــة اســبوع ثــم‬\n      ‫تغيــب ومضــت املهلــة وعلمنــا بعــد ذلــك انــه تــويف بعدهــا بشــهر ) ا‪.‬ه ـ‬\n      ‫فقــد أقــر املدعــى عليــه باســتالمه كامــل املبلــغ املدعــى بــه ودفــع بتســلم‬\n      ‫مبلغــا قــدره‪ :‬خمســون ألــف ريــال لوكيــل ورثــة البائــع‪ ،‬ودفعــه هــذا ال‬\n      ‫يلتفــت إليــه إذ إنــه لــم يقــم بينــة علــى ذلــك‪ ،‬وبنــاء علــى املــادة اخلامســة‬\n      ‫واخلمســون مــن نظــام املرافعــات الشــرعية‪ ،‬لذلــك كلــه فقــد الزمــت‬\n\n\n‫‪207‬‬\n\f‫املدعــى عليــه اصالــه ‪ ........‬ســجل رقــم ‪ ........‬بتســليم املبلــغ املدعــى بــه‬\n‫وقــدره خمســة وســبعون الــف ريــال لورثــة ‪ ........‬وبذلــك قضيــت وهــذا‬\n‫احلكــم يعــد حضوريــا يف حــق املدعــى عليــه وباعــان احلكــم قــرر‬\n‫املدعــي وكالــة قناعتــة باحلكــم امــا املدعــى عليــه فســوف يبلــغ بنســخة‬\n‫مــن احلكــم واذا اســتلم احلكــم لشــخصه فلــه احلــق يف تقــدمي اعتراضــه‬\n‫ملــدة ثالثــن يــوم مــن تاريــخ اســتالمه احلكــم فــاذا مضــت هــذه املــدة ولــم‬\n‫يقــدم اعتراضــة ســقط حقــة يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫واذا اســتلمه لغيــر شــخصة رفــع احلكــم حملكمــة االســتئناف لتدقيقــة‬\n‫حســب التعليمــات وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/20‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة املســاعد بجــدة برقــم ‪32/759673‬‬\n‫وتاريــخ ‪1434/4/30‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n‫‪ ........‬القاضــي باحملكمــة العامــة مبحافظــة جــدة واملســجل بعــدد‬\n‫‪ 33459984‬وتاريــخ ‪ 1433/11/20‬هـ ـ واملتضمــن دعــوى‪ ........ /‬اصالــة‬\n     ‫عــن نفســه ووكالــة ضــد‪ ........ /‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم واهلل املوفق‪.‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                        ‫وســلم ‪،،،‬‬\n\n\n\n\n                                                                                        ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":201,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"da63ce8ea8234c9ac44504163d2a01fb232cad7f2e10a8d56b223a4b5f6d1466","normalized_text_hash":"64f98432fb8db67c3ad767c7798a56e1e5a186a5219b8d41409cc054866d4ba2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p201-33459984"},{"id":"cd540b26-4ff5-58aa-8303-500c339cd30e","document_type":"judgment","category":"judicial","subcategory":"general","title":"جعالة -مطالبة باسترداد أجرة جعالة لبطان عقد البيع -دفع بأن اجلعل ليس سعيا بل على اجلمع بن املتعاقدين -دفع بإقرار املدعي بأنه غير مسترد -احلكم برد اجلعل للمدعي لثبوت بطان العقد الذي أخذ اجلعل ألجله.","document_number":"34193570","case_number":"32534792","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/21","year":"1434","subject":"جعالة -مطالبة باسترداد أجرة جعالة لبطان عقد البيع -دفع بأن اجلعل ليس سعيا بل على اجلمع بن املتعاقدين -دفع بإقرار املدعي بأنه غير مسترد -احلكم برد اجلعل للمدعي لثبوت بطان العقد الذي أخذ اجلعل ألجله.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34193570 :‬تاريخه‪1434/4/21 :‬هـ‬\n                         ‫رقم الدعوى‪32534792 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34286360‬تاريخه‪1434/8/2 :‬هـ‬\n\n\n      ‫جعالــة ‪ -‬مطالبــة باســترداد أجــرة جعالــة لبطــان عقــد البيــع ‪ -‬دفــع‬\n      ‫بــأن اجلعــل ليــس ســعيا بــل علــى اجلمــع بــن املتعاقديــن ‪ -‬دفــع بإقــرار‬\n      ‫املدعــي بأنــه غيــر مســترد ‪ -‬احلكــم بــرد اجلعــل للمدعــي لثبــوت بطــان‬\n                                               ‫العقــد الــذي أخــذ اجلعــل ألجلــه‪.‬‬\n\n\n\n\n      ‫كا َنـ ْـت‬      ‫‪ .1‬البهوتــي كشــاف القنــاع يف بــاب الصــداق مــا نصــه‪َ « :‬و ِإ ْن َ‬\n      ‫ك ُأ ْجـ َـر ِة الـ َّـد َّللِ َو َن ْح ِو َهــا )‬          ‫ا ْل َع ِط َّي ـ ُة ل َِغ ْي ـ ِر ا ْل َعاقِ َد ْيـ ِـن ِب َسـ َـب ِب ا ْل َع ْقــدِ َ‬\n      ‫ك ُأ ْجـ َـر ِة ا ْل َك َّيــالِ َوا ْل ـ َو َّزانِ ( َقــالَ ا ْبـ ُـن َعقِ يــلٍ ) ِف ال َّن َظ ِر َّيــاتِ ( ْإن فُ ِسـ َـخ‬                       ‫َ‬\n      ‫اض) مِ ـ ْـن ا ْل َعاقِ َد ْيـ ِـن ( َلـ ْـم َيـ ُـر َّد ُه)‬  ‫ـف َع َلــى َتـ َـر ٍ‬    ‫مــا َيقِ ـ ُ‬  ‫َب ْيـ ٌـع ِب ِإ َقا َلـ ٍة َو َن ْح ِو َهــا ِ َّ‬\n      ‫أ َْي َلـ ْـم َيـ ُـر َّد الـ ّـدالل َمــا أ ََخـ َـذ ُه ( َوإال ) أ َْي َو ِإ ْن َلـ ْـم َيقِ ـ ْـف ا ْل َف ْسـ ُـخ َع َلــى‬\n        ‫كا ْل َف ْسـ ِـخ ل َِع ْيـ ٍـب َو َن ْحـ ِو ِه ( َر َّد ُه ) أ َْي َر َّد الــدالل َمــا أ ََخـ َـذ ُه َّ‬\n      ‫ألن‬                                                                                                                         ‫اضيهِ َمــا َ‬     ‫َت َر ِ‬\n                                                            ‫ْالَ ِبيـ َـع َو َقـ َـع ُم َتـ َـر ِّد ًدا َب ْي َنــا ال ُّل ـ ُزو ِم َو َع َدمِ ـهِ» أ‪.‬هــ‪.‬‬\n      ‫‪ .2‬مطالــب أولــي النهــى يف بــاب الشــروط يف البيــع ‪« :‬فَ ْصــلٌ ‪َ ( :‬و َمـ ْـن َبــا َع‬\n      ‫اع ـ ُه ؛ َلـ ْـم َي ْبـ َـر ْأ ‪َ ( ،‬أ ْو )‬ ‫يمــا َب َ‬  ‫ك ِّل َع ْيـ ٍـب ) فِ َ‬      ‫َش ـ ْي ًئا ( ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة مِ ـ ْـن ُ‬\n      ‫ان ِف ْالَ ِبيـ ِـع ( َلـ ْـم َي ْبـ َـر ْأ َبا ِئـ ٌـع)‬  ‫ك َ‬   ‫كـ َـذا ) ‪ْ ،‬إن َ‬       ‫ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ( مِ ـ ْـن َع ْيـ ِـب َ‬\n      ‫ـك ‪َ ،‬ولِ ُ ْش ـ َت ٍر ا ْل َف ْسـ ُـخ ِب َع ْيـ ٍـب َلـ ْـم ُي ْع َلـ ْـم َحا َل ـ َة َع ْقــدٍ ؛ لِ َــا َر َوى أ َْح َمـ ُـد‬           ‫ِب َذ ِلـ َ‬\n      ‫أ ََّن ا ْبـ َـن ُع َمـ َـر َبــا َع َز ْيـ َـد ْبـ َـن َثا ِبـ ٍـت َع ْبـ ًـدا ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ِب َث َم ِانِا َئـ ِة ِد ْر َهـ ٍـم‪،‬‬\n      ‫ـاب َز ْيـ ٌـد ِب ـ ِه َع ْي ًبــا ‪،‬فَ ـ َأ َرا َد َر َّد ُه َع َلــى ا ْبـ ِـن ُع َمـ َـر فَ َلـ ْـم َي ْق َب ْل ـ ُه ‪ ،‬فَ َت َرافَ َعــا‬\n                                                                                                                                             ‫فَ َأ َصـ َ‬\n      ‫ـك َلـ ْـم َت ْع َلـ ْـم ِب َهـ َـذا‬   ‫ـف َأ َّنـ َ‬‫ت ِلـ ُ‬ ‫ـان ِل ْبـ ِـن ُع َمـ َـر ‪ْ َ :‬‬  ‫ـان ‪ ،‬فَ َقــالَ ُع ْث َمـ ُ‬        ‫إ َلــى ُع ْث َمـ َ‬\n‫‪209‬‬\n\f                             ‫اع ـ ُه ا ْبـ ُـن ُع َمـ َـر ِب َأ ْلـ ِ‬\n‫ـف ِد ْر َهـ ٍـم ‪َ .‬و َهــذِ ِه‬                                    ‫ا ْل َع ْيـ ِـب ؟ َقــالَ ‪َ :‬ل ‪ ،‬فَ ـ َـر َّد ُه َع َل ْي ـ ِه ‪ ،‬فَ َب َ‬\n                                         ‫اش ـ َت َه َر ْت ‪َ ،‬و َلـ ْـم ُت ْن َكـ ْـر‪ ،‬فَ َكا َنـ ْـت كاإلجمــاع»‪.‬‬         ‫َق ِض َّي ـ ٌة ْ‬\n\n\n\n\n‫ادعــى املدعــى علــى املدعــى عليــه أنــه ســلمه مبلــغ (‪ )250.000‬ريــال‬\n‫أجــرة ســعي علــى عقــد شــراء أرض ‪ ،‬وقــد ظهــر بطــان العقــد وحكــم‬\n‫بحكــم يثبــت ذلــك واحلكــم مصــدق مــن محكمــة االســتئناف‪ ،‬وقــام‬\n‫البائــع بإعــادة ثمــن األرض وهمــش علــى الصــك بذلــك ولبطــان الصــك‬\n‫يطلــب املدعــى إلــزام املدعــى عليــه بــرد مــا ســلم لــه ‪ ،‬املدعــى عليــه‬\n‫صــادق علــى حصولــه علــى املبلــغ وقــرر أنــه ال يوافــق علــى رد املبلــغ ألنــه‬\n‫قبضــه بنــاء علــى عمــل ولــم يكــن ســعي بــل جعالــة والســعي يدفــع عنــد‬\n‫اإلفــراغ ويطلــب رد الدعــوى‪ ،‬وقــدم مذكــره بالــرد ومــا فيهــا مــن دفــاع‬\n‫وقــدم املدعــى احلكــم الصــادر بإبطــال البيــع ودفــع بعلــم املدعــى عليــه‬\n‫بحــال االرض محــل احلكــم مــن انهــا موقوفــه‪ ،‬رد املدعــى عليــه بأنــه‬\n‫علــم أن األرض محــل عقــد البيــع موقوفــه الحق ـ ًا بعــد اســتالمه للمبلــغ‪.‬‬\n‫ولتأمــل الدعــوى وإلقــرار املدعــى عليــه باســتالم املبلــغ مــن املدعــى‬\n‫مقابــل جعالــة شــرط اســتحقاقها احضــار البائــع والتوقيــع علــى عقــد‬\n‫شــراء األرض وملــا يثبــت باحلكــم الســابق بطــان البيــع الختــال شــرط‬\n‫مــن شــروط صحتــه وثبــت شــرع ًا عــدم انعقــاده ألجلــه فــإن ذلــك يــؤول‬\n‫لبطــان العــوض «اجلعــل» الــذي علــق اســتحقاقه عليــه علــى الصحيــح‬\n‫مــن كالم الفقهــاء أنــه ال اثــر ملــا دفــع بــه املدعــى عليــه مــن أنــه اســتحق‬\n‫العــوض مبوجــب عقــد جعالــه ال ســعي حيــث نــص علــى جــواز مطالبــة‬\n‫الدافــع بــرد العــوض املســلم لغيــر املتعاقديــن متــى كان بســبب العقــد‬\n\n                                                                                                                                              ‫‪210‬‬\n\f      ‫كأجــرة الــدالل والــوزان وكان الفســخ مــن غيــر تراضــي مــن الطرفــن‬\n      ‫جميع ـ ًا كاإلقالــة وهــذان الشــرطان يتحققــان يف هــذه الواقعــة محــل‬\n      ‫ا عــن أن اجلعالــة والســعي والداللــة الفــاظ ملســمى واحــد هــو‬\n                                                                        ‫النظــر فضـ ً‬\n      ‫«اجلعالــة» ‪ ،‬وعليــه فقــد حكــم علــى املدعــى عليــه بدفــع مبلــغ مائتــن‬\n      ‫وخمســن ألــف ريــال للمدعــى ويعــد احلكــم حضوري ـ ًا صــدق علــى‬\n                                              ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 32534792‬وتاريــخ‬\n      ‫‪1432/11/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321434064‬وتاريــخ‬\n      ‫‪1432/11/12‬ه ـ ففــي يــوم الســبت ‪1433/06/21‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪11 : 41‬وفيهــا حضــر (‪ )......‬ويحمــل الســجل املدنــي رقــم (‪)......‬‬\n      ‫ا عــن (‪ )......‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬        ‫بصفتــه وكي ـ ً‬\n      ‫العدل الثانية شمال محافظة جدة برقم ‪ 48763‬وتاريخ ‪1432/5/29‬هـ‬\n      ‫واملخــول لــه فيهــا املخاصمــة واحملاكمــة ومتابعــة القضايــا املقامــة منــه‬\n      ‫أو ضــده واملدافعــة واملرافعــة وتقــدمي البينــات ‪...‬الــخ وحضــر حلضــوره‬\n      ‫املدعــى عليــه(‪ )......‬ويحمــل الســجل املدنــي رقــم (‪ )......‬وادعــى األول‬\n      ‫ا لقــد ســلم موكلــي لهــذا احلاضــر مائتــن وخمســن ألــف ريــال‬         ‫قائ ـ ً‬\n      ‫أجــرة ســعي علــى عقــد شــراء أرض يف (‪ )......‬مــن (‪ )......‬أصالــة عــن‬\n      ‫نفســه وبوكالتــه عــن موكليــه وقــد ظهــر بطــان العقــد وحكــم‬\n      ‫بحكــم يثبــت ذلــك مــدون علــى الصــك املســجل برقــم ‪5/200/134‬‬\n\n‫‪211‬‬\n\f‫وتاريــخ ‪1431/7/30‬ه ـ واملصــدق مــن محكمــة االســتئناف بالقــرار‬\n‫رقــم ‪ 32262057‬وتاريــخ ‪1432/10/4‬ه وقــام البائــع بإعــادة ثمــن األرض‬\n‫وهمــش علــى الصــك بذلــك لــذا وحيــث ظهــر بطــان العقــد لــذا فــإن‬\n‫موكلــي يطلــب إلــزام املدعــى عليــه بإعــادة مــا ســلم لــه مائتــن وخمســن‬\n‫ألــف ريــال هــذه دعــواي وباســتجواب املدعــى عليــه قــال مــا ذكــره‬\n‫املدعــي مــن أنــي اســتلمت مائتــن وخمســن ألــف ريــال بخصــوص أرض‬\n‫يف (‪ )......‬مــن (‪ )......‬صحيــح إال أنــي ال أوافــق علــى رد املبلــغ ألنــه مت‬\n‫القبــض بنــاء علــى عمــل كمــا أن املبلــغ لــم يكــن ســعي بــل جعالــة وامنــا‬\n‫الســعي يدفــع عنــد افــراغ األرض مت لــذا فإنــي أطلــب رد دعــواه فســألته‬\n‫اجلعالــة كان علــى مــاذا فأجــاب علــى احضــار البائــع إلــى بيــت املدعــي‬\n‫شــخصي ًا واقناعــه بالتوقيــع علــى العقــد أ‪.‬ه ـ وبعرضــه علــى وكيــل‬\n‫املدعــي قــال مــا ذكــره غيــر صحيــح والصحيــح بأنــه كان ســعي ًا وبينتي‬\n‫علــى ذلــك نــص شــهادته يف صــك احلكــم حيــث أقــر بأنــه كان ســعي ًا‬\n‫أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه قــال الصحيــح بأنــه لــم يكــن ســعي ًا‬\n‫وامتســك مبــا ورد يف هــذا العقــد وأبــرز مذكــره جوابيــه جــاء فيــه مــا‬\n‫نصــه (أو ًال ‪ :‬أن املدعــي طلــب منــي البحــث عــن صاحــب األرض مــدار‬\n‫الدعــوى وان اجمعــه بالبايــع والوقــوف عليهــا ويف حالــة حتقيــق ذلــك‬\n‫وتوقيــع البائــع علــى عقــد البيــع يدفــع لــي جعالــة قدرهــا ‪ 250000‬ريــال‬\n‫مائتــان وخمســون ألــف ريــال وهــذه اجلعالــة وليــس ســعي وامنــا الســعي‬\n‫كمــا يتضــح لفضيلتكــم مــن أعقــد االتفــاق املرفــق تدفــع عنــد افــراغ‬\n‫األرض املذكــورة واحلــاق األطــوال واملســاحة اإلجماليــة عليهــا وأن املبلــغ‬\n‫املدعــى بــه ال يــرد وال يســترجع وحــرر عــن ذلــك عقــد اتفــاق مــؤرخ يف‬\n‫‪1426/11/11‬ه ـ موقــع عليــه مــن املدعــي وعليــه ختــم مؤسســته إال أن‬\n\n\n                                                                                     ‫‪212‬‬\n\f      ‫املدعــي ناقــض العقــد والعقــد‪ .‬ثانيـ ًا ‪ :‬القاعــدة الشــرعية (مــن ســعى الــى‬\n      ‫نقــض مــا مت مــن جهتــه فســعيه مــردود عليــه) فاملدعــي اتفــق معــي علــى‬\n      ‫أن املبلــغ املدعــى بــه هــو جعالــة ال تــرد وال تســترجع وحــرر عــن ذلــك عقــد‬\n      ‫اتفــاق ونــص عليــه يف البنــد الرابــع منــه‪ .‬ثالثــا ‪ :‬اننــي جمعتــه بصاحــب‬\n      ‫األرض وقــد مت التوقيــع علــى عقــد البيــع بتاريــخ ‪1426/11/11‬ه ـ بــن‬\n      ‫املدعــي وبــن البائــع واصبــح املبلــغ املدعــى بــه جعالــة حتققــت شــروطها‬\n      ‫وصيغتهــا الشــرعية وال يحــق للمدعــي املطالبــة بهــا شــرع ًا ‪ .‬رابعـ ًا ‪ :‬البينة‬\n      ‫حجــة متعديــة واإلقــرار حجــة قاصــرة واإلقــرار شــرع ًا أقــوى يف االثبــات‬\n      ‫مــن الشــهادة الن الشــهادة اخبــار عــن حــس أمــا اإلقــرار فهــو انشــاء‬\n      ‫وكــون املدعــي أقــر مبوجــب إقــرار خطــي بــأن هــذا املبلــغ املدعــى بــه‬\n      ‫هــو جعالــة غيــر مســترد وغيــر مســترجع وأن الســعي لــم يتــم دفعــه الن لــم‬\n      ‫يتــم اكمــال البيــع حســب االتفــاق املبــرم واحملــرر بــن املدعــي والبائــع‬\n      ‫وكذلــك عقــد االتفــاق الــذي بينــه وبــن املدعــي‪ .‬خامس ـ ًا ‪ :‬ملــا كان‬\n      ‫اإلقــرار حجــة قاصــرة علــى املقــر وأن القاعــدة الشــرعية التــي تنــص‬\n      ‫علــى أن العقــد شــريعة املتعاقديــن اعمــا ًال لقولــه تعالــى (يــا أيهــا الذيــن‬\n      ‫آمنــوا أوفــوا بالعقــود) ولعمــوم قــول النبــي صلــى اهلل عليــه وســلم‬\n      ‫«املؤمنــون علــى شــروطهم»وأن الثابــت بينــي وبــن املدعــي العقــد املبــرم‬\n      ‫بيننــا واملشــروط فيــه بــأن املبلــغ املدعــى بــه ال يــرد وال يســترجع ألنــه‬\n      ‫جعالــة إلحضــار البائــع وجمعــه مــع املدعــي واحضــار العقــود واملســتندات‬\n      ‫والتفــاوض مــع البائــع لتســهيل البيــع للمدعــي علــى أن يتــم دفــع الســعي‬\n      ‫بعــد اإلفــراغ ولكــن املدعــي خالــف قــول اهلل تعالــى [وليملــل الــذي عليــه‬\n      ‫احلــق وليتــق اهلل ربــه وال يبخــس منــه شــيئا]‪ .‬سادسـ ًا ‪ :‬ان املدعــي تناقــض‬\n      ‫يف دعــواه تناقض ـ ًا يبطلهــا وقاصــد ًا مــن ذلــك االضــرار والكيــد بــي‬\n\n\n‫‪213‬‬\n\f‫وذلــك ألنــه طلبنــي يف الشــهادة ضــد البائــع ولكنــي شــهدت احلقيقــة‬\n‫والواقــع وكانــت هــذه الشــهادة ال تلــق قبولــه ‪ .‬فضيلــة الشــيخ (‪)...‬‬\n‫حفظــه اهلل أن الدعــوى واضحــة فهــي دعــوى كيديــة فكيــف للمدعــي‬\n‫أن يســلمني املبلــغ املذكــور جعالــة إلحضــار البائــع ولقائــه بــه ووقوفــه‬\n‫علــى املوقــع وبــذل مجهــود شــاق حتــى وقــع علــى عقــد البيــع وقــد وافــق‬\n‫ومبحــض إرادتــه أن املبلــغ املدعــى بــه ليــس ســعي ًا وال جــزء مــن الســعي‬\n‫ولكنــه جعالــة علــى عمــل محــدد إذا مت هــذا العمــل واالتفــاق مبوجــب‬\n‫إقــرار موثــق بعقــد وأصبحــت اجلعالــة مســتحقة وملزمــة‪ .‬اتفــق القائلــون‬\n‫باجلعالــة علــى أن عقــد اجلعالــة بعــد متــام العمــل يصبــح الزمــا ألنــه ال أثــر‬\n‫يترتــب علــى رجــوع اجلاعــل عــن العقــد أو تــرك العامــل العمــل حينئــذ ألن‬\n‫اجلعــل قــد لــزم واســتقر علــى اجلاعــل وحيــث أن مــا مت االتفــاق عليــه مــن‬\n‫األعمــال املتعاقــد عليهــا يف عقــد اجلعالــة فإنــه يلــزم اجلعالــة بعــد متــام‬\n‫العمــل لــذا فأننــي اطلــب مــن فضيلتكــم احلكــم بصــرف النظــر عــن‬\n‫دعــوى املدعــي واخــاء ســبيلي مــن الدعــوى) وأضــاف بأنــه متمســك يف‬\n‫الفقــرة الرابعــة بــأن املبلــغ ال يــرد وال يســترجع وأن أجــرة الســعي يف‬\n‫الفقــرة الرابعــة «أ‪.‬ه ـ ثــم حضــر وكيــل املدعــي واملدعــى عليــه أصالــة‬\n‫وقــد جــرى اإلطــاع علــى الوثيقــة املؤرخــة يف ‪1426/11/11‬ه ـ ونصهــا‬\n‫(احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪،،،‬‬\n‫أنه يف يوم االثنني ‪ 11‬ذو القعدة ‪1426 ،‬هـ املوافق ‪12‬ديسمبر ‪2005،‬م‬\n‫بعــون اهلل وتوفيقــه قــد اتفــق كل مــن ‪ -:‬الطــرف األول ‪ )......( -:‬حامــل‬\n‫حفيظــة رقــم (‪ )......‬تاريــخ ‪1402/11/17‬ه ـ إصــدار مكــة املكرمــة ‪.‬‬\n‫الطرف الثاني ‪ )......( -:‬حامل حفيظة رقم (‪ )......‬بتاريخ ‪1392/11/1‬هـ‬\n‫إصــدار مكــة املكرمــة ‪ .‬متهيــد حيــث أن الطــرف األول ســعى وأحضــر‬\n\n\n                                                                                          ‫‪214‬‬\n\f      ‫األرض الواقعــة يف طريــق (‪ )......‬اململوكــة بالصــك رقــم (‪ )......‬والصــك‬\n      ‫رقــم (‪ )......‬واملســجلة يف محكمــة الليــث برقــم ‪ 58‬و‪59‬بتاريــخ ‪1347‬ه ـ‬\n      ‫البالــغ مســاحتها (‪ )321000000‬متــر مربــع‪( ،‬فقــط ثالثمائــة وواحــد‬\n      ‫وعشــرين مليــون متــر مربــع تقريبــا) عليــه فقــد إتفــق الطرفــان علــى مــا‬\n      ‫يلــي ‪ -:‬أو ًال يعتبــر التمهيــد جــزء مــن العقــد ‪ .‬ثانيـ ًا ‪ :‬يلتــزم الطــرف الثانــي‬\n      ‫بدفــع مبلــغ وقــدره (‪ )250.000‬ريــال ‪ ،‬فقــد مائتــان وخمســون ألــف‬\n      ‫ريــال عنــد توقيــع عقــد األرض املذكــورة أعــاه ‪.‬ثالث ـاً‪ :‬يلتــزم الطــرف‬\n      ‫الثانــي بدفــع مبلــغ وقــدره (‪)20000000‬ريــال‪ ،‬فقــط عشــرون مليــون‬\n      ‫ريــال ســعودي عنــد إفــراغ األرض املذكــورة أعــاه وإحلــاق األطــوال‬\n      ‫واملســاحة اإلجماليــة عليهــا‪ .‬رابع ـ ًا ‪ :‬املبلــغ املدفــوع للســعاة عنــد توقيــع‬\n      ‫العقــد ال يــرد وال يســترجع ‪ .‬طــرف أول (‪ )......‬توقيعــه‪ ،‬طــرف ثانــي‬\n      ‫(‪ )......‬توقيعــه ‪ ،‬ختــم مؤسســة (‪ )......‬أ‪.‬ه ـ وبعرضهــا علــى وكيل املدعي‬\n      ‫قــال إن موكلــي يقــر بــأن هــذه الوثيقــة صحيحــة ومنطوقهــا نــص صريح‬\n      ‫يف أن املبلــغ املســلم كان مقابــل ســعي أمــا مــا ورد يف الفقــرة الرابعــة‬\n      ‫فموكلــي يطلــب عــدم االلتفــات لهــا لكونــه غــار ًا حيــث كان يعلــم أن‬\n      ‫علــى األرض ايقافـ ًا ولــم يخبــر بذلــك موكلــي أ‪.‬هـ وبعرضــه على املدعى‬\n      ‫عليــه قــال مــا ذكــره بأنــي كنــت أعلــم بحــال األرض وأن التصــرف‬\n      ‫فيهــا موقــوف غيــر صحيــح أ‪.‬ه ـ وبعرضــه علــى املدعــي قــال الصحيــح مــا‬\n      ‫ادعيــت بــه مــن أنــه يعلــم ولــدي البينــة أ‪.‬ه ـ وأبــرز صــورة الصــك الصــادر‬\n      ‫مــن هــذه احملكمــة برقــم ‪ 5/200/134‬وتاريــخ ‪1431/7/30‬ه ـ‬\n      ‫بخصــوص دعــوى موكلــه ضــد البائــع وقــد جــاء يف شــهادته مــا نصــه‬\n      ‫(‪ )......‬بالســجل املدنــي رقــم (‪ )......‬وطلــب ســماع مــا لديــه مــن شــهادة‬\n      ‫فأذنــت بذلــك وشــهد قائــا أشــهد بــاهلل العظيــم أنــي كنــت الوســيط‬\n\n\n‫‪215‬‬\n\f‫بــن (‪ )......‬و(‪ )......‬يف بيــع األرض الواقعــة بالليــث وقــد إجتمعنــا يف منــزل‬\n‫(‪ )......‬يف مســاء ‪1426/11/11‬ه ـ وقــد جــرى التفــاوض علــى البيــع‬\n‫واتفقــا علــى بيعهــا مبائــة مليــون ريــال واختلفــا علــى الدفعــة األولــى‬\n‫فــكان (‪ )......‬يطلــب املزيــد فتراضيــا علــى أن تكــون الدفعــة األولــى‬\n‫حســبما هــو مــدون يف العقــد احملــرر يف ذلــك اليــوم مليونــن وســتمائة أو‬\n‫ســبعمائة ألــف ال أذكــر حتديــدا ولكنــه مقــارب لهــذا املبلــغ وتكــون‬\n‫غيــر مســترجعة بحــال مــن األحــوال حتــى ولــو لــم يتمكــن (‪ )......‬مــن‬\n‫اســتخراج صــك عليهــا أي تكــون مــن زكاة مالــه وقــام (‪ )......‬وبنــاء‬\n‫علــى هــذا االتفــاق باســتالم مبلــغ مبوجــب شــيكني وجــرى التوقيــع علــى‬\n‫العقــد األول وبعــد مضــي فتــرة اتصــل بــي (‪ )......‬وطلــب منــي إقنــاع (‪)......‬‬\n‫بتوقيــع عقــود أخــرى حيــث طلــب مكتــب (‪ )......‬تغييــر صيغــة العقــد‬\n‫صوريــا لتســهيل األمــر حســب قولــه وكان (‪ )......‬يرفــض ذلــك فجــرى‬\n‫إقناعــه مــن قبلــي بعدمــا وعدتــه بــأن آتيــه بورقــة مضــادة مــن قبــل (‪)......‬‬\n‫للتحقــق مــن جعلهــا صوريــة هــذا مــا حصــل فقــد حضــر لــدي (‪ )......‬أحــد‬\n‫املوظفــن لديــه وســلم لــي عقديــن بثمانــن مليون ـ ًا كل عقــد بأربعــن‬\n‫وقمنــا بإيصالهــا إلــى (‪ )......‬ووقــع عليهمــا وبعــد توقيعــي عليهــا أعدناهــا‬\n‫إلــى (‪ )......‬بعــد مــا صــاغ لــي (‪ )......‬الورقــة امللغيــة لهذيــن العقديــن‬\n‫الصوريــة وقــام مكتــب (‪ )......‬بطباعتهــا وضمهــا ثــم عرضهــا علــى‬\n‫املدعــي فقــام بالتوقيــع عليهــا وأعدتهــا إلــى (‪ )......‬هــذا مــا لــدي وبــه‬\n‫أشــهد‪ .‬فســألت الشــاهد هــل قــام البائــع بإخطــاره عمــا حصــل لــأرض‬\n‫ســابق ًا مــن أوامــر ونحوهــا؟ قــال‪ :‬نعــم لقــد أخبــره بــأن أحــد أفــراد‬\n‫األســرة املالكــة حــاول أن يســتخرج صــكا عليهــا إال إنــه لــم يتمكــن‪،‬‬\n‫أخبــره بذلــك قبــل التوقيــع علــى العقــد األول عندمــا كنــا يف اســتراحة‬\n\n\n                                                                                        ‫‪216‬‬\n\f      ‫(‪،)......‬كما أخبره بوجود اعتداءات عليها‪ ،‬واستعد (‪ )....‬بتعويضهم‪،‬‬\n      ‫وطلــب مــن البائــع أن يتنــازل عــن جــزء مــن األرض مقابــل مــا ســيتم‬\n      ‫تعويــض املعتديــن عليهــا ‪.‬أ‪.‬ه ـ فجــرى عــرض صــورة العقــد املبــرز مــن قبل‬\n      ‫وكيــل املدعــي علــى الشــاهد فقــرر بــأن هــذا العقــد هــو أحــد العقــود‬\n      ‫الصوريــة ال احلقيقيــة والعقــد احلقيقــي املعتمــد هــو العقــد األول مبائــة‬\n      ‫مليــون )أ‪.‬ه ـ وبعرضــه عليــه قــال مــا جــاء يف الشــهادة صحيــح وقــد علمــت‬\n      ‫بحالهــا الحق ـ ًا ووقــت اســتالمي للمبلــغ لــم أكــن أعلــم أ‪.‬ه ـ وبعرضــه‬\n      ‫علــى وكيــل املدعــي قــال الصحيــح مــا ادعيــت بــه أ‪.‬ه ـ ويف يــوم األحــد‬\n      ‫‪1434/4/7‬ه ـ فتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر‬\n      ‫وكيــل املدعــي ولــم يحضــر املدعــى عليــه ولــم يتقــدم بعــذر مقبــول حتــى‬\n      ‫اآلن عليــه وبعــد قفــل بــاب املرافعــة وتأمــل الدعــوى واإلجابــة وإلقــرار‬\n      ‫املدعــى عليــه بأنــه اســتلم مــن املدعــي مئتــن وخمســن ألــف ريــال مقابــل‬\n      ‫جعالــة شــرط اســتحقاقها احضــار البائــع والتوقيــع علــى عقــد شــراء‬\n      ‫األرض جــاء ذلــك نصــا يف مذكرتــه املدونــة يف اجللســة األولــى بقولــه «‬\n      ‫ويف حالــة حتقــق ذلــك وتوقيــع البائــع علــى عقــد البيــع يدفــع لــي جعالــة‬\n      ‫قدرهــا مئتــن وخمســن ألــف ريــال « عليــه وألن مجــرد احضــار البائــع‬\n      ‫أمــر تبعــي املقصــود منــه غايتــه وهــو « التوقيــع علــى العقــد « فيســتحق‬\n      ‫املدعــى عليــه اجلعــل مبجــرده ولــو لــم يتحقــق اللقــاء بينهمــا ‪ ،‬عليــه وملــا‬\n      ‫ثبــت باحلكــم الســابق بطــان هــذا البيــع الختــال شــرط مــن شــروط‬\n      ‫صحتــه وثبــت شــرع ًا عــدم انعقــاده ألجلــه فــإن ذلــك يــؤول لبطــان‬\n      ‫العــوض «اجلعــل» الــذي علــق اســتحقاقه عليــه علــى الصحيــح مــن كالم‬\n      ‫الفقهــاء قــال البهوتــي ‪ -‬رحمــه اهلل‪ -‬يف كشــاف القناع يف باب الصداق‬\n                    ‫كا َنـ ْـت ا ْل َع ِط َّيـ ُة ِل َغ ْيـ ِـر ا ْل َعاقِ َد ْيـ ِـن ِب َسـ َـب ِب ا ْل َع ْقــدِ َ‬\n      ‫ك ُأ ْجـ َـر ِة‬                                                                                              ‫مــا نصــه ‪َ ( »:‬و ِإنْ َ‬\n\n‫‪217‬‬\n\f‫ك َّيــالِ َوا ْلـ َـو َّزانِ ( قَ ــالَ ا ْبـ ُـن َعقِ يـ ٍـل ) ِف‬                          ‫ك ُأ ْجـ َـر ِة ا ْل َ‬  ‫الـ َّـد َّللِ َون َْح ِو َهــا) َ‬\n   ‫اض) مِ ــنْ‬  ‫ـف َع َلــى َتـ َـر ٍ‬          ‫مــا َيقِ ـ ُ‬  ‫ـات ( إنْ ُف ِسـ َـخ َب ْيـ ٌـع ِب ِإقَ ا َل ـ ٍة َون َْح ِو َهــا ِ َّ‬        ‫ال َّن َظ ِر َّيـ ِ‬\n‫ا ْل َعاقِ َد ْيـ ِـن ( َلـ ْـم َيـ ُـر َّد ُه ) َأ ْي َلـ ْـم َيـ ُـر َّد الـ َّـد َّللُ َمــا َأ َخـ َـذ ُه ( َو ِإ َّل ) َأ ْي َو ِإنْ َلـ ْـم‬\n‫(ر َّد ُه) َأ ْي َر َّد‬   ‫كا ْل َف ْسـ ِـخ ل َِع ْيـ ٍـب َون َْح ـ ِو ِه َ‬               ‫اضيه َِمــا َ‬       ‫ـف ا ْل َف ْسـ ُـخ َع َلــى َت َر ِ‬       ‫َيقِ ـ ْ‬\n‫وم َو َع َدمِ ـ ِه «أ‪.‬ه ـ وهــذا‬                                                                                 ‫الـ َّـد َّللُ َمــا َأ َخـ َـذ ُه ِ َل َّن ْ َ‬\n                                                 ‫ال ِبيـ َـع َوقَ ـ َـع ُم َتـ َـر ِّد ًدا َب ْي َنــا ل ُّلـ ُـز ِ‬\n‫النــص الفقهــي العــام يبــن لنــا أنــه ال أثــر ملــا دفــع بــه املدعــى عليــه مــن أنــه‬\n‫اســتحق العــوض مبوجــب عقــد اجلعالــة ال ســعي حيــث نــص علــى جــواز‬\n‫مطالبــة الدافــع بــرد العــوض املســلم لغيــر املتعاقديــن متــى كان بســبب‬\n‫العقــد كأجــرة الــدالل والكيــال والــوزان وكان الفســخ مــن غيــر‬\n‫تــراض مــن الطرفــن جميعــا كاإلقالــة وهــذا الشــرطان متحققــان يف‬\n‫هــذه الواقعــة محــل النظــر ‪ ،‬فضــا عــن أن « اجلعالــة والســعي والداللــة»‬\n‫ألفــاظ ألصــل شــرعي واحــد هــو «اجلعالــة « فــإن اختلفــت األســماء‬\n‫فاملســمى واحــد ‪ ،‬وأمــا الدفــع اآلخــر الــذي متســك بــه املدعــى عليــه وهــو‬\n‫إقــرار املدعــي بــأن املبلــغ املســلم ال يــرد وال يســترجع فاألظهــر بأنــه‬\n‫شــرط غيــر صحيــح ألن إســقاط احلــق قبــل ســببه لغــو ال أثــر لــه وهــو ال‬\n‫يســتحق اجلعــل بعــد تســليمه للعامــل « املدعــى عليــه « إال بعــد ثبــوت‬\n‫بطــان البيــع ونظيــره مــن الشــروط الفاســدة وأقربــه إليــه البيــع بشــرط‬\n‫البــراءة مــن العيــب فــإن الصحيــح مــن كالم أهــل العلــم أن الشــرط‬\n‫باطــل ال أثــر إلشــتراطه يف اســقاط حــق خيــار العيــب للمشــتري ‪ ،‬قــال‬\n‫يف مطالــب أولــي النهــى يف بــاب الشــروط يف البيــع ‪َ »:‬ف ْصــلٌ ‪َ ( :‬و َمــنْ َبــا َع‬\n‫اعـ ُه ؛ َلـ ْـم َي ْبـ َـر ْأ ‪َ ( ،‬أ ْو )‬        ‫يمــا َب َ‬    ‫كلِّ َع ْيـ ٍـب ) فِ َ‬           ‫) َشـ ْيئًا ( ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة مِ ــنْ ُ‬\n‫ال ِبيـ ِـع ( َلـ ْـم َي ْبـ َـر ْأ َبا ِئـ ٌـع‬\n                                             ‫ان ِف ْ َ‬      ‫ك َ‬    ‫كـ َـذا ) ‪ ،‬إنْ َ‬                 ‫ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ( مِ ــنْ َع ْيـ ِـب َ‬\n‫) ِب َذ ِلـ َـك ‪َ ،‬ولِ ُْشـ َت ٍر ا ْل َف ْسـ ُـخ ِب َع ْيـ ٍـب َلـ ْـم ُي ْع َلـ ْـم َحا َلـ َة َع ْقــدٍ ؛ لِ َــا َر َوى َأ ْح َمـ ُـد َأ َّن‬\n\n\n                                                                                                                                                                   ‫‪218‬‬\n\f      ‫ا ْبـ َـن ُع َمـ َـر َبــا َع َز ْيـ َـد ْبـ َـن ثَا ِبـ ٍـت َع ْبـ ًـدا ِب َشـ ْـر ِط ا ْل َبـ َـر َاء ِة ِبث ََمانِ ِا َئ ـ ِة د ِْر َهـ ٍـم ‪،‬‬\n      ‫‪،‬فـ َأ َرا َد َر َّد ُه َع َلــى ا ْبـ ِـن ُع َمـ َـر َف َلـ ْـم َي ْق َب ْلـ ُه ‪َ ،‬ف َت َر َاف َعــا‬\n                                                                                                          ‫ـاب َز ْيـ ٌـد ِبـ ِه َع ْي ًبــا َ‬‫َف َأ َصـ َ‬\n      ‫ـف َأ َّنـ َـك َلـ ْـم َت ْع َلـ ْـم ِب َهـ َـذا ا ْل َع ْيـ ِـب‬                                  ‫ـان ‪َ ،‬ف َقــالَ ُع ْث َمـ ُ‬\n                                                                           ‫ـان ِل ْبـ ِـن ُع َمـ َـر ‪ْ َ :‬‬\n                                                                     ‫ت ِلـ ُ‬                                                            ‫إ َلــى ُع ْث َمـ َ‬\n      ‫ـف د ِْر َهـ ٍـم َ‪.‬و َهــذِ ِه قَ ِض َّي ـ ٌة‬      ‫اع ـ ُه ا ْبـ ُـن ُع َمـ َـر ِب َأ ْلـ ِ‬\n                                                                                               ‫؟ قَ ــالَ ‪َ :‬ل ‪َ ،‬فـ َـر َّد ُه َع َل ْي ـ ِه ‪َ ،‬ف َب َ‬\n      ‫اع»‪.‬وهــذا علــى فــرض أن‬                                  ‫ال ْج َم ِ‬‫ك ِْ‬ ‫كا َنـ ْـت َ‬      ‫كـ ْـر‪َ ،‬ف َ‬                                         ‫ْ‬\n                                                                                                                    ‫اش ـ َت َه َر ْت ‪َ ،‬و َلـ ْـم ُت ْن َ‬\n      ‫العبــارة تشــمل الواقعــة محــل النظــر وإال فإنــه يــرد احتمــال قــوي بــأن‬\n      ‫مرادهمــا مــا لــو عجــز املشــتري عــن إحلــاق الــذرع علــى الصــك فإنــه ال‬\n      ‫يحــق املطالبــة باســترداد اجلعــل « العــوض « وهــذا ظاهــر إذ ال يســتحق‬\n      ‫حينهــا املطالبــة بــرده ألنــه ال يلــزم مــن عــدم قدرتــه علــى ذلــك بطــان بيــع‬\n      ‫العــن والشــرط جــاء ل ــتأكيد هــذا األمــر وهــذا االحتمــال الــوارد علــى‬\n      ‫اللفــظ يضعــف أيضــا األخــذ بإطالقــه مــع مــا تقــدم ‪ ،‬عليــه وملجمــوع مــا‬\n      ‫تقــدم فقــد حكمــت علــى املدعــى عليــه (‪ )......‬بدفــع مائتــن وخمســن‬\n      ‫ألــف ريــال للمدعــي (‪ )......‬عليــه وألن تخلفــه بعــد تبلغــه لشــخصه مبوعــد‬\n      ‫اجللســة وســماع جوابــه فيعــد احلكــم حضوريــا وجــرى النطــق بــه يف يــوم‬\n      ‫‪1434/4/7‬ه ـ وأمــرت بإخــراج صــك مبوجبــه وبعــث صورتــه للمدعــى‬\n      ‫عليــه لــه مــن بعــد اســتالمه لهــا ثالثــون يومــا يقــدم خاللهــا الئحتــه‬\n      ‫اإلعتراضيــة فــإن لــم يفعــل يســقط حقــه يف اإلعتــراض ويكتســب‬\n      ‫احلكــم الصفــة القطعيــة وأقفلــت اجللســة الســاعة احلادية عشــرة ‪ .‬وصلى‬\n                                               ‫اهلل وسلم على نبينا محمد وعلى آله وصحبه أجمعني‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )......‬القاضــي يف احملكمــة العامــة‬\n      ‫مبكــة املكرمــة ففــي يــوم األحــد ‪1434/09/06‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة الواحــدة ظهــرا بعدمــا وردتنــا املعاملــة مــن محكمــة اإلســتئناف‬\n      ‫بالقــرار رقــم ‪ 34286360‬وتاريــخ ‪1434/08/02‬ه ـ ونــص احلاجــة‬\n\n\n‫‪219‬‬\n\f‫منــه (وبدراســة احلكــم وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر‬\n‫باألكثريــة املوافقــة علــى احلكــم) قاضــي اســتئناف (‪ )......‬ختمــه‬\n‫وتوقيعــه ‪ ،‬قاضــي اســتئناف (‪ )......‬ختمــه وتوقيعــه ولــه وجهــة نظــر‪،‬‬\n‫رئيــس الدائــرة (‪)......‬ختمــه وتوقيعــه ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                         ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/9/6‬ه ـ‬\n‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n‫مــن فضيلــة الشــيخ (‪ )......‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫املســجل بعــدد ‪ 34193570‬وتاريــخ ‪ 1434/4/21‬املتضمــن دعــوى (‪)......‬‬\n‫ضــد (‪ )......‬احملكــوم في ــه مبــا دون باطــن الصــك‪ ،‬وبدراســة احلكــم‬\n‫وص ــورة ضبط ــه والئحتــه االعتراضيــة تق ــرر باألكثريــة املوافق ــة عل ــى‬\n‫احلكــم‪ .‬وبــاهلل التوفيــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه‬\n                                                              ‫وصحب ــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪220‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":209,"source_page_end":220,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cdf3970588d4e05a3223b8c4c9de041e46ce3b6309ad4ddd1263a06d519cb259","normalized_text_hash":"d7e00379204599748ef1dff08964c1f8da3d678564600f743513e99da9eb1834","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p209-34193570"},{"id":"48497706-45ee-50ec-a1c4-4930a730889f","document_type":"judgment","category":"judicial","subcategory":"general","title":"عمالة -مطالبة برسوم استقدام خادمة -مت ارجاعها ملكتب اخلدمات -حضور املدعى عليه -جلنة صلح -الصلح على مبلغ معن لم يلتزم به املدعى عليه عدم حضور املدعى عليه جلسة احلكم رغم تبليغه باملوعد حلف املدعي على املبلغ الذي دفعه األدلة الشرعية دلت على أنه لو لم يحكم على املستتر جلعل ال لتضييع احلقوق احلكم على املدعى عليه بدفع االستتار سبي املبلغ للمدعي -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى","document_number":"34168504","case_number":"33136578","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"عمالة -مطالبة برسوم استقدام خادمة -مت ارجاعها ملكتب اخلدمات -حضور املدعى عليه -جلنة صلح -الصلح على مبلغ معن لم يلتزم به املدعى عليه عدم حضور املدعى عليه جلسة احلكم رغم تبليغه باملوعد حلف املدعي على املبلغ الذي دفعه األدلة الشرعية دلت على أنه لو لم يحكم على املستتر جلعل ال لتضييع احلقوق احلكم على املدعى عليه بدفع االستتار سبي املبلغ للمدعي -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34168504 :‬تاريخه ‪1434/3/22 :‬هـ‬\n                        ‫رقم الدعوى ‪33136578 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34289497‬تاريخه‪1434/8/7 :‬هـ‬\n\n\n      ‫عمالــة ‪ -‬مطالبــة برســوم اســتقدام خادمــة ‪ -‬مت ارجاعهــا ملكتــب‬\n      ‫اخلدمــات ‪ -‬حضــور املدعــى عليــه ‪ -‬جلنــة صلــح ‪ -‬الصلــح علــى مبلــغ‬\n      ‫معــن لــم يلتــزم بــه املدعــى عليــه ـ عــدم حضــور املدعــى عليــه جلســة‬\n      ‫احلكــم رغــم تبليغــه باملوعــد ـ حلــف املدعــي علــى املبلــغ الــذي دفعــه‬\n      ‫ـ األدلــة الشــرعية دلــت علــى أنــه لــو لــم يحكــم علــى املســتتر جلعــل‬\n      ‫ال لتضييــع احلقــوق ـ احلكــم علــى املدعــى عليــه بدفــع‬  ‫االســتتار ســبي ً‬\n      ‫املبلــغ للمدعــي ‪ -‬رفــع احلكــم حملكمــة االســتئناف لتعــذر تبليــغ املدعــى‬\n                                                                             ‫عليــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬ما روى أبو موسى األشعري ـ رضي اهلل عنه ـ قال ‪ ( :‬كان اخلصمان‬\n      ‫إذا اختصمــا إلــى رســول اهلل صلــى اهلل عليــه وســلم فاتعــدا املوعــد فوفــى‬\n      ‫أحداهمــا ولــم يــوف اآلخــر قضــى للــذى وفــى ) أخرجــه الطبرانــي يف‬\n                                                                              ‫األوســط ‪.‬‬\n      ‫ال لتضييــع احلقوق‬    ‫‪ .2‬لــو لــم يحكــم علــى املســتتر جلعــل االســتتار ســبي ً‬\n                                                        ‫( الشــرح الكبير ‪. ) 508/28‬‬\n      ‫‪ .3‬املــادة (‪ )55‬و (‪ )103‬مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n                                                                         ‫التنفيذيــة ‪.‬‬\n\n\n\n‫‪221‬‬\n\f‫حضــر املدعــي ولــم يحضــر املدعــى عليــه رغــم إبالغــه عــدة مــرات‬\n‫ـ ورغــم حضــوره جلســة جلنــة الصلــح باحملكمــة ـ بنــاء علــى املــادة‬\n‫(‪ )55‬مــن نظــام املرافعــات قــرر ناظــر الدعــوى ســماع الدعــوى ـ ادعــى‬\n‫املدعــي علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم بأنــه قــد ســلمه‬\n‫مبلــغ وقــدره ســبعة آالف وخمســمائة ريــال قيمــة رســوم عاملــة منزليــة‬\n‫أحضرهــا عــن طريــق مكتــب املدعــى عليــه لالســتقدام وبعــد قدومهــا‬\n‫رفضــت العمــل فقــام بإعادتهــا للمكتــب خــال فتــرة التجربــة وتســلمها‬\n‫املدعــى عليــه ووعــده بإعــادة املبلــغ الــذي دفعــه إال أنــه قــد ماطــل ولــم يقم‬\n‫بإنهــاء إجــراءات اخلادمــة حيــث إنهــا مــا زالــت يف كفالــة املدعــي وطلــب‬\n‫إلــزام املدعــى عليــه بإعــادة املبلــغ الــذي ســلمه لــه وقــدره ســبعة آالف‬\n‫وخمســمائة ريــال ‪ - 7500‬مت ســؤال املدعــي البينــة علــى دعــواه فأشــار‬\n‫إلــى أن املدعــى عليــه قــد حضــر لــدى جلنــة الصلــح باحملكمــة واصطلحــا‬\n‫أن يدفــع املدعــى عليــه للمدعــي خمســة آالف ريــال يف ‪1433/5/29‬ه ـ‬\n‫ويتنــازل املدعــي عــن ألفــن وخمســمائة ريال إال أن املدعــى عليه لم يلتزم‬\n‫بالصلــح ـ جــرى االطــاع علــى األوراق فوجــد بهــا خطــاب جلنــة الصلــح‬\n‫املتضمــن أنــه حضــر املدعــي واملدعــى عليــه واصطلحــا أن يدفــع املدعــى‬\n‫عليــه للمدعــي مبلغـ ًا وقــدره خمســة آالف ريــال يف ‪1435/5/29‬ه ـ ويف‬\n‫حــال تأخــره عــن دفــع املبلــغ يف املوعــد احملــدد فإنــه يكون ملزم ًا بســداد‬\n‫كامــل املدعــى بــه وقــدره ســبعة آالف وخمســمائة ريــال ويكــون هــذا‬\n‫الصلــح منهــي للنــزاع بــن الطرفــن ‪ -‬حلــف املدعــي اليمــن ‪ -‬بنــاء علــى‬\n‫مــا ورد يف خطــاب جلنــة الصلــح وحللــف املدعــي اليمــن ‪ -‬وألن املدعــى‬\n\n                                                                                          ‫‪222‬‬\n\f      ‫عليــه لــم يــف مبــا وعــد بــه وألن الرســول صلــى اهلل عليــه وســلم قضــى‬\n      ‫للــذي وفــى علــى مــن لــم يــف ‪ -‬وبنــاء علــى املــواد (‪ )55‬و (‪ )103‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ‪ -‬صــدر احلكــم بــأن يدفــع املدعــى عليــه للمدعــي‬\n      ‫املبلــغ وقــدره ســبعة آالف وخمســمائة ريــال ‪ -‬مت بعــث صــورة مــن احلكــم‬\n      ‫للمدعــى عليــه لتبليغــه وإفهامــه بتعليمــات االســتئناف ‪ -‬صــدق احلكــم‬\n                                                        ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n      ‫ـاء علــى املعاملــة احملالــة‬\n                                 ‫أنــا ‪........‬القاضــي باحملكمــة اجلزئيــة بجــدة بنـ ً‬\n      ‫لنــا مــن فضيلــة رئيــس هــذه احملكمــة املســاعد برقــم ‪33357873‬‬\n      ‫يف ‪1433/2/22‬ه ـ واملتعلقــة بدعــوى ‪........‬ضــد ‪........‬ومبوجبهــا ففــي‬\n      ‫هــذا اليــوم االثنــن املوافــق ‪1434/2/18‬ه ـ الســاعة التاســعة صباحــا‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي ‪........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪........‬ولــم يحضــر املدعــى عليــه يف هــذه اجللســة‬\n      ‫أصالــة وال وكالــة رغــم طلبــه عــدة مــرات مبوجــب اإلبــاغ رقــم ‪........‬يف‬\n      ‫‪1433/5/12‬ه ـ و اإلبــاغ رقــم ‪........‬يف ‪1433/7/2‬ه ـ و ورغــم حضــوره‬\n      ‫جللســة جلنــة الصلــح بهــذه احملكمة بتاريخ االثنــن ‪1433/5/17‬هـ وبناء‬\n      ‫علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولوائحهــا‬\n      ‫التنفيذيــة فقــد قــررت ســماع الدعــوى وأذنــت للمدعــي بتحريــر دعــواه‬\n      ‫فادعــى علــى خصمــه الغائــب عــن املجلــس الشــرعي قائــا إن لــي يف ذمــة‬\n      ‫املدعــى عليــه مبلغــا وقــدره ســبعة آالف وخمســمائة ريــال قيمــة رســوم‬\n      ‫عاملــة منزليــة احضرهــا املدعــى عليــه عــن طريــق مكتبــه مكتــب‬\n\n‫‪223‬‬\n\f‫‪........‬لالســتقدام إال أنهــا رفضــت العمــل لــدي وقمــت بإعادتهــا للمكتــب‬\n‫خــال فتــرة التجربــة وتســلمها املذكــور ووعدنــي بإعــادة املبلــغ إال انــه‬\n‫بعــد ذلــك ماطلنــي ولــم يقــم بإنهــاء إجــراءات خروج الشــغالة حيــث إنها ال‬\n‫تــزال علــى كفالتــي ولــم يعيــد لــي املبلــغ لــذا أطلــب إلزامــه بســداد املبلــغ‬\n‫وقــدره ســبعة آالف وخمســمائة ريــال أطالبــه بذلــك فجــرى ســؤاله هــل‬\n‫لديــك بينــة علــى دعــواك أجــاب قائــا نعــم لقــد حضــر املدعــى عليــه لــدى‬\n‫جلنــة الصلــح بهــذه احملكمــة بتاريــخ االثنــن ‪1433/5/17‬ه ـ واصطلحنا‬\n‫علــى أن يدفــع لــي مبلــغ خمســة آالف ريــال يف تاريــخ ‪1433/5/29‬ه ـ‬\n‫وأتنــازل لــه عــن ألفــن وخمســمائة ريــال إال انــه لــم يلتــزم بذلــك الصلــح‬\n‫فجــرى االطــاع علــى األوراق فوجــد بهــا خطــاب جلنــة الصلــح بهــذه‬\n‫احملكمــة برقــم ‪ 33357873‬يف ‪ 1434/5/17‬ه ـ واملتضمــن انــه حضــر‬\n‫لديهــم املدعــي واملدعــى عليــه واصطلحــا علــى ان يدفــع املدعــى عليــه‬\n‫للمدعــي مبلــغ خمســة االف ريــال يف تاريــخ ‪1433/5/29‬ه ـ ويف حــال‬\n‫تأخــره عــن دفــع املبلــغ يف املوعــد احملــدد فانــه يكــون ملزمــا بســداد‬\n‫كامــل املبلــغ املدعــى بــه وقــدره ســبعة االف وخمســمائة ريــال ويكــون‬\n‫هــذا الصلــح منهيــا جلميــع النزاعــات القائمــة بــن الطرفــن انتهــى فجــرى‬\n‫ســؤال املدعــي هــل حتلــف اليمــن علــى أن لــك يف ذمــة املدعــى عليه مبلغا‬\n‫وقــدره ســبعة آالف وخمســمائة ريــال فأجــاب قائــا نعــم أحلــف فجــرى‬\n‫وعظــه وتخويفــه مــن مغبــة اليمــن الكاذبــة وأنهــا تغمــس صاحبهــا يف‬\n‫نــار جهنــم فحلــف بــاهلل قائــا واهلل العظيــم الــذي ال الــه إال هــو عالــم‬\n‫الغيــب والشــهادة احلــي القيــوم بــأن لــي يف ذمــة املدعــى عليــه ‪ ........‬مبلغــا‬\n‫وقــدره ســبعة آالف وخمســمائة ريــال حالــة ولــم يســلمني منهــا شــيئا‬\n‫واهلل العظيــم انتهــى وعليــه فبنــاء علــى دعــوى املدعــي املرصــودة أعــاه‬\n\n\n                                                                                          ‫‪224‬‬\n\f      ‫وبنــاء علــى مــا ورد يف محضــر جلنــة الصلــح املشــار لــه بعاليــه وبنــاء علــى‬\n      ‫اليمــن التــي حلفهــا املدعــي باســتحقاقه مبلــغ ســبعة االف وخمســمائة‬\n      ‫ريــال يف ذمــة املدعــى عليــه وملــا رواه أبــو موســى األشــعري رضــي اهلل‬\n      ‫عنــه قــال ( كان اخلصمــان إذا اختصمــا إلــى رســول اهلل صلــى اهلل‬\n      ‫عليــه وســلم فاتعــد املوعــد فوفــى احدهمــا ولــم يــوف اآلخــر قضــى للــذي‬\n      ‫وفــى ) أخرجــه الطبرانــي يف األوســط وغيــره وألنــه لــو لــم يحكــم‬\n      ‫عليــه جلعــل االســتتار ســبيال لتضييــع احلقــوق كمــا ذكــر يف الشــرح‬\n      ‫الكبيــر‪ 508/28‬وغيــره وبنــاء علــى املــادة اخلامســة واخلمســن واملــادة‬\n      ‫الثالثــة بعــد املائــة مــن نظــام املرافعــات الشــرعية ولوائحهمــا التنفيذيــة‬\n      ‫فقــد حكمــت علــى املدعــى عليــه ‪ ........‬حضوريــا بــأن يدفــع للمدعــي‬\n      ‫‪ ........‬مبلغــا وقــدره ســبعة آالف وخمســمائة ريــال وبــه حكمــت وأمــرت‬\n      ‫بتنظيــم هــذا الصــك مبوجبــه وبعــث صــورة منــه للمدعــى عليــه لتبليغــه‬\n      ‫وإفهامــه بأنــه إذا لــم يتقــدم باعتراضــه خــال املــدة املقــررة نظامــا‬\n      ‫فســوف يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعيــة واهلل‬\n      ‫املوفــق وصلــى اهلل علــى ســيدنا محمــد وعلــى الــه وصحبــه وســلم حــرر‬\n                                                                     ‫يف ‪1434/2/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد وحيــث جــرى بعــث صــورة مــن احلكــم لتبليــغ‬\n      ‫املدعــى عليــه وردتنــا افــادة مديــر شــرطة محافظــة جــدة برقــم ‪........‬‬\n      ‫يف ‪1434/5/28‬ه ـ متضمنــة انــه لــم يتــم االســتدالل علــى املدعــى عليــه‬\n      ‫وجــرى االتصــال علــى االرقــام التــي زودهــم بهــا املدعــي ولــم يتــم الــرد‬\n      ‫‪.‬انتهــى ‪.‬وعليــه قــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n      ‫لتدقيــق احلكــم اســتنادا للمــادة اخلامســة واخلمســن مــن نظــام املرافعات‬\n      ‫الشــرعية والئحتهــا التنفيذيــة واهلل املوفــق وصلــى اهلل علــى ســيدنا‬\n\n\n‫‪225‬‬\n\f              ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/6/10‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد جــرى‬\n‫اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر مــن فضيلــة‬\n‫الشــيخ ‪........‬القاضــي باحملكمــة اجلزائيــة مبحافظــة جــدة برقــم‬\n‫‪ 34168504‬وتاريــخ ‪1434/3/22‬ه ـ املتضمــن دعــوى ‪........‬ضــد ‪........‬‬\n‫واحملكــوم فيــه مبــادون باطنــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫تقــرر باألكثريــة املوافقــة علــى احلكــم والغائــب علــى حجتــه إذا حضــر‬\n‫واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                                 ‫‪،.،.،.،.،‬‬\n\n\n\n\n                                                                                ‫‪226‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":221,"source_page_end":226,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a79db35299f96c525493704adc3c30279593d5295a1a47df54f5c858fa4b532d","normalized_text_hash":"7a4c24a5b47e102b20762460b2ff8ca9a3d519a796d780556c6e3a6477a7238b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p221-34168504"},{"id":"ad1db665-b09b-5344-b77b-1a3cfa318d42","document_type":"judgment","category":"judicial","subcategory":"general","title":"اتعاب -اعمال تعقيب -مطالبة بإعادة جزء من األجرة لعدم إجناز األجير للعمل -وجوب الوفاء بالعقود -االصل يف العقود و الشروط احلل -احلكم برد دعوى املدعى والزام املدعي بدفع اتعاب احملاماة ملوكل املدعى عليه .","document_number":"33204853","case_number":"19263","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/21","year":"1434","subject":"اتعاب -اعمال تعقيب -مطالبة بإعادة جزء من األجرة لعدم إجناز األجير للعمل -وجوب الوفاء بالعقود -االصل يف العقود و الشروط احلل -احلكم برد دعوى املدعى والزام املدعي بدفع اتعاب احملاماة ملوكل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33204853 :‬تاريخه‪1433/4/21 :‬هـ‬\n                            ‫رقم الدعوى‪19263 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3434009‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n      ‫اتعــاب‪ -‬اعمــال تعقيــب‪ -‬مطالبــة بإعــادة جــزء مــن األجــرة لعــدم إجنــاز‬\n      ‫األجيــر للعمــل‪ -‬وجــوب الوفــاء بالعقــود‪ -‬االصــل يف العقــود و الشــروط‬\n      ‫احلــل ‪ -‬احلكــم بــرد دعــوى املدعــى والــزام املدعــي بدفــع اتعــاب احملامــاة‬\n                                                               ‫ملــوكل املدعــى عليــه ‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قول اهلل تعالى‪(( :‬يا أيها الذين آمنوا أوفوا بالعقود))‪.‬‬\n                                               ‫‪ -2‬األصل يف العقود الصحة‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن موكلــه اتفــق مــع املدعــى عليــه علــى أن يقــوم‬\n      ‫الثانــي بأعمــال التعقيــب واملتابعــة يف إنهــاء موضوعــه املتعلــق بتالعــب‬\n      ‫أحــد املصــارف بحســاباته كمــا اتفــق معــه علــى أن يدفــع لــه املبلــغ‬\n      ‫املذكــور يف الدعــوى بشــيك ليبقــى ضمان ـ ًا لديــه بشــرط أال يصرفــه‬\n      ‫ا إال أن املدعــى عليــه قــام بصــرف الشــيك‬    ‫حتــى ينهــي املوضــوع كام ـ ً‬\n      ‫دون إنهــاء مــا اتفــق عليــه‪ ،‬لــذا طلــب إلزامــه بإعــادة مــا اســتلمه مــن‬\n      ‫موكلــه‪ -‬أقــر وكيــل املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع بــأن‬\n      ‫االتفاقيــة التــي بينهمــا تنــص علــى حــق موكلــه يف صــرف الشــيك كمــا‬\n      ‫دفــع بــأن املدعــي هــو مــن قــام بفســخ وكالــة موكلــه دون أن ُيبلغــه‬\n\n‫‪227‬‬\n\f‫بالفســخ أو ســببه ‪ -‬العقــد املبــرم بــن املتداعيــن يتضمــن أن الشــيك‬\n‫محــل الدعــوى حــق مــن حقــوق الطــرف الثانــي لــه احلــق يف صرفــه دون‬\n‫الرجــوع للطــرف األول كمــا يتضمــن أن الطــرف الثانــي يســتحق جميــع‬\n‫حقوقــه عنــد فســخ الطــرف األول لوكالتــه‪ -‬قضــت احملكمــة بــرد‬\n‫دعــوى املدعــي لعــدم اســتحقاقه ملــا يدعيــه ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n‫وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                       ‫احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ ....‬وتاريــخ ‪ 1431/04/18‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 3166610‬وتاريــخ ‪ 1431/04/14‬ه ـ ففــي يــوم االحــد املوافــق‬\n‫‪ 1432/03/10‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 : 44‬وفيهــا حضــر ‪........‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ .....‬بالوكالــة عــن ‪ ........‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جده برقم‬\n‫‪ 12261‬يف ‪1431/2/9‬ه ـ جلــد ‪ 9269‬وادعــى علــى احلاضــر معــه ‪........‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ ........‬بالوكالــة عــن ‪ ........‬مبوجب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم‬\n‫ا يف دعــواه عليــه إن موكلــي‬   ‫‪ 18987‬يف ‪1432/3/9‬ه ـ جلــد ‪ 4640‬قائـ ً‬\n‫اتفــق مــع مــوكل املدعــى عليــه علــى التعقيــب ومتابعــة يف موضوعــه‬\n‫املتعلــق بتالعــب بنــك ‪ ...‬بحســاباته اجلاريــة واالســتثمارية وبــذل قصــارى‬\n‫جهــده إلنهــاء املوضــوع كــون موكلــي رجــل أعمــال وحصــل هنــاك‬\n\n                                                                                   ‫‪228‬‬\n\f      ‫تالعــب مــن بنــك ‪ ........‬ووكل املدعــى عليــه أصالــة بإنهــاء مــا يتعلــق بهذا‬\n      ‫األمــر وقــد أتفــق موكلــي مــع مــوكل املدعــى عليــه علــى أن يدفــع لــه‬\n      ‫موكلــي مبلــغ مليونــن شــرط أن ينهــي مــوكل املدعــى عليــه املوضــوع‬\n      ‫ا وكذلــك بقــاء هــذا املبلــغ ضمانـ ًا حلــن اســترجاع أموالــه التــي‬   ‫كامـ ً‬\n      ‫مت االســتيالء عليهــا مــن حســابه يف أحــد البنــوك إال أن موكلــي تفاجــأ‬\n      ‫بقيــام مــوكل املدعــى عليــه بصــرف الشــيك دون إنهــاء مــا اتفــق عليــه‬\n      ‫لــذا أطلــب احلكــم علــى مــوكل املدعــى عليــه بإعــادة مــا اســتلمه مــن‬\n      ‫موكلــي مبلغ ـ ًا وقــدره مليونــا ريــال وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫وكالــة أجــاب بأنــي أطلــب إمهالــي للرجــوع إلــى موكلــي واإلفــادة يف‬\n      ‫اجللســة القادمــة لــذا رفعــت اجللســة ويف يــوم االثنــن ‪1432/06/06‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر الطرفــان وســألت املدعــى عليــه عــن‬\n      ‫جوابــه علــى الدعــوى فقــال إن جوابــي هــو مــا ذكــره املدعــي مــن طلــب‬\n      ‫موكلــي لــه يف التعقيــب عنــه فهــذا صحيــح حيــث إن املدعــي أصالــة‬\n      ‫طلــب مــن موكلــي أن ميثلــه يف التعقيــب واملرافعــة يف معاملتــه لــدى جلنــة‬\n      ‫املنازعــات املصرفيــة ضــد بنــك ‪ ...‬فطلــب منــه موكلــي قبــل أن يتفــق معه‬\n      ‫أن يكتــب لــه وكالــة لكــي يســتطيع مبوجبهــا معرفــة حقيقــة الدعــوى‬\n      ‫‪ .‬وبالفعــل كتــب لــه وكالــة برقــم (‪ ).....‬وتاريــخ ‪1430/3/21‬ه ـ مرفــق‬\n      ‫رقــم (‪ )1‬وعلــى ضــوء هــذه الوكالــة قــام موكلــي مبراجعــة اجلهــات‬\n      ‫املختصــة ملعرفــة حقيقــة هــذه الدعــوى ومالبســاتها وبقــي موكلــي‬\n      ‫مــدة وهــو يســأل عــن قضيــة املدعــي وبعــد أن عــرف قضيتــه أبلغــه أنــه‬\n      ‫ال مانــع لديــه مــن الســعي يف الدعــوى وحرصـ ًا مــن املدعــي قــام وكتــب‬\n      ‫لــه شــيك ًا مببلــغ مليونــي ريــال (‪ 2000.000‬ريــال) وأرســله ملوكلــي‬\n      ‫وطلــب مــن موكلــي عــدم صرفــه فكتــب لــه موكلــي إقــرار ًا موقع ـ ًا‬\n\n\n‫‪229‬‬\n\f‫منــه فقــط مؤرخ ـ ًا يف ‪1430/4/12‬ه ـ أنظــر مرفــق رقــم (‪ )2‬واشــترط‬\n‫عليــه موكلــي أنــه ال بــد مــن كتابــة اتفاقيــة حتــدد حقــوق كل منهمــا‬\n‫كمــا هــو متعــارف عليــه فوافــق املدعــي ثــم حضــر بعــد ثالثــة أيــام‬\n‫مــن إقــرار موكلــي املــؤرخ يف ‪1430/4/12‬ه ـ وكتبــا بينهمــا اتفاقيــة‬\n‫مؤرخــه يف ‪1430/4/15‬ه ـ املوافــق ‪2009/4/11‬م مرفــق (‪ )3‬موقعــة‬\n‫مــن املدعــي أصالــة بقلمــه وإبهامــه وكذلــك موكلــي ومــن ثالثــة شــهود‪.‬‬\n‫وعلــى ضــوء هــذه االتفاقيــة قــام موكلــي بصــرف الشــيك املمثــل للمبلــغ‬\n‫املدعــى بــه ألنــه جــاء يف هــذه االتفاقيــة بنــد (‪ )6‬أن ملوكلــي حــق صــرف‬\n‫الشــيك‪ .‬وموكلــي منــذ أن وقــع اتفاقــه مــع املدعــي بــل منــذ أن وكلــه لــم‬\n‫يألــو جهــد ًا يف كشــف احلقيقــة للمســئولني ومــن ذلــك علــى ســيبل املثــال‬\n‫ال احلصــر خطــاب موكلــي املوجــه لســعادة األمــن العــام للجنــة تســوية‬\n‫املنازعــات املصرفيــة املــؤرخ يف ‪1430/4/9‬ه ـ املوافــق ‪2009/4/5‬م‬\n‫مرفــق (‪)4‬ومنهــا اخلطــاب املــؤرخ يف ‪1430/4/24‬ه ـ مرفــق (‪ )5‬ومنهــا‬\n‫اخلطاب املؤرخ يف ‪1430/5/3‬هـ املوافق ‪2009/4/28‬م مرفق (‪ )6‬ومنها‬\n‫اخلطــاب املــؤرخ يف ‪1430/5/22‬ه ـ املوافــق ‪2009/5/17‬م مرفــق(‪)8-7‬‬\n‫وضـ َـح للمســئولني‬ ‫ومــن يتأمــل هــذا اخلطــاب يظهــر لــه أن موكلــي قــد ّ‬\n‫حقيقــة دعــوى موكلــه وج ـ ـ ـ ــاء يف الفقـ ـ ــرة (‪ )9‬مــن هــذا اخلط ـ ـ ــاب مــا‬\n‫نصــه ( ليصبــح إجمـ ـ ــالي مط ـ ـ ــالبتي للبنــك خمســة ماليــن وثالثمائــة‬\n‫واثنــان وثمانــون ألفـ ًا وخمســمائة وأربعــة ريــاالت وســبعة وعشــرون هللــه‬\n‫((‪ 5.382.504.27‬ريــال‪ .‬وهــذا يعتبــر مهــارة مــن موكلــي حيــث عـ ّـدل‬\n‫باســتدعائه هــذا الدعــوى التــي ســبق أن رفعــت مــن وكيــل املدعــى‬\n‫الــذي قبلــه أنظــر مرفــق (‪ )10-9‬حيــث جــاء يف الفقــرة (‪ )3‬منــه أن املبلــغ‬\n‫الــذي يطالــب بــه املدعــي ثالثــة ماليــن وثالثمائــة وثمانــون الفـ ًا وســتمائة‬\n\n\n                                                                                         ‫‪230‬‬\n\f      ‫وثالثــة وعشــرون ريــا ًال وســبعة وعشــرون هللــه (‪ .)3.380.623.27‬ألنــه‬\n      ‫اكتشــف مــا لــم يكشــفه غيــره بعــد اطالعــه علــى األوراق التــي تخــص‬\n      ‫املدعــي‪ .‬وقــد حضــر موكلــي اجللســة املنعقــدة بتاريــخ ‪1430/10/17‬ه ـ‬\n      ‫يف جلنــة تســوية املنازعــات حســبما يظهــر مــن خطــاب األمــن العــام‬\n      ‫ـاء علــى طلبــه رقــم (‪/578‬ل ت) وتاريــخ‬          ‫للجنــة املوجــه ملوكلــي بنـ ً‬\n      ‫‪1432/3/25‬ه ـ مرفــق (‪ )12-11‬وممــا يــدل علــى اهتمــام موكلــي‬\n      ‫أنــه أجــاب إلــى استفســار جلنــة تســوية املنازعــات التــي ُطلبــت منــه يف‬\n      ‫اجللســة املؤرخــة يف ‪1430/10/17‬ه ـ حيــث أجابهــم بخطابــه املــؤرخ يف‬\n      ‫‪1430/10/21‬ه ـ املوافــق ‪2009/10/10‬م مرفــق (‪ )14-13‬وممــا يــدل‬\n      ‫علــى اهتمــام موكلــي أنــه ُيطلــع موكلــه ( املدعــي) علــى كل مــا يقــوم‬\n      ‫بــه أو مــا يحتــاج إلــى استفســار حيــث كتــب لــه خطاب ـ ًا بعــد جلســة‬\n      ‫‪1430/10/17‬ه ـ أنظــر مرفــق (‪ .)15‬وممــا يــدل علــى رضــا املدعــي‬\n      ‫أصالــة عــن عمــل موكلــي مــا قالــه ابــن املدعــي (‪ )........‬حيــث قــال مــا‬\n      ‫نصــه «وقــد رضينــا رض ـ ًا تــام علــى مــا قــام بــه الوكيــل الشــرعي‪........‬‬\n      ‫مــن عمــل وجهــد يف متابعــة قضيــة املدعــو ‪ ........‬وقــد أعطينــاه الوقــت‬\n      ‫الــكايف حتــى تنتهــي القضيــة»‪ .‬أنظــر مرفــق (‪ )16‬ســطر (‪.)10-9‬‬\n      ‫وممــا يــدل علــى مواصلــة موكلــي لعملــه أنــه كتــب مذكــرة للجنــة‬\n      ‫تســوية املنازعــات املصرفيــة مؤرخــة يف ‪1430/12/26‬ه ـ املوافــق‬\n      ‫‪2009/12/13‬م أنظــر مرفــق (‪ .)17‬وعندمــا حضــر موكلــي للجلســة‬\n      ‫املؤرخــة يف ‪1431/1/2‬ه ـ تفاجــأ بأنــه جــرى فســخ وكالتــه بــدون أن‬\n      ‫ُيبلغــه املدعــي أو يتفاهــم معــه أو ُيبــن لــه وجــه القصــور أو الســبب‬\n      ‫احلامــل لــه علــى فســخ الوكالــة‪ .‬واملدعــي هــداه اهلل عمــل هــذا العمــل‬\n      ‫مــع محامــن ســابقني ملوكلــي حيــث فســخ وكاالتهــم أنظــر مرفــق‬\n\n\n‫‪231‬‬\n\f‫(‪ .)19-18‬أمــا مــا طلبــه مــوكل املدعــى مــن احلكــم علــى موكلــي‬\n‫بإعــادة مــا اســتلمه وقــدره مليونــا ريــال (‪ 2000.000‬ريــال) فموكلــي‬\n‫ال يوافــق علــى ذلــك ألنــه اســتحق هــذا املبلــغ منــذ أن وقــع االتفاقيــة مــع‬\n‫املدعــي املؤرخــة يف ‪1430/4/15‬ه ـ ومــن يطلــع علــى هــذه االتفاقيــة‬\n‫يظهــر لــه جلي ـ ًا أنهــا بعــد إقــرار موكلــي بعــدم صــرف الشــيك املــؤرخ‬\n‫يف ‪1430/4/12‬ه ـ ألن االتفــاق املوقــع عليــه مــن الطرفــن هــو األســاس‬\n‫يف التعامــل بينهمــا وهــو املتأخــر تاريخ ـ ًا ومــن املعلــوم أن املتأخــر ناســخ‬\n‫ملــا قبلــه الســيما أنــه جــاء يف البنــد (‪ )6‬منــه مــا نصــه « ويعتبــر اإلقــرار‬\n‫الــذي صــدر مــن الطــرف الثانــي يف ‪1430/4/12‬ه ـ ملغــي وال ميثــل أي‬\n‫شــيء بــن الطرفــن»‪ .‬مــع اإلحاطــة ان املدعــى وكالــة قــال يف دعــواه أن‬\n‫موكلــي رجــل أعمــال ومــن هــذه حالــه فهــو يعــرف معنــى االتفــاق ومــا‬\n‫يــدل عليــه وهــو ليــس بجاهــل بــل رجــل أعمــال وســبق أن فســخ وكالتــن‬\n‫لوكيلــن قبــل أن يكتــب الوكالــة ملوكلــي ومــن يعمــل هــذا ال بــد أنــه‬\n‫أخــذ حــذره وحيطتــه مــع مــن ســيتفق معــه وهــذا مــا عملــه مــع موكلــي‬\n‫حيــث لــم يكتفــي بالتوقيــع بــل طلــب التوقيــع بالقلــم واإلبهــام‪ .‬ومــن هــذا‬\n‫كلــه يظهــر أن موكلــي قــام بعملــه علــى الوجــه املطلــوب ولكــن ملــا‬\n‫ظهــر للمدعــي أن موكلــي ســار يف القضيــة ســير ًا صحيحـ ًا وتكشــفت‬\n‫حقائقهــا قــام بفســخ وكالتــه لكــي ال يطالبــه بنســبة ال ـ ـ ـ (‪) %20‬‬\n‫يف املئــة املتفــق عليهــا يف العقــد املوقــع عليــه بينهمــا مرفــق (‪ )3‬فقــرة‬\n‫(‪ )4‬وموكلــي يحتفــظ بحقــه بإقامــة الدعــوى بهــذه النســبة ‪ .‬أطلــب‬\n‫صــرف النظــر عــن دعــوى املدعــي وتكليــف املدعــي بأجــرة احملامــاة‬\n‫التــي خســرها موكلــي وقدرهــا مئتــان ألــف ريــال (‪ 200.000‬ريــال)‬\n‫هــذه إجابتــي وبعــرض ذلــك علــى املدعــي وكالــة قــال أطلــب تزويــدي‬\n\n\n                                                                                         ‫‪232‬‬\n\f      ‫نســخة مــن رد املدعــى عليــه حتــى امتكــن مــن الــرد عليــه يف اجللســة‬\n      ‫القادمــة وجــرى تزويــده بنســخة مــن رد املدعــى عليــه وكالــة ومرفقاتــه‬\n      ‫ورفعــت اجللســة ثــم لــدي أنــا ‪ ........‬املكلــف بعمــل املكتــب رقــم (‪ )3‬لــدى‬\n      ‫فضيلــة الشــيخ ‪ ........‬القاضــي يف احملكمــة العامــة بالريــاض مبوجــب‬\n      ‫خطــاب فضيلــة رئيــس احملكمــة رقــم ‪ 32/823650‬يف ‪1432/7/4‬ه ـ‬\n      ‫ففــي يــوم االربعــاء ‪1432/7/6‬ه ـ افتتحــت اجللســة الســاعة ‪ 9:30‬وفيهــا‬\n      ‫حضــر الطرفــان وبقــراءة مــا مت ضبطــه ســابقا صادقــا عليــه وبســؤال‬\n      ‫املدعــي وكالــة عــن جوابــه عــن جــواب املدعــى عليــه وكالــة قــال جوابــه‬\n      ‫لــم يالقــي الدعــوى هكــذا قــال وعلــى هــذا رفعــت اجللســة للتأمــل ثــم‬\n      ‫لــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة بالريــاض ويف يــوم الســبت‬\n      ‫املوافــق ‪ 1432/11/3‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 12‬وفيهــا حضــر‬\n      ‫املدعــى عليــه وكالــة ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬ولــم‬\n      ‫يحضــر املدعــي وال مــن ينــوب عنــه بوكالــة شــرعيه وفيهــا قــدم املدعــي‬\n      ‫عليــه وكالــه ردا مــن ورقتــن ضمــت بأصــل املعاملــة ونصهــا ومضمونهــا‬\n      ‫قائــا يف رده علــى إجابــة املدعــي يف اجللســة املاضيــة مــن أن إجابتــي‬\n      ‫غيــر مالقيــة لدعــواه ‪ .‬أجيــب عــن ذلــك بــأن إجابتــي مالقيــة وبصــورة‬\n      ‫وافيــة لدعــواه فهــو ذكــر يف دعــواه مــا نصــه (ثاني ـاً) إلــزام املدعــى‬\n      ‫عليــه ‪ ........‬بالتضامــن مــع أعوانــه املذكوريــن بــرد مــا اســتولوا عليــه‬\n      ‫مــن مبالــغ مــن موكلــي وقدرهــا مليونــا ريــال (‪ 2.000.000‬ريــال) دون‬\n      ‫وجــه حــق واحلكــم بذلــك) وموكلــي هــو الــذي اســتلم املبلــغ مــن املدعــي‬\n      ‫أصالــة ووضحــت يف إجابتــي بصــورة مفصلــه ســبب اســتالم موكلــي‬\n      ‫لهــذا املبلــغ ومــن هــذا يتضــح أن إجابتــي مالقيــة للدعــوى‪ .‬ثــم حضرنــا‬\n      ‫اجللســة املاضيــة بتاريــخ ‪1432/8/2‬ه ـ ولــم يقــدم املدعــي شــيئاً‪ .‬وما عدم‬\n\n\n‫‪233‬‬\n\f‫حضــور املدعــي جللســة هــذا اليــوم إ ّال لعلمــه بعــدم أحقيــة موكلــه لهــذه‬\n‫الدعــوى‪ .‬ولــو كان لديــه شــيء لقدمــه إذ ليــس مــن املعقــول أن يتــرك‬\n‫دعــواه يف هــذا املبلــغ الكبيــر لــو كان لديــه بينــة‪ .‬صاحــب الفضيلــة‬\n‫إن املدعــي ذكــر ان مســتنده هــو االتفــاق بــن موكلــه وموكلــي وأن‬\n‫موكلــه قــام بتوقيــع عــدة مســتندات كمــا جــاء يف صفحــة الدعــوى‬\n‫ا علــى دعــواه يف مذكرتــي املعطــى‬       ‫أخــر ســطر(‪ )3‬وقــد أجبــت تفصيـ ً‬\n                                                ‫للمدعــي وكالــة صــورة منهــا ‪.‬‬\n‫وموكلــي لــم يأتــي بجديــد يف رده علــى دعــوى املدعــي وإمنــا قــام‬\n‫بتوضيــح االتفــاق الــذي وقعــه مــع املدعــي أصالــة وكــذا قــام بتوضيــح‬\n‫العمــل الــذي قــام بــه ألن املدعــي قــال يف دعــواه (أنــه اســتولى عليــه‬\n‫دون وجــه حــق) الســطر األخيــر مــن صحيفــة الدعــوى‪ .‬ومــن هــذا كلــه‬\n‫يتضــح أن املدعــي قــدم جميــع مــا لديــه مــن مســتندات وألن املــادة ( ‪)54‬‬\n‫مــن نظــام املرافعــات الشــرعية نصــت علــى انــه ( إذا حضــر املدعــى عليــه‬\n‫يف اجللســة التــي غــاب عنهــا املدعــي فلــه أن يطلــب مــن احملكمــة عــدم‬\n‫شــطب الدعــوى واحلكــم يف موضوعهــا إذا كانــت صاحلــة للحكــم‬\n‫فيهــا) وهــذه القضيــة صاحلــة للحكــم فيهــا‪ .‬ألنــه لــم يبــق للمدعــي مــا‬\n‫يقدمــه إذ لــو كان لديــه شــيء لقدمــه يف هــذه اجللســة‪ .‬وكــذا املــادة‬\n‫( ‪ 84‬و ‪ )85‬مــن نظــام املرافعــات الشــرعية فيهــا إذا تهيــأت الدعــوى‬\n‫للحكــم فــا تنقطــع اخلصومــة وعلــى احملكمــة احلكــم فيهــا وتعــد‬\n‫الدعــوى مهيــأة للحكــم إذا أبــدى اخلصــوم أقوالهــم وطلباتهــم اخلتاميــة‬\n‫يف جلســة املرافعــة‪ .‬لــذا أطلــب احلكــم يف القضيــة وصــرف النظــر يف‬\n‫الدعــوى هــذه إجابتــي عنــد ذلــك رفعــت اجللســة للتأمــل يف يــوم الثالثــاء‬\n‫املوافــق‪ 1433/04/20‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 12‬وفيهــا‬\n\n\n                                                                                    ‫‪234‬‬\n\f      ‫حضــر املدعــي وكالــة ‪ ........‬ســعودي مبوجــب الســجل املدنــي رقــم ‪........‬‬\n      ‫بالوكالــة عــن ‪........‬واملدونــة وكالتــه ســابق ًا كمــا حضــر حلضــوره‬\n      ‫املدعــى عليــه وكالــة ‪........‬مبوجــب الســجل املدنــي رقــم ‪........‬بالوكالــة‬\n      ‫عــن ‪........‬واملــدون وكالتــه أعــاه وقــدم املدعــي وكالــة ردا مــن ورقــة‬\n      ‫واحــدة جــرى ضمهــا باملعاملــة ونصهــا افيــد فضيلتكــم بــأن مــا ذكــره‬\n      ‫املدعــى عليــه غيــر صحيــح كونــه اســتدرج موكلــي للريــاض وغــرر‬\n      ‫بــه للتوقيــع علــى االتفاقيــة بينهمــا مخالفــة ألصــل العقــد والــذي يتعهــد‬\n      ‫فيــه بعــدم صــرف مبلــغ شــيك وان يبقــى لديــه ضمــان حلــن اجنــاز مــا‬\n      ‫اوكل اليــه اال انــه بعــد ان احضــره للريــاض ونظــرا لكبــر ســنه حيــث‬\n      ‫يبلــغ خمســة وثمانــون عامــا دون ان يعلــم موكلــي مــا اضمــره املدعــى‬\n      ‫عليــه مــن احتيــال لتحصيــل الشــيك دون وجــه حــق وقبــل بــدء العمــل‬\n      ‫وممــا يثبــت التغريــر واالســتدراج والغــن ان مطالبــة موكلــي التــي تقــدم‬\n      ‫بهــا املدعــى عليــه امــام جلنــة تســوية املنازعــات املصرفيــة مببلــغ خمســة‬\n      ‫ماليــن ريــال فقــط فكيــف يســتحق مقــدم اتعــاب مبلــغ مليونــي ريــال‬\n      ‫واملطالبــة هــي مــا ذكــر كمــا يثبــت ذلــك ان املدعــى عليــه ادعــى بأنــه‬\n      ‫يعمــل محامــي للخصــم يف مثــل هــذه الدعــاوى علــى عكــس احلقيقــة‬\n      ‫لــذا اطلــب احلكــم علــى املدعــى عليــه بــرد مبلــغ وقــدره مليونــي ريــال‬\n      ‫ملوكلــي لعــدم اســتحقاقه لذلــك املبلــغ لقولــه جــل وعــا ( وال تأكلــوا‬\n      ‫أموالكــم بينكــم بالباطــل ) اآليــة وبعرضهــا علــى املدعــى عليــه وكالــة‬\n      ‫اجــاب ليــس لــدي زيــادة علــى مــا قدمــت واكتفــي بــه هــذه اجابتــي عنــد‬\n      ‫ذلــك قــرر املدعــي وكالــة بأنــي اكتفــي بحصــر دعــوى موكلــي ضــد‬\n      ‫املدعــى عليــه ‪ ........‬كونــه هــو مــن أجــرى االتفــاق مــع موكلــي فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة والن املدعــى عليــه وكالــة صــادق‬\n\n\n‫‪235‬‬\n\f‫علــى بعــض دعــوى املدعــي وكالــة وانكــر البعــض ونظــرا للعقــد املبــرم‬\n‫بــن املتداعيــن اصالــة وفيــه مــا نصــه توقيــع الطرفــن علــى هــذا العقــد‬\n‫يعتبــر الشــيك املوضــح يف البنــد رقــم (‪ )3‬حــق مــن حقــوق الطــرف الثانــي‬\n‫لــه احلــق يف صرفــه دون الرجــوع للطــرف األول وال يحــق للطــرف األول‬\n‫أو الحــد مــن طرفــه املطالبــة بهــذا الشــيك بــأي حــال وألن هــذا الشــرط‬\n‫نــص يف النــزاع ولقولــه تعالــى « يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود «‬\n‫وألن األصــل يف العقــود الصحــة وال يصــار إلــى ابطالهــا إال إذا اشــتملت‬\n‫علــى مــا ينــايف مقتضــى العقــود وملطالبــة املدعــى عليــه وكالــة بأجــرة‬\n‫احملامــاة مبلغ ـ ًا وقــدره مئتــا ألــف ريــال لــذا فقــد حكمــت بــرد دعــوى‬\n‫املدعــي وكالــة وعــدم اســتحقاق موكلــه ملــا يدعيــه كمــا حكمــت‬\n‫بإلــزام مــوكل املدعــي بدفــع مبلــغ وقــدره مئتــا ألف ريال ملــوكل املدعى‬\n‫عليــه أتعابـ ًا للمحامــاة وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليه‬\n‫وكالــة القناعــة بــه أمــا املدعــي وكالــة فقــرر عــدم قناعتــه باحلكــم‬\n‫وطلــب االســتئناف فأجيــب لطلبــه وجــرى تســليمه نســخة مــن احلكــم‬\n‫لتقــدمي االعتــراض عليــه خــال مــدة ثالثــن يومـ ًا وان لــم يقــدم اعتراضــه‬\n‫خاللهــا ســقط حقــه يف االســتئناف واكتســب احلكــم الصفــة القطعيــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                           ‫وســلم ‪ .‬حــرر يف ‪ 1433/04/20‬ه ـ‬\n‫احلمــد هلل وحــده ففــي يــوم األحــد املوافــق‪ 1433/11/21‬ه ـ افتتحــت‬\n‫اجللســة الــس‪ : 08‬وفيهــا حضــر املدعــى عليــه وكالــة ‪ ........‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬بالوكالــة عــن ‪ ........‬واملــدون‬\n‫ا عنــه وقــد وردت املعاملــة‬ ‫وكالتــه أعــاه ولــم يحضــر املدعــي او وكيـ ً‬\n‫مــن رئيــس محكمــة االســتئناف برقــم ‪ 331056932‬يف ‪1433/8/6‬ه ـ‬\n\n\n                                                                                      ‫‪236‬‬\n\f      ‫ومرفــق بــه القــرار رقــم ‪ 33334042‬يف ‪1433/7/9‬ه ـ واملتضمــن‬\n      ‫مالحظــة أصحــاب الفضيلــة حفظهــم اهلل مــا يلــي أو ًال ‪ :‬وجــد أن‬\n      ‫فضيلتــه لــم يطلــب العقــد املبــرم بــن الطرفــن ويطلــع عليــه ويرصــد‬\n      ‫مضمونــه بالضبــط والصــك وال بــد مــن ذلــك ثانيـ ًا ‪ :‬لــم يتحقــق فضيلتــه‬\n      ‫مــن اســتحقاق املدعــى عليــه للمبلــغ املدعــى بــه حســب االتفــاق املبــرم‬\n      ‫بينهمــا ملالحظــة مــا ذكــر وباإلجابــة علــى مالحظــة أصحــاب الفضيلــة‬\n      ‫أقــول وبــاهلل التوفيــق فقــد جــرى منــا االطــاع علــى العقــد املبــرم بــن‬\n      ‫الطرفــن وجــرى رصــد مضمونــه وهــذا نصــه « بســم اهلل الرحمــن‬\n      ‫الرحيــم التاريــخ ‪1430/4/15‬ه ـ املوافــق ‪2009/4/11‬م عقــد اتفاقيــة‬\n      ‫انــه يف يــوم الســبت ‪1430/4/15‬ه ـ املوافــق ‪2009/4/11‬م مت االتفــاق‬\n      ‫بعــون اهلل بــن كل مــن ‪ /1‬الســيد ‪........‬ويشــار إليــه فيمــا بعــد بالطــرف‬\n      ‫األول ‪ /2‬الســيد ‪ ........‬ويشــار اليــه فيمــا بعــد بالطــرف الثانــي حيــث‬\n      ‫ان للطــرف األول قضيــة تنحصــر بتالعــب بنــك ‪ ...‬يف حســاباته اجلاريــة‬\n      ‫واالســتثمارية وحيــث قبــل الطــرف الثانــي القيــام عــن الطــرف األول يف‬\n      ‫التعقيــب ومتابعــة القضيــة يف جميــع الدوائــر احلكوميــة ذات العالقــة‬\n      ‫ومنهــا وال تقتصــر علــى مؤسســة النقــد وجلانهــا واإلمــارة واحملاكــم‬\n      ‫ووزارة الداخليــة واألمــن العــام وبنــك ‪ ........‬قــد اتفقــا علــى مــا يلــي ‪/1 :‬‬\n      ‫مقدمــة هــذا العقــد جــزء ال يتجــزأ مــن هــذه االتفاقيــة ‪ /2‬يلتــزم الطــرف‬\n      ‫الثانــي ببــذل قصــارى جهــده يف متابعــة هــذه القضيــة بالتعــاون املبــذول‬\n      ‫مــن قبــل الطــرف األول ‪ /3‬اصــدار الطــرف األول شــيك مصــريف رقــم‬\n      ‫‪ 998100‬يف ‪2009/4/7‬م بقيمــة ( ‪ ) 2000,000‬ريــال علــى البنــك ‪........‬‬\n      ‫لصالــح الطــرف الثانــي مقابــل اتعابــه يف التعقيــب علــى قضيــة الطــرف‬\n      ‫املوضحــة يف مقدمــة هــذا العقــد ‪ /4‬يف حــال اســتطاع الطــرف الثانــي‬\n\n\n‫‪237‬‬\n\f‫تكليــف بنــك ‪ ........‬بدفــع غرامــة ماليــة جزائيــة ملــا قامــوا بــه مــن تالعــب‬\n‫يف حســابات الطــرف األول أو اســتطاع تكليفهــم بإعــادة أربــاح أو‬\n‫خســائر الطــرف األول يف حســاباته االســتثمارية واجلاريــة فــأن للطــرف‬\n‫الثانــي نســبة قدرهــا ( ‪ ) % 20‬مــن هــذا املبلــغ تضــاف إلــى قيمــة أتعابــه‬\n‫املوضحــة يف البنــد ( ‪ /5 ) 3‬تنتهــي مســئوليات الطــرف الثانــي أمــام‬\n‫الطــرف األول مــع اســتحقاقه جميــع حقوقــه املبينــة يف هــذا العقــد عنــد‬\n‫بــت جلنــة املنازعــات املصرفيــة أو إذا اســترجع بنــك ‪ ........‬حقــوق الطــرف‬\n‫األول مباشــرة أو عــن طريــق الصلــح أو عنــد إخــال الطــرف األول يف‬\n‫هــذه االتفاقيــة كقيامــة بفســخ وكالــة الطــرف الثانــي أو توكيــل غيره‬\n‫قبــل نهايــة هــذه القضيــة ‪ /6‬بتوقيــع الطرفــن علــى هــذا العقــد يعتبــر‬\n‫الشــيك املوضــح يف البنــد رقــم ( ‪ ) 3‬حــق مــن حقــوق الطــرف الثانــي‬\n‫لــه حــق صرفــه دون الرجــوع للطــرف األول وال يحــق للطــرف األول أو‬\n‫ألحــد مــن طرفــه املطالبــة بهــذا الشــيك بــأي حــال ويعتبــر االقــرار الــذي‬\n‫صــدر مــن الطــرف الثانــي يف ‪1430/4/12‬ه ـ ملغــى وال ميثــل أي شــيء‬\n‫بــن الطرفــن واهلل املوفــق الطــرف األول ‪........‬توقيعــه وبصمتــه الطــرف‬\n‫الثانــي ‪........‬توقيعــه وبصمتــه الشــاهد األول ‪........‬وتوقيعــه والشــاهد‬\n‫الثانــي ‪........‬وتوقيعــه والشــاهد الثالــث ‪........‬وتوقيعــه « أه ـ وباإلجابــة‬\n‫علــى املالحظــة الثانيــة أجيــب أصحــاب الفضيلــة انــه باالطــاع علــى‬\n‫العقــد املبــرم بــن الطرفــن الفقــرة اخلامســة ونصهــا « تنتهــي مســئوليات‬\n‫الطــرف الثانــي أمــام الطــرف األول مــع اســتحقاقه جميــع حقوقــه املبينــة‬\n‫يف هــذا العقــد عنــد بــت جلنــة املنازعــات املصرفيــة أو إذا اســترجع بنــك‬\n‫‪ ......‬حقــوق الطــرف األول مباشــرة أو عــن طريــق الصلــح أو عنــد إخــال‬\n‫الطــرف األول يف هــذه االتفاقيــة كقيامــة بفســخ وكالــة الطــرف‬\n\n\n                                                                                         ‫‪238‬‬\n\f      ‫الثانــي أو توكيــل غيــره قبــل نهايــة هــذه القضيــة « وألن مــوكل املدعــي‬\n      ‫قــام بفســخ الوكالــة مبــا يخالــف مقتضــى العقــد فقــد اســتحق املدعــى‬\n      ‫عليــه املبلــغ املدعــى بــه وعليــه ليــس لــدي ســوى مــا حكمــت بــه واغلقــت‬\n      ‫اجللســة يف متــام الســاعة ‪ 44:08‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بالرياض‪/‬املســاعد برقــم ‪ 2156931‬وتاريــخ‬\n      ‫‪ 1434/01/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3428802‬وتاريــخ‬\n      ‫‪ 1434/01/06‬ه ـ ففــي يــوم األربعــاء املوافــق ‪ 1434/01/14‬ه ـ افتتحت‬\n      ‫اجللســة الســاعة ‪ 08،06‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالريــاض مرفــق بهــا قرارهــم ‪ 33477343‬يف ‪1433/12/25‬هـ املتضمن‬\n      ‫قولهــم جــواب فضيلــة القاضــي علــى املالحظــة الثانيــة من القرار الســابق‬\n      ‫ال يكفــي ‪ ،‬الن العقــد املوقــع بــن الطرفــن ال يتجــزأ ثانيــا ‪ -:‬لم يذكر‬\n      ‫فضيلتــه مســتنده علــى إلــزام املدعــي بدفــع مائتــي الــف ريــال للمدعــى‬\n      ‫عليــه أجــرة اتعــاب احملامــاة ‪ .‬وعليــه أجيــب اصحــاب الفضيلــة مشــايخنا‬\n      ‫الفضــاء أجيــب عــن امللحوظــة األولــى أنــه ال يســلم يف كل حــال عــدم‬\n      ‫جتزئــة العقــود فمتــى حصــل نقــص الحــد شــروط العقــد نقــص كلــه‬\n      ‫الن نقــص البعــض نقــص للــكل وإال ملــا صــار للعقــود والشــروط فيهــا‬\n      ‫أي حجــة وأجيــب عــن املالحظــة الثانيــة أن املدعــى عليــه قــدم وكالــة‬\n      ‫صــادرة مــن كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 3448913‬يف‬\n      ‫‪1434/1/13‬ه ـ ونصهــا مــا يلــي ‪ ( :‬وقــد مت االقــرار بتوكيــل ‪ ........‬فيمــا‬\n      ‫يخــص املطالبــات واحملاكــم وذلــك بالتنــازل بشــأن القضيــة املرفوعــة‬\n      ‫بخصــوص مطالبتــي ل ‪ ........‬يف أتعــاب احملامــاة وقدرهــا مئتــا ألــف ريــال‬\n\n\n‫‪239‬‬\n\f‫ومراجعــة جميــع اجلهــات ذات العالقــة وإنهــاء جميــع اإلجــراءات الالزمــة‬\n‫والتوقيــع فيمــا يتطلــب ذلك)‪.‬ا‪.‬ه ـ وعليــه رجعــت عمــا حكمــت بــه مــن‬\n‫إلــزام مــوكل املدعــي بدفــع مبلــغ وقــدره مائتــا ألــف ريــال للمدعــى‬\n‫عليــه أجــرة للمحامــاة وليــس لــدي ســوى مــا حكمــت بــه ســائال املولــى‬\n‫جــل وعــا ألصحــاب الفضيلــة مشــايخنا الكــرام التوفيــق والســداد ‪.‬‬\n‫وأغلقــت اجللســة الســاعة ‪ 08،10‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/14‬ه ـ‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3434009‬وتاريــخ‬\n                                             ‫‪ 1434/12/25‬ه ـ‬\n\n\n\n\n                                                                                ‫‪240‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"6cb1008d-3a95-574c-9ead-e0af920e44c3","source_page_start":227,"source_page_end":240,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0dcb22d91c490c7afb9651acbc6dcf29b9649bc41476178b4edfa84bef4b79fb","normalized_text_hash":"34cef6a374bd2ba8996af30c87bf2ba790de5f53f8e10b375e9a8bfce1b368f2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v8-p227-33204853"}]$archive_payload$::jsonb) AS x LIMIT 25
